	-- 贫瘠之地: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "阿迦玛戈",
			short = "阿迦玛戈位于陶拉祖营地向西延伸的道路以北，是一片被鬃背野猪人占据的荆木迷宫。",
			full = "阿迦玛戈位于陶拉祖营地向西延伸的道路以北，是一片被鬃背野猪人占据的荆木迷宫。它们的死者会留下干涸血液的碎片，流亡者碎牙十分珍视这些信物，并用他自己那些奇特的恩惠来交换它们。",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "巴尔莫丹",
			short = "巴尔丹城堡的石头要塞耸立在一座石塔牛头人村庄的旧址上。",
			full = "巴尔丹城堡的石头要塞耸立在一座石塔牛头人村庄的旧址上。在它下方，矮人挖掘者们正朝着一座古老的泰坦建筑群挖去，那是一座研究设施，早在牛头人踏上这片土地之前就已被掩埋，其中的遗物大多仍沉睡在黑暗中，无人认领。\n\n矮人们带着炸药而来，炸开了石塔部族视为神圣的土地。挖掘撕裂了大地，也撕裂了牛头人，部族中的大多数人或被杀死，或被赶出了他们世代守护的土地。他们昔日的村庄如今已被矮人的挖掘机器撕得千疮百孔。至今仍在附近道路上行走的加恩·石塔，曾试图以一位首领对另一位首领的身份解决此事，以对话代替战斗。矮人们却不肯放弃挖掘。于是他从外交转向了战争，寻求一切能找到的力量将他们赶走。",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
