			full = "莫尔杉壁垒矗立在黄金之路向北离开贫瘠之地的地方，是为了抵御联盟从灰谷发起的进攻而建的一道城墙。它是一座为战争而建的简陋工事：土垒和瞭望塔，用以抵挡从北方压来的敌军，守住防线。",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "迅猛龙巢穴",
			short = "遍布这座小山谷的日鳞迅猛龙与贫瘠之地的其他迅猛龙都不一样。它们表现出一种不同寻常的狡猾，会建造简陋的小屋，还会用本不该懂得手艺的爪子制作工具。",
			full = "遍布这座小山谷的日鳞迅猛龙与贫瘠之地的其他迅猛龙都不一样。它们表现出一种不同寻常的狡猾，会建造简陋的小屋，还会用本不该懂得手艺的爪子制作工具。\n\n更奇怪的是，它们对任何闪亮或陌生的东西都充满了渴望，这驱使它们袭击附近部落的定居点，把任何吸引它们目光的东西都拖走。",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "棘齿城",
			short = "棘齿城坐落在贫瘠之地的东海岸，是一座地精港口小镇，与海对面的藏宝海湾和大财主里维加兹进行着兴旺的贸易。",
			full = "棘齿城坐落在贫瘠之地的东海岸，是一座地精港口小镇，与海对面的藏宝海湾和大财主里维加兹进行着兴旺的贸易。加兹鲁维用萨尔为建造奥格瑞玛而付给他的钱建立了这座城镇，这里后来聚满了走私者，以及其他所有被体面地方拒之门外的人。\n\n这种来者不拒的态度几乎让它付出了惨重的代价。火刃邪教暗中挑拨奥格瑞玛和塞拉摩之间的关系，在棘齿城的港口附近制造了一系列航运事件，而双方都只把这些事件当作挑衅。曾在码头上和平共处的兽人和人类水手开始在街头斗殴，当打手穆兹克兰克逮捕了克拉特船长和乔克船长时，北方城堡将此视为兽人正在集结准备开战的证据。棘齿城成了一支准备向他们进军的部落军队的集结地。直到火刃氏族在此事中的黑手暴露出来，萨尔才在战斗打响之前将其叫停。",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "战士之魂神殿",
			short = "一条被踩得光秃的小路爬上十字路口以西的一座山丘，尽头是一座供奉一位阵亡战士的神殿。那里没有刻下名字，也没有旗帜作为标记。",
			full = "一条被踩得光秃的小路爬上十字路口以西的一座山丘，尽头是一座供奉一位阵亡战士的神殿。那里没有刻下名字，也没有旗帜作为标记。山丘保持着它的沉默，而通往山顶的小路是唯一的迹象，表明仍有人记得。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "淤泥沼泽",
			short = "淤泥沼泽并非从来就是大地上的一道伤口。这里曾有一汪水晶般湛蓝的池水，直到风险投资公司到来，在上面架起了一座石油钻井。",
			full = "淤泥沼泽并非从来就是大地上的一道伤口。这里曾有一汪水晶般湛蓝的池水，直到风险投资公司到来，在上面架起了一座石油钻井。如今剩下的只有一片工业废料形成的泥沼，在一名地精主管的监督下运作，他为这里的作业向公司负责。\n\n这座钻井招来了竞争对手，也污染了池水。棘齿城的工匠协会在瑞德沃克斯主管的催促下，要赶上风险投资公司那些新式的伐木机，他们放弃了在制造上与对方一较高下，转而决定直接窃取设计。地精斯布特瓦夫派维兹格朗克从沼泽中夺取一台机器，把它运回棘齿城。维兹格朗克好不容易才爬进伐木机，却发现自己根本没有启动它的钥匙，只好被困在敌人的地盘上，直到救援赶到，才得以在公司工人的眼皮底下把机器开了出去。",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "南黄金之路",
			short = "南黄金之路得名于在路上往来的商队。",
			full = "南黄金之路得名于在路上往来的商队。它从贫瘠之地南缘的巨型升降梯出发，向北延伸到连接贫瘠之地南北两半的桥梁，在那里便成了普通的黄金之路。\n\n商人们从遥远的地方来到这条路上：来自塔纳利斯的加基森，来自黑海岸的奥伯丁，来自北方的永夜港。他们都沿着同一条路而来，被赋予这条路名字的同一种贸易所吸引。",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "怒水河",
			short = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。",
			full = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。从那里开始，它奔流得又宽又急，将大地一分为二：它标志着灰谷与艾萨拉的分界，再往南，又是贫瘠之地的尽头和杜隆塔尔的起点。在入海口，河水从最后一道瀑布上奔腾而下，注入无尽之海，那里就在地精港口棘齿城的东北方。\n\n河上架着三座桥，一座连接艾萨拉与灰谷，一座载着旅人进入奥格瑞玛，还有一座连接杜隆塔尔与贫瘠之地。就在最西边那座桥的北面，有一段水域同时触及四片土地，那是灰谷、艾萨拉、杜隆塔尔和贫瘠之地唯一的交汇之处。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "死水绿洲",
			short = "死水绿洲是商旅海岸与黄金之路之间的一片静止的绿色水域。科卡尔半人马在它的周边扎营，据说他们的存在与活力正是来自这潭死水。",
			full = "死水绿洲是商旅海岸与黄金之路之间的一片静止的绿色水域。科卡尔半人马在它的周边扎营，据说他们的存在与活力正是来自这潭死水。在这里游荡的科多兽虚弱而孤单，不像南方巨人旷野上的庞大兽群，因而更容易成为猎物。变异鱼在水面下游弋，烹熟之后颇受珍视，而绿洲钳嘴龟则与它们一同潜伏在浑水之中。",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "荆棘岭",
			short = "荆棘岭坐落在十字路口与杜隆塔尔之间一座山顶的北坡上，山坡上到处都是钢鬃部族的野猪人。",
			full = "荆棘岭坐落在十字路口与杜隆塔尔之间一座山顶的北坡上，山坡上到处都是钢鬃部族的野猪人。它们从这处高地出击，袭击途经此地的部落商队，激起了守卫下方道路的人们的愤怒。",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "提度斯阶梯",
			short = "提度斯阶梯是商旅海岸上方一连串宽阔的石阶平台，层层叠叠，宛如巨人的阶梯，俯瞰着海面。",
			full = "提度斯阶梯是商旅海岸上方一连串宽阔的石阶平台，层层叠叠，宛如巨人的阶梯，俯瞰着海面。两位牛头人，水之先知伊斯伦和玛伦·星眼，常驻在这些岩台上，向浪花中抛下钓线，与栖身于下方水中的灵魂交谈。",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "哀嚎洞穴",
			short = "哀嚎洞穴得名于这里本身的声响：蒸汽从岩石的裂缝中喷涌而出，在黑暗中化作悠长而哀怨的呼号。",
			full = "哀嚎洞穴得名于这里本身的声响：蒸汽从岩石的裂缝中喷涌而出，在黑暗中化作悠长而哀怨的呼号。\n\n发现这些洞穴并赋予它们使命的，是暗夜精灵德鲁伊纳拉雷克斯。草原之下流淌着地下水道，它们在别处涌出地面，形成了贫瘠之地上星罗棋布的绿洲。纳拉雷克斯相信，只要将这些水与翡翠梦境本身相连，他就能把那股翠绿的生机重新注入上方干涸的土地。他带领信徒们深入洞穴，开始冥想，将自己化作梦境与现实世界之间的通道。\n\n然而翡翠梦魇攫住了他。纳拉雷克斯再也无法醒来。梦魇的腐化通过他那敞开的沉睡之躯涌入洞穴，污染了水源，将野生动物扭曲成怪异的变异形态，还将他的大多数信徒逼疯了，留下来的那些人成了尖牙德鲁伊。\n\n纳拉雷克斯至今仍在那里沉睡，而尖牙德鲁伊则占据着洞穴，阻挡任何想要唤醒他的人。",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- 奥特兰克山脉: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "达拉然",
			short = "达拉然作为一座法师之城而崛起，由阿拉索帝国的巫师们在巨魔战争之后建立，后来自成一国。",
			full = "达拉然作为一座法师之城而崛起，由阿拉索帝国的巫师们在巨魔战争之后建立，后来自成一国。这里的人民不效忠于任何王冠，只听命于肯瑞托，那是由世上最强大的施法者组成的精英议会，由六人议会统领。城市的中心矗立着紫罗兰城堡，那是研习奥术之人的圣所与避风港，除了精灵的国度奎尔萨拉斯之外，再没有哪座城市汇聚着如此强大的魔法力量。就连奎尔萨拉斯那些高傲的高等精灵法师，也要向肯瑞托的主权低头。\n\n那份主权在烈火中被打碎了。当天灾军团进攻达拉然时，它的人民被逐出了自己的国度，阿克蒙德亲手将城市化为废墟，肯瑞托的幸存成员也四散到艾泽拉斯各地。\n\n幸存者们没有让他们的城市就此死去。他们回到废墟之中，着手重建，并升起一座巨大的魔法穹顶，守护这座城市破碎的心脏免遭进一步的伤害。",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "达伦德农场",
			short = "一座小农场和庄园坐落在高地的西部边缘，那里的土地与雾气湖岸相接，还有一座港口通向洛丹米尔湖。",
			full = "一座小农场和庄园坐落在高地的西部边缘，那里的土地与雾气湖岸相接，还有一座港口通向洛丹米尔湖。\n\n奥里登就住在这里，与他同住的还有他的情妇艾丽萨。她戴着一条曾经属于塔蕾莎·福克斯顿的项链。",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "洛丹米尔收容所",
			short = "洛丹米尔收容所坐落在达拉然陨坑上方的一座山丘上，是奥特兰克山脉中唯一的一座收容所，由达拉然的军队看守。",
			full = "洛丹米尔收容所坐落在达拉然陨坑上方的一座山丘上，是奥特兰克山脉中唯一的一座收容所，由达拉然的军队看守。\n\n阿尔萨斯·米奈希尔王子和吉安娜·普罗德摩尔女士在前往达拉然的途中，曾趁着夜色溜过巡逻的卫兵和瞭望塔，来这里看一看关在其中的兽人。他们所见的一切让两人产生了分歧。吉安娜看着那些兽人妇女和她们的孩子，内心的笃定动摇了，化为怀疑与懊悔。阿尔萨斯却丝毫不为所动，坚持认为无论如何这些收容所都是必要的。没有人发现他们。他们原路返回，而两人之间的分歧也随之被带走了。\n\n如今，典狱官贝拉摩尔指挥着这里的守军，研究着凯甘·达玛尔和他的同伴们交给她的血石神器。",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "奥特兰克废墟",
			short = "残破的城墙沿着奥特兰克山脉的山坡攀升，那里曾矗立着一座城市，如今宫殿半塌，教堂和市政厅都已向内坍塌，只有城门依然保留着与暴风城的城门相同的样式。",
			full = "残破的城墙沿着奥特兰克山脉的山坡攀升，那里曾矗立着一座城市，如今宫殿半塌，教堂和市政厅都已向内坍塌，只有城门依然保留着与暴风城的城门相同的样式。\n\n它的毁灭源自它自己的国王。第二次战争期间，艾登·匹瑞诺德国王成了叛徒，他与兽人部落沆瀣一气，与自己的人类同胞为敌。有人发现奥特兰克的士兵与兽人并肩作战，而城市附近的一座囚营里还关押着达拉然的市民。真相大白之后，其他人类王国向奥特兰克进军以示报复。居民们或逃离或被赶出家园，洛丹伦的国王泰瑞纳斯·米奈希尔二世宣布对这座城市实行军事管制，废黜了匹瑞诺德，并将他投入牢狱。\n\n这座城市再也没能复兴。破碎岭食人魔在穆格索尔的带领下占据了空荡荡的街道和宫殿，而昔日奥特兰克人民四散的残部则占据着城外的村庄。毁坏的运肉马车至今仍躺在北面城墙和城门附近，城墙内外的墓地、被积雪掩埋的农场，以及瓦砾中破碎的弩车，都还保持着当初被遗弃时的模样。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "高地",
			short = "高地曾经养活过一个王国。这里的丘陵是奥特兰克的粮仓，为这个古老的国家提供粮食和牧场。",
			full = "高地曾经养活过一个王国。这里的丘陵是奥特兰克的粮仓，为这个古老的国家提供粮食和牧场。\n\n那个国家分崩离析了。高地没有落入任何王室手中，而是归了辛迪加，在这片山区中，没有哪里比这里被他们控制得更加牢固。瓦杜斯男爵在他们设于此地的营地中发号施令，成了一个破碎王国残留土地的领主。\n\n在最西端坐落着达伦德农场，这个名字比它曾经的含义留存得更加长久。",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
