		["drowned reef"] = {
			name = "水下暗礁",
			short = "在阿拉希高地南岸外的海湾之下，沉睡着一座古老而残破的精灵城市。它已不再空无一人：刺脊纳迦占据了这里，由纳兹亚克王子统治。",
			full = "在阿拉希高地南岸外的海湾之下，沉睡着一座古老而残破的精灵城市。它已不再空无一人：刺脊纳迦占据了这里，由纳兹亚克王子统治。\n\n上方的暗礁已经吞没了许多船只，其中包括少女愚行号和银松之魂号。据说刺脊纳迦能够扭转海湾的潮水，将那些以为在法迪尔海湾找到了安全港湾的船员引向礁石。",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "枯须峡谷",
			short = "枯须峡谷穿过阿拉希高地东部的群山，位于落锤镇的东北方。峡谷的尽头是一个洞穴，那里住着枯须狗头人，它们与共同栖居于这片高地的巨人结为盟友。",
			full = "枯须峡谷穿过阿拉希高地东部的群山，位于落锤镇的东北方。峡谷的尽头是一个洞穴，那里住着枯须狗头人，它们与共同栖居于这片高地的巨人结为盟友。\n\n在洞穴深处，越过那些地道，安放着一块石头碎片，其中囚禁着密斯莱尔公主的一部分精华。狗头人们凶狠地守护着它，也守护着聚集在洞穴深处的那些微粒，尽管它们之中似乎没有谁知道那块碎片里究竟藏着什么。",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "法迪尔海湾",
			short = "法迪尔海湾得名于法迪尔，据说他和他的追随者们启程远航时，曾在这里留下标记。",
			full = "法迪尔海湾得名于法迪尔，据说他和他的追随者们启程远航时，曾在这里留下标记。\n\n很久以后，黑水袭击者为了寻找据说沉在附近水域中的精灵宝藏来到这里。钢腹船长和奥布瑞恩船长率领三艘船驶入海湾，但一股奇异的潮水向他们涌来，那是守护着暗礁下沉没废墟的纳迦所掀起的，三艘船中有两艘沉没了。只有先驱者号抵达了岸边，而她的船员们发现自己被困在了海湾里，直到纳迦被赶走，下方沉船中的航海日志被找回，他们才得以离开。\n\n后来，两位侏儒工程师德拉克里格博士和菲兹索普教授制造了一台装置，用来寻找据说钙化在水下暗礁岩石中的精灵宝石。\n\n这片海湾至今仍带着那段水淹历史的伤痕：暗礁、残骸和废墟，都在诉说着那些本不该沉没的船只，以及一笔大海至今未曾交出的宝藏。",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "格沙克农场",
			short = "格沙克农场位于阿拉希高地东部，靠近枯木村。",
			full = "格沙克农场位于阿拉希高地东部，靠近枯木村。第三次战争之后，来自落锤镇的被遗忘者和兽人占据了这座农场，各有所图，兽人从这里获取补给，而被遗忘者则把它的田地和附属建筑变成了一处试验场，用来研究某种更加黑暗的炼金术。\n\n联盟特工奎艾和基恩洛前来调查这里发生的事情。在他人的帮助下，他们截杀了一名正要前往塔伦米尔送信的被遗忘者信使，并搜查了农场本身，在那里找到了一位药剂师乔瑞尔的笔记。他的研究表明，某种可怕的新东西正在成形：又一场瘟疫正在酝酿之中。\n\n如今，落锤镇的步兵驻守着这座农场。",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "落锤镇",
			short = "落锤镇的土地记得它曾经的模样。第二次战争之后，洛丹伦联盟在这里建立了它最大的收容所之一，将被俘的兽人关押在高墙之后。",
			full = "落锤镇的土地记得它曾经的模样。第二次战争之后，洛丹伦联盟在这里建立了它最大的收容所之一，将被俘的兽人关押在高墙之后。它并没有一直作为一座监狱存在下去。酋长萨尔和奥格瑞姆·毁灭之锤率领部落攻打收容所，解救他们的族人，在那场解救的混乱中，就在萨尔掩护撤退之际，一名冲锋的骑士将长枪刺入了奥格瑞姆的后背，力道之猛，竟将他的盔甲前后贯穿。毁灭之锤就死在那里，死在他前来解放的这片土地上。\n\n第三次战争之后，部落回到这片废墟，在其中建起了一座前线基地，并以在夺取此地时阵亡的那位酋长之名，将其命名为落锤镇。它不仅仅是一座前哨，更是那些觉得世上已无容身之处的人们的避难所，它的灵魂小屋、兽栏、锻炉和大厅，就矗立在收容所的高墙曾经屹立的地方。",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "诺斯弗德农场",
			short = "激流堡陷落之后，诺斯弗德农场落入了辛迪加之手，他们将这里变成了在阿拉希高地的一处前哨。",
			full = "激流堡陷落之后，诺斯弗德农场落入了辛迪加之手，他们将这里变成了在阿拉希高地的一处前哨。\n\n巨魔萨满祭司托尔甘来到这里，是因为他察觉到空气中有某种不对劲的东西。他循着这股气息追查到农场，发现恶魔召唤的残余痕迹仍萦绕在此，而当他走近时，他自己的血液也开始沸腾，涌起一股并不完全属于他自己的怒火。他在地上发现了一枚用来召唤恶魔的血石护符，不过这一枚的力量已经耗尽了。他怀疑辛迪加的勾当远不止拦路抢劫那么简单，于是开始搜寻其他同样的护符，以查明他们的真实意图。",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "避难谷地",
			short = "当激流堡的都城在第三次战争中化为废墟时，它的大多数人民都向南逃进了阿拉希高地。但激流堡军队的残部却不愿随他们而去。",
			full = "当激流堡的都城在第三次战争中化为废墟时，它的大多数人民都向南逃进了阿拉希高地。但激流堡军队的残部却不愿随他们而去。他们留了下来，决心夺回失去的一切，正是在这里，在避难谷地，他们坚守了下来。\n\n这座前哨成了联盟在高地作战的大本营，士兵们一心要夺回激流堡，并为联盟的事业尽可能地获取资源。这种专一的目标几乎容不下任何别的事情。当萨多尔大桥遭到黑铁矮人的猛烈袭击，那里的矮人派人前来求援，希望夺回丹莫德和大桥本身时，尼艾丝队长连一个人都抽不出来。她说，激流堡已经陷落，在夺回它之前，避难谷地的每一把剑、每一双手都只属于这一项事业。她告诉那位信使，荣誉和职责将他们束缚在高地，布莱德·长须只能在没有他们的情况下想办法了。",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "激流堡",
			short = "激流堡曾经是斯托姆，是第一个人类王国的摇篮，也是阿拉索帝国的都城。",
			full = "激流堡曾经是斯托姆，是第一个人类王国的摇篮，也是阿拉索帝国的都城。当兽人部落来到东部王国时，它仍是洛丹伦联盟中的一方强权，即使在第二次战争之后，它的威名也未曾屈服。\n\n第三次战争之后，这座城市遭到洗劫，变得支离破碎。如今它被分割成三部分：内堡被辛迪加占据，毁坏的法师区被石拳食人魔在枯木巨魔的协助下占领，而最后一片城区仍由激流堡的军队据守，加伦·托尔贝恩王子正是在那里统领着他残存的子民。",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "萨多尔大桥",
			short = "两座巨大的石拱横跨在湿地与阿拉希高地之间的峡谷上，它们由矮人亲手建造，三代以来一直由安威玛尔家族守护。",
			full = "两座巨大的石拱横跨在湿地与阿拉希高地之间的峡谷上，它们由矮人亲手建造，三代以来一直由安威玛尔家族守护。它们建于三锤之战之后，当时铁炉堡希望与鹰巢山的蛮锤同胞保持友好，这两座桥梁便成了两个矮人王国之间的道路与象征，承载着令双方都富足起来的贸易。\n\n这两座桥足以承受整支军队的重量，曾经是矮人与人类之间主要的贸易通道。正是在这里，安度因·洛萨将旧部落的最后残部逐出洛丹伦，赶回了卡兹莫丹，迫使他们败退着越过了大桥。\n\n如今，大桥伤痕累累。由卡姆·深怒和卑劣的巴尔加拉斯策划的一场黑铁阴谋严重破坏了桥梁，矮人部队正奋力守住剩下的部分，并夺回附近的丹莫德镇。许多矮人在战斗中牺牲，其中包括苏利·巴鲁、伊贝尼瑟·锈锁，以及布莱德·长须的兄弟。",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "索拉丁之墙",
			short = "索拉丁国王修筑了这道城墙以抵御阿曼尼巨魔，那时斯托姆还年轻，阿拉索也才刚刚为人类夺得这片土地。",
			full = "索拉丁国王修筑了这道城墙以抵御阿曼尼巨魔，那时斯托姆还年轻，阿拉索也才刚刚为人类夺得这片土地。世世代代以来，它如同一名坚定的哨兵屹立于此，这道防线的意义就在于保护人类免遭巨魔的侵袭。\n\n几百年后，城墙依然屹立，却已严重损毁，石块破碎，它漫长的守望也沦为了一片废墟。",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "阿拉索之塔",
			short = "阿拉索之塔矗立在激流堡的法师区，得名于这个王国血脉所承袭的古老的阿拉索帝国。",
			full = "阿拉索之塔矗立在激流堡的法师区，得名于这个王国血脉所承袭的古老的阿拉索帝国。\n\n大法师特雷莱恩曾在塔中研习，并在那里构建了一套融入高塔本身的防御，平时处于沉睡状态，要用一颗附魔宝石才能唤醒。当辛迪加和石拳食人魔逼近激流堡时，特雷莱恩试图用他的造物守住高塔，但这还远远不够。他逃离了城市，而高塔也随之陷落。石拳食人魔将法师区据为己有，食人魔法师鲁尔·独石也住进了塔中的厅堂。\n\n特雷莱恩从未停止惦念他留在那里的东西：他的护命匣、他的宝珠，还有一块他亲手打磨的余烬玛瑙。他求助于他以前的学徒大法师马林，希望能从如今占据高塔的食人魔手中取回它们。后来有消息传回给马林，说老师的遗物已经被找到了，就藏在他曾经视为己有的那些厅堂里的箱子中。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "枯木村",
			short = "枯木村环绕着阿拉希高地东南部的一座小湖，是枯木部族巨魔的家园。村子后面是一个巨大的洞穴，部族的首领们大多就在那里。",
			full = "枯木村环绕着阿拉希高地东南部的一座小湖，是枯木部族巨魔的家园。村子后面是一个巨大的洞穴，部族的首领们大多就在那里。\n\n枯木巨魔与附近的石拳食人魔结成了同盟，共同对抗激流堡和落锤镇。巨魔和食人魔联手占据了激流堡本身的一片城区，那是他们从昔日的主人手中夺来的。\n\n这份力量使枯木巨魔成了众矢之的，联盟和部落都在追猎他们，希望将他们彻底消灭。在那些抵抗这场清算的人之中，杀戮者尼玛尔被认为是最危险的一个，这名战士在临死之时，还拉上了许多敌人为他陪葬。",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
