			name = "漫尘盆地",
			short = "漫尘盆地位于卡加斯和巨牙谷之间，是荒芜之地西北部一片龟裂干旱的土地。郊狼和秃鹫在这里四处游荡，岩石元素在石块间蠢蠢欲动。",
			full = "漫尘盆地位于卡加斯和巨牙谷之间，是荒芜之地西北部一片龟裂干旱的土地。郊狼和秃鹫在这里四处游荡，岩石元素在石块间蠢蠢欲动。除了仙人掌和几棵顽强的树木之外，这里几乎寸草不生。瓦格营地就坐落在这片荒原之中。",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "尘风峡谷",
			short = "狂风不断地冲刷着尘风峡谷，直到这里再也没有任何柔软的东西能够屹立，只剩下岩石和峡谷干枯的骨架。它位于莱瑟罗峡谷以西，是荒芜之地中一道荒凉的沟壑，尘土在这里从来不会长久地落定。",
			full = "狂风不断地冲刷着尘风峡谷，直到这里再也没有任何柔软的东西能够屹立，只剩下岩石和峡谷干枯的骨架。它位于莱瑟罗峡谷以西，是荒芜之地中一道荒凉的沟壑，尘土在这里从来不会长久地落定。",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "铁趾挖掘场",
			short = "铁趾挖掘场位于荒芜之地北部，曾经在这里劳作的矿工早已离去，挖掘坑道如今一片寂静。",
			full = "铁趾挖掘场位于荒芜之地北部，曾经在这里劳作的矿工早已离去，挖掘坑道如今一片寂静。铁趾本人已经放弃了这处挖掘场，取而代之的是一伙黑铁矮人，他们很可能就是已经侵入奥达曼的那股势力。",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "卡加斯",
			short = "卡加斯孤零零地矗立在卡兹莫丹，是部落在那片土地上唯一的前哨，以碎手氏族的酋长卡加斯·刃拳之名命名。",
			full = "卡加斯孤零零地矗立在卡兹莫丹，是部落在那片土地上唯一的前哨，以碎手氏族的酋长卡加斯·刃拳之名命名。\n\n奉酋长萨尔本人之命，卡加斯远征军一次又一次地驰入严酷的荒芜之地。它真正的目的，是打通一条穿过灼热峡谷通往黑石山的道路，好让部落能够在黑暗部落酋长雷德·黑手自己的要塞中向他发起攻击。那条道路穿过黑铁矮人视为己有的土地，因此部落发现自己再次与他们开战，这并非出于计划，只是因为他们需要穿越这片土地。\n\n卡加斯的另一重价值则更为显而易见：它是南北之间的枢纽，从落锤镇和幽暗城而来的道路，在这里与向南通往格罗姆高、藏宝海湾和斯通纳德的道路交汇。",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "莱瑟罗峡谷",
			short = "莱瑟罗峡谷宽阔而崎岖，横贯荒芜之地的东部，谷底出没着黑龙军团的雏龙和幼龙。",
			full = "莱瑟罗峡谷宽阔而崎岖，横贯荒芜之地的东部，谷底出没着黑龙军团的雏龙和幼龙。峡谷中零星矗立着水晶方尖碑，在岩石和龙焰之间显得奇异而刻意。",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "造物者遗迹",
			short = "在奥达曼的入口外，大地被一道道宽阔而刻意的切口剥开，留下一道向天空敞开的挖掘伤疤。",
			full = "在奥达曼的入口外，大地被一道道宽阔而刻意的切口剥开，留下一道向天空敞开的挖掘伤疤。如今黑铁矮人占据着这处遗迹，监视着挖掘场和那条通往地下埋藏之处的道路。",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "雾气平原",
			short = "雾气平原位于荒芜之地火山洞穴的东边。这里只剩下一片无人之地，只有巨型秃鹫、山脊潜伏者族长和疯狂的峭壁郊狼宣称它归自己所有。",
			full = "雾气平原位于荒芜之地火山洞穴的东边。这里只剩下一片无人之地，只有巨型秃鹫、山脊潜伏者族长和疯狂的峭壁郊狼宣称它归自己所有。",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "奥达曼",
			short = "在卡兹莫丹群山的深处，坐落着奥达曼，那是泰坦守护者在远古时代建造的一座巨大而古老的宝库。",
			full = "在卡兹莫丹群山的深处，坐落着奥达曼，那是泰坦守护者在远古时代建造的一座巨大而古老的宝库。第三次战争之前，来自铁炉堡的矮人曾深入其中，挖掘它那些被掩埋的厅室，但此后宝库落入了穴居人和黑铁矮人之手，如今他们正在它的岩石中挖掘，寻找它仍然蕴藏的任何地下财富。\n\n奥达曼中依然遍布着那个泰坦铸造时代留下的遗物，那些敢于深入其中的人仍能找到埋藏其中的神器，探险者协会的考古学家和冒险者们正继续在废墟中细细搜寻，将它们慢慢发掘出来。",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "巨牙谷",
			short = "巨牙谷是荒芜之地中夹在两道石壁之间的一条狭窄山谷，被狼和美洲狮所占据，它们的利齿为这里赢得了名字。",
			full = "巨牙谷是荒芜之地中夹在两道石壁之间的一条狭窄山谷，被狼和美洲狮所占据，它们的利齿为这里赢得了名字。\n\n流放者马特克就在谷中扎营，他是从某个他曾经归属的地方被驱逐出来的，与他在一起的还有里格弗兹和加兹里克。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- 诅咒之地: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "黑暗之门",
			short = "这座传送门的建造从一开始就是一场背叛。古尔丹与被黑暗泰坦萨格拉斯附身的人类法师麦迪文联手撕开了这道裂隙。",
			full = "这座传送门的建造从一开始就是一场背叛。古尔丹与被黑暗泰坦萨格拉斯附身的人类法师麦迪文联手撕开了这道裂隙。在德拉诺，建造其石框的兽人石匠们被术士杀害，以便为最后的封印注入力量，而几乎所有仍被部落关押的德莱尼囚犯都被带到门下，在一瞬间被吸干生命，好让古尔丹获得连接两个世界的力量。部落经由这道大门涌入暴风城，掀起了第一次战争，在随后的战争中，它源源不断地将兽人和食人魔送入艾泽拉斯，而它周围的沼泽也渐渐凝结成一片血红的荒原，后来被称为诅咒之地。\n\n战争结束时，大法师卡德加和他的法师同伴们摧毁了位于艾泽拉斯一侧的建筑，以断绝部落的退路，那场爆炸如此猛烈，就连德拉诺那边的石框也一并被摧毁了。此后，卡德加建起了守望堡来监视这片废墟，然而两个世界之间的裂痕从未真正愈合，在此后的岁月里，恶魔还会再次从中穿过。",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "巨槌岗哨",
			short = "巨槌岗哨是巨槌食人魔氏族堆起的一座土丘，他们从德拉诺来到艾泽拉斯，从未远离黑暗之门。",
			full = "巨槌岗哨是巨槌食人魔氏族堆起的一座土丘，他们从德拉诺来到艾泽拉斯，从未远离黑暗之门。他们至今仍占据着这片土地。",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "要塞军械库",
			short = "在诅咒之地伤痕累累的土地上，联盟的矿工们在要塞军械库劳作，为守望堡从大地中开采矿物。",
			full = "在诅咒之地伤痕累累的土地上，联盟的矿工们在要塞军械库劳作，为守望堡从大地中开采矿物。他们开采到的东西会被运往暴风城，作为交换，城堡则会得到在那片荒芜之地中坚持下去所需的其他补给。",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "守望堡",
			short = "守望堡矗立在一座高高的断崖之上，俯瞰着进入诅咒之地的唯一道路，它的城墙是为了监视这个世界上一道谁也不希望再次打开的伤疤而筑起的。",
			full = "守望堡矗立在一座高高的断崖之上，俯瞰着进入诅咒之地的唯一道路，它的城墙是为了监视这个世界上一道谁也不希望再次打开的伤疤而筑起的。\n\n大法师卡德加在第二次战争之后的那些年里提议建造了它，那时第一座黑暗之门已经破碎，门另一边的兽人家园也已凋零成一片废墟。洛丹伦联盟出资建造了它，有些王国比其他王国更加乐意，而石匠工会则在艾德温·范克里夫的主持下修建了它。此后，肯瑞托驻守在这里，努力遏制那些从传送门的伤口中蔓延出来、威胁着要扩散到更远土地上的污秽。\n\n卡德加一直是这里的主人，直到耐奥祖的氏族从德拉诺一侧重铸了黑暗之门，并围攻了这座城堡。卡德加和他的同伴图拉扬、达纳斯·托尔贝恩、奥蕾莉亚·风行者和库德兰·蛮锤率领联盟穿过传送门，在那边击溃了部落，随后他们留在了另一侧，将传送门封闭，以免德拉诺的毁灭追随他们而来。此后的二十年间，传送门一直沉寂无声。",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "污染者高地",
			short = "污染者高地从诅咒之地的中央拔地而起，是一片嶙峋破碎的山地。强大的恶魔拉瑟莱克就居住在这里，单凭他的存在，就足以赋予这个地方它的名字。",
			full = "污染者高地从诅咒之地的中央拔地而起，是一片嶙峋破碎的山地。强大的恶魔拉瑟莱克就居住在这里，单凭他的存在，就足以赋予这个地方它的名字。",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "盘蛇谷",
			short = "盘蛇谷是诅咒之地东部一片蜿蜒曲折的洞穴群，洞口处立着第二次战争遗留下来的兽人建筑，早已烧成焦黑的残骸。",
			full = "盘蛇谷是诅咒之地东部一片蜿蜒曲折的洞穴群，洞口处立着第二次战争遗留下来的兽人建筑，早已烧成焦黑的残骸。在那场战争结束很久之后，这些洞穴成了某种更加黑暗之物的巢穴：一群狂热崇拜被诅咒的基里斯的邪教徒。\n\n大法师阿利斯塔进入了那座迷宫，让他的魔誓者从里面开始行动。入口附近的一个箱子里，存放着一枚刻有他名字的护符。",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "腐烂之痕",
			short = "腐烂之痕曾是黑色沼泽的一部分，直到黑暗之门的腐化渗入这里，使大地变得干涸、光秃，红得如同鲜血。",
			full = "腐烂之痕曾是黑色沼泽的一部分，直到黑暗之门的腐化渗入这里，使大地变得干涸、光秃，红得如同鲜血。如今这里已经没有水流。恶魔野兽在这片再也记不起曾经生长过什么的土地上徘徊。\n\n海加尔山之战后，末日领主卡扎克将燃烧军团在艾泽拉斯的残余部队撤到了这道伤痕之中，将其据为己有。他派他的副官污染者拉瑟莱克统辖此地，命令这名污染者守住这片土地。此后，卡扎克本人也一直留在这里，在海加尔山之战于别处打响并获胜多年之后，单凭他的存在，就足以表明这道伤痕仍是燃烧军团的领地。\n\n很久以后，一位年迈的人类术士衰老的戴奥来到了这道伤痕，并在它的祭坛边安了家。在那里，在这片土地早已孕育出的恶魔之间，他不受打扰地举行着自己的仪式，并招收年轻的学徒，在这个早已被邪能所吞噬的地方向他们传授地狱的法术。",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- 提瑞斯法林地: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "阿加曼德家族墓穴",
			short = "在阿加曼德磨坊以北，阿加曼德家族的逝者曾在这座墓穴中安息。天灾军团的爪牙达尔格尔队长将这里据为己有，唤醒了墓中所有的尸体和灵魂。",
			full = "在阿加曼德磨坊以北，阿加曼德家族的逝者曾在这座墓穴中安息。天灾军团的爪牙达尔格尔队长将这里据为己有，唤醒了墓中所有的尸体和灵魂。如今，漆黑的通道中尘土弥漫，满怀怨恨的亡者会攻击任何不请自来的闯入者。",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "阿加曼德磨坊",
			short = "阿加曼德的风车曾经为提瑞斯法最富有的家族之一而转动。当天灾军团向北袭来时，格里高·阿加曼德拒绝逃离。",
			full = "阿加曼德的风车曾经为提瑞斯法最富有的家族之一而转动。当天灾军团向北袭来时，格里高·阿加曼德拒绝逃离。他加固了磨坊，储备好物资以应对围攻，并说服家族自己的工人们留下来，与他们并肩作战。\n\n本该守得住的。然而并没有，因为背叛来自墙内。阿加曼德家最小的儿子德夫林背叛了自己的血亲，协助了天灾军团，守军因此无法抵挡随之而来的攻击。最终，瘟疫还是夺走了这个家族其余的人，那些为保卫家园而死的阿加曼德家族成员，在家中复活成了没有心智的亡灵。\n\n这些风车至今仍矗立在提瑞斯法北部的高地上，而建造它们的家族如今却在为摧毁了他们的那支大军效力。",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "巴尼尔农场",
			short = "巴尼尔农场位于那座毁灭的都城东北方，篱笆残破，马厩空荡，只有游荡的天灾军团在其中出没。",
			full = "巴尼尔农场位于那座毁灭的都城东北方，篱笆残破，马厩空荡，只有游荡的天灾军团在其中出没。\n\n巴尼尔家族曾经经营着这片土地，饲养着洛丹伦王室作为坐骑的高大白马。王城陷落的那一天，天灾军团来到农场，杀死了整个家族，只留下这片闹鬼的土地。\n\n农场花园里曾经精心照料的金鱼草至今仍在那里野蛮生长，有消息传到生者那里，说瘟疫之地的腐化可能已经侵入了这些花草。溜过亡灵壁垒的天灾军团成群地聚集在这座废弃的农场周围。",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "澈水湖",
			short = "澈水湖位于布瑞尔的东北方，湖中央有一座大岛，如今冈瑟尔的居所就矗立在岛上。",
			full = "澈水湖位于布瑞尔的东北方，湖中央有一座大岛，如今冈瑟尔的居所就矗立在岛上。",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "布瑞尔",
			short = "布瑞尔曾是洛丹伦王国一座普通的城镇，由巴罗夫家族管辖，阿加曼德家族也在镇上拥有一座自己的宅邸。",
			full = "布瑞尔曾是洛丹伦王国一座普通的城镇，由巴罗夫家族管辖，阿加曼德家族也在镇上拥有一座自己的宅邸。克尔苏加德到来的那一天，它的平凡便宣告终结。那时这位死灵法师还是个活人，他选择布瑞尔作为首次试验亡灵瘟疫的地方，而那次感染如此成功，使他备受鼓舞，于是敦促巫妖王提前发动了对洛丹伦的入侵。提瑞斯法林地的死者多到这片土地无法妥善安葬；布瑞尔城墙外的那片大墓地，便是对这些多余死者的回答。镇上的守卫者无法守住它，残存的幸存者纷纷逃离，去投奔正在追查席卷北方的腐化源头的阿尔萨斯·米奈希尔王子。\n\n布瑞尔并没有一直沉寂下去。多年以后，被遗忘者占据了这里，如今执政官塞弗伦统治着这片曾被瘟疫夺走的土地。古老的怨恨也在这里徘徊不去：曾经为阿加曼德家族效力的库勒曼·法席恩仍在搜寻他们的遗骸，他要这些骨头并非出于怜悯，而是为了报复一场他归咎于他们的死亡。",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "布瑞尔城镇大厅",
			short = "城镇大厅是布瑞尔最显眼的建筑。执政官塞弗伦在它的讲台上代表全镇发言，为提瑞斯法的亡者分派任务。",
			full = "城镇大厅是布瑞尔最显眼的建筑。执政官塞弗伦在它的讲台上代表全镇发言，为提瑞斯法的亡者分派任务。在任何地方，都很少有这样的大厅像这座一样掌握在被遗忘者手中，这足以表明布瑞尔是多么牢固地属于他们。",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "亡灵壁垒",
			short = "亡灵壁垒矗立在提瑞斯法林地与西瘟疫之地的交界处，是被遗忘者抵御仍在东方集结的天灾军团的防线。",
			full = "亡灵壁垒矗立在提瑞斯法林地与西瘟疫之地的交界处，是被遗忘者抵御仍在东方集结的天灾军团的防线。在这里，被遗忘者的守卫者与银色黎明放下了彼此的分歧，共同对抗这个共同的敌人，他们一同守望着边界，并向东派出战士，打击巫妖王的爪牙。\n\n与提瑞斯法的其他地方不同，这一带看上去完全不像林地：一层瘟疫之雾笼罩在上空，将天空染成了与更远处的西瘟疫之地一样病态的黄灰色。",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "炉灰庄园",
			short = "炉灰庄园曾因壁炉的温暖和田地的丰饶而得名。亡灵瘟疫终结了这一切。",
			full = "炉灰庄园曾因壁炉的温暖和田地的丰饶而得名。亡灵瘟疫终结了这一切。在这里生活和劳作的人全都死于那场疫病，丰饶的土地变得荒芜，一排排田垄被没有心智的天灾亡灵占据，它们至今仍在那里蹒跚游荡。\n\n被遗忘者将这座农舍据为己有，与附近道路上的旅人做些交易。",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "十字军前哨",
			short = "一座侦察塔耸立在提瑞斯法林地东部的丘陵上，由血色十字军把守。",
			full = "一座侦察塔耸立在提瑞斯法林地东部的丘陵上，由血色十字军把守。他们从塔顶监视着穿过林地向南延伸的道路，随时准备从侧翼袭击任何胆敢向远处的血色修道院进军的部队。瓦尚队长在这里指挥。",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "丧钟镇",
			short = "丧钟镇坐落在一道狭窄而戒备森严的山谷中，新近复生的被遗忘者正是在这里第一次睁开双眼，望向这个赐予他们的世界。",
			full = "丧钟镇坐落在一道狭窄而戒备森严的山谷中，新近复生的被遗忘者正是在这里第一次睁开双眼，望向这个赐予他们的世界。\n\n女妖之王麾下反叛的亡灵所占据的其他据点，都沿用了它们作为生者城镇时的名字，丧钟镇却被赋予了一个全新的名字，这个名字与这里发生的事情相符，而不是与这里曾经存在过的东西相符。如今已经没有人记得其中的缘由。\n\n在这里，生存是每天都要面对的挣扎，而金子是最稀缺的东西。村子西北方有一座富含金属的矿洞，但已被蜘蛛占据，丧钟镇的亡灵们一次又一次地出发，试图将它清理干净，好让地下的矿石终于能够得到开采。亡灵精英卫兵沿着山谷的边缘守望，在脆弱的新生亡灵与那些想要让他们再死一次的天灾军团和血色十字军之间，他们是唯一的屏障。",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "法奥之墓",
			short = "在血色修道院的西南方，提瑞斯法林地的东部，有一块曾经有哀悼者照料的土地：法奥之墓，大主教阿隆索斯·法奥的坟墓。",
			full = "在血色修道院的西南方，提瑞斯法林地的东部，有一块曾经有哀悼者照料的土地：法奥之墓，大主教阿隆索斯·法奥的坟墓。\n\n法奥生前备受尊崇，他在天灾军团到来之前的某个时候去世，他的死吸引了哀悼者们来到这片土地。\n\n如今已经没有人再来拜谒他留下的这座坟墓了。曾经前来的哀悼者都已不在，这块墓地无人照料，大多已被遗忘。",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "恐惧之末旅店",
			short = "恐惧之末旅店坐落在布瑞尔，它的名字阴森地呼应着它所服务的这座城镇。",
			full = "恐惧之末旅店坐落在布瑞尔，它的名字阴森地呼应着它所服务的这座城镇。在它的地板下面，地窖里并没有什么值得一提的酒桶：那里关着一名被俘的血色狂热者和一名矮人巡山人，他们都是被遗忘者的囚犯。",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "加伦鬼屋",
			short = "加伦鬼屋曾是提瑞斯法林地北部一座富饶的农庄，田地广阔，粮仓充盈。亡灵瘟疫终结了这一切。",
			full = "加伦鬼屋曾是提瑞斯法林地北部一座富饶的农庄，田地广阔，粮仓充盈。亡灵瘟疫终结了这一切。在洛丹伦天灾浩劫中，天灾军团席卷而过，加伦和他的家人在自己的家中惨遭屠戮，就连他们残破家园周围的土地本身也变得灰暗而毫无生气。\n\n残存下来的建筑被蛆眼率领的腐皮豺狼人占据，它们将农舍和谷仓据为己有，毫不犹豫地攻击任何过于靠近的人。\n\n这座农庄再也没能恢复。它被遗弃在那里，田地荒芜，主人一家已然消逝，只有豺狼人还留在那里，宣示着如今是谁占据着它。",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "冈瑟尔的居所",
			short = "澈水湖的一座岛上矗立着冈瑟尔的居所，被遗忘者巫妖冈瑟尔·阿坎努斯和他的僵尸仆从占据着那里。",
			full = "澈水湖的一座岛上矗立着冈瑟尔的居所，被遗忘者巫妖冈瑟尔·阿坎努斯和他的僵尸仆从占据着那里。在它的西南岸外，一座光秃秃的无名小岛上，有一处奇怪的标记，人们只知道它叫莉莉丝的餐桌。",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "夜行蜘蛛洞穴",
			short = "夜行蜘蛛洞穴是一道小山谷，其中有一座古老的金矿，两者都已被蜘蛛占据。幼小的蜘蛛在开阔的谷地中游荡，而成年的夜行蜘蛛则盘踞在矿洞更加黑暗的坑道中。",
			full = "夜行蜘蛛洞穴是一道小山谷，其中有一座古老的金矿，两者都已被蜘蛛占据。幼小的蜘蛛在开阔的谷地中游荡，而成年的夜行蜘蛛则盘踞在矿洞更加黑暗的坑道中。\n\n新近复生的被遗忘者来到这里，测试他们的身体还能做些什么，他们先是除掉外面的幼蛛，然后才敢深入矿洞本身。\n\n在矿洞的最深处，盘踞着夜行蜘蛛之母，她是上方那些蜘蛛群的母亲。",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "噩梦谷",
			short = "在提瑞斯法林地的血色哨塔以西，有一道已经荒废的山谷。这里的树木已经枯萎，曾经生活在林间的野生动物被黑暗猎犬和巨大的吸血蝙蝠吃了个干净。",
			full = "在提瑞斯法林地的血色哨塔以西，有一道已经荒废的山谷。这里的树木已经枯萎，曾经生活在林间的野生动物被黑暗猎犬和巨大的吸血蝙蝠吃了个干净。在这些猎手之中飞翔着刺针者雷萨恩，那是一只与众不同的稀有白色蝙蝠。",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "北部海岸",
			short = "北部海岸位于提瑞斯法林地与无尽之海相接的地方，如今已被鱼人和水生生物所占据。",
			full = "北部海岸位于提瑞斯法林地与无尽之海相接的地方，如今已被鱼人和水生生物所占据。自从亡灵瘟疫爆发以来，海岸就变得阴暗而寒冷，潮水将死去的海洋生物留在水边腐烂。",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "洛丹伦废墟",
			short = "在这座地下城市的上方，洛丹伦的王宫依然矗立，大厅向天空敞开，花园已经荒芜。联盟的伟大王国就在这里消亡，而它的幽魂也从未真正离开过这里。",
			full = "在这座地下城市的上方，洛丹伦的王宫依然矗立，大厅向天空敞开，花园已经荒芜。联盟的伟大王国就在这里消亡，而它的幽魂也从未真正离开过这里。\n\n终结它的正是阿尔萨斯·米奈希尔。这位王子率领着一支为对付他自己的人民而组建的军队回到了家乡，在任何人明白他变成了什么之前，人们用钟声和欢呼声迎接他穿过了这些大门。他看到他的父亲泰瑞纳斯国王正在王座厅中等候，便在那里杀死了他。他站在尸体旁说出的话，至今仍在那间大厅里回荡，传入任何在那里逗留的人耳中：这个王国将会覆灭，而一个新的秩序将从它的灰烬中崛起，撼动整个世界。这并不是一句空洞的狂言。短短几天之内，这座城市和它的人民惨遭屠戮，洛丹伦从此归属于天灾军团。\n\n据说，如果如今在庭院中漫步，仍能听到石头所记得的声音：低沉的私语，迎接的钟声，还有王座厅中那从未真正消散的喃喃低语。那些能够看透帷幕的人说，洛丹伦的市民仍在那里行走，却浑然不知他们的王国早已不复存在。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "血色修道院",
			short = "在十字军的统治下，古老修道院变成了兵营和监狱。大检察官怀特迈恩和雷诺·莫格莱尼将这里作为他们的大本营，它的礼拜堂既是祈祷之所，也成了审判之地。",
			full = "在十字军的统治下，古老修道院变成了兵营和监狱。大检察官怀特迈恩和雷诺·莫格莱尼将这里作为他们的大本营，它的礼拜堂既是祈祷之所，也成了审判之地。\n\n在成为一座要塞之前，古老修道院是圣光教会的一座大教堂，里面满是图书馆，圣骑士们就在那里接受训练。亚历山德罗斯·莫格莱尼本人年轻时曾在那里度过数月，在他拿起剑之前，一直在那里祈祷和学习。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "血色十字军哨岗",
			short = "血色十字军哨岗在这里守望，守护着血色修道院自身无法防御的那条通道。梅尔拉克队长在这里指挥，守卫着这座哨岗，抵御任何企图在暗中攻击修道院薄弱侧翼的人。",
			full = "血色十字军哨岗在这里守望，守护着血色修道院自身无法防御的那条通道。梅尔拉克队长在这里指挥，守卫着这座哨岗，抵御任何企图在暗中攻击修道院薄弱侧翼的人。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "灰影墓穴",
			short = "灰影墓穴位于丧钟镇墓地内的斜坡顶端，高踞在提瑞斯法的群山之间。一条踩得光秃的小路从它的入口蜿蜒而下，通往下方的丧钟镇。",
			full = "灰影墓穴位于丧钟镇墓地内的斜坡顶端，高踞在提瑞斯法的群山之间。一条踩得光秃的小路从它的入口蜿蜒而下，通往下方的丧钟镇。",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "索利丹农场",
			short = "索利丹的南瓜田是提瑞斯法少数几块旧日生活尚未被瘟疫或亡灵吞噬的土地之一。",
			full = "索利丹的南瓜田是提瑞斯法少数几块旧日生活尚未被瘟疫或亡灵吞噬的土地之一。周围的乡野先是落入天灾军团之手，后来又落入从中崛起的被遗忘者之手，而这里的农民却仍在耕种他们的田垄，在附近血色栅栏的血色十字军的守护下安然无恙。\n\n这份庇护使索利丹成了一个异类。农民们不信任任何不属于血色十字军的人，他们将被遗忘者视为那场几乎夺去他们性命的瘟疫所造就的怪物而拒之门外，同时也对联盟心存戒备，因为联盟的旗帜可能会把他们卷入一场战争，而到目前为止，他们正是因为弱小和被人遗忘才得以置身事外。\n\n被遗忘者无法对这份宁静置之不理。亡灵卫兵希米尔监视着索利丹，并不是因为它现在的样子，而是因为它将来可能变成的样子：今天是爱好和平的农民，明天就可能成为联盟的武装佃户，在被遗忘者志在必得的土地上成为敌人的立足点。",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "静水池",
			short = "在瘟疫爆发之前，静水池是生者享受青春的地方。",
			full = "在瘟疫爆发之前，静水池是生者享受青春的地方。林地里的人家会来到池边野餐，那些年纪太小、还不敢到澈水湖深水里去的孩子们，就在这里学习游泳。\n\n如今那池水已经变成了灰色。水面下的鱼只剩下骨头还在游动，仿佛没有人告诉它们该停下了。游荡的亡灵和野兽沿着池岸经过，黑暗猎犬拜恩在水边徘徊，捕食任何粗心大意逗留在此的东西。\n\n当被遗忘者开始将布瑞尔从废墟中重建起来时，血色十字军的战士们已经开始在静水池的岸边巡逻了。",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "休息区",
			short = "就在血色修道院的北面，有一片从未被瘟疫触及的土地。这里生长着翠绿的树篱，一座喷泉流淌着清澈而非污浊的泉水，与提瑞斯法林地的其他地方截然不同。",
			full = "就在血色修道院的北面，有一片从未被瘟疫触及的土地。这里生长着翠绿的树篱，一座喷泉流淌着清澈而非污浊的泉水，与提瑞斯法林地的其他地方截然不同。血色十字军照料着这里，让这片小小的台地保持着生机，以证明在这片枯萎之中，仍有纯净的东西可以留存下来。",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "毒蛛峡谷",
			short = "毒蛛峡谷曾经一片青翠，到处都是鹿和兔子，后来才变成了如今的模样：一道被毒蜘蛛占据的山谷，由稀有而致命的斯里斯库克统领，它们的蛛网取代了青草，也为这道山谷赢得了名字。",
			full = "毒蛛峡谷曾经一片青翠，到处都是鹿和兔子，后来才变成了如今的模样：一道被毒蜘蛛占据的山谷，由稀有而致命的斯里斯库克统领，它们的蛛网取代了青草，也为这道山谷赢得了名字。黑暗猎犬在北部的血色十字军营地附近出没，那座营地由桑德斯中尉把守。",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "耳语花园",
			short = "在血色修道院南面的山丘上，那些后来成为血色十字军的人曾在这里与一支天灾大军交战。",
			full = "在血色修道院南面的山丘上，那些后来成为血色十字军的人曾在这里与一支天灾大军交战。双方都有许多人倒下。在暮色中，他们的灵魂仍在徘徊，在花园静谧的石头之间化作隐约的低语，喃喃不绝。",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "耳语海岸",
			short = "耳语海岸位于提瑞斯法林地西部，索利丹农场以北。渔民们曾经钟爱这里平静的水面和稳定的收获。",
			full = "耳语海岸位于提瑞斯法林地西部，索利丹农场以北。渔民们曾经钟爱这里平静的水面和稳定的收获。\n\n那份富饶已经不复存在。鱼人占据了海岸，扑向任何靠近的人，海水也变得寒冷而阴暗。",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- 银松森林: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "安伯米尔",
			short = "安伯米尔曾是一座无足轻重的磨坊小镇，在银松森林中洛丹米尔湖的西南方伐木。",
			full = "安伯米尔曾是一座无足轻重的磨坊小镇，在银松森林中洛丹米尔湖的西南方伐木。\n\n天灾军团和燃烧军团改变了这座小镇的价值。达拉然的肯瑞托在自身遭受毁灭之后正在重建，他们占据了这座小镇，一时之间，安伯米尔变成了它从未成为过的样子：在达拉然巫术的支撑下，成为银松森林中人类真正的抵抗力量。\n\n被遗忘者并没有对此坐视不理。他们的亡灵哨兵从一名囚犯口中得知，巫师们在那里保存着一些与达拉然本身的状况有关的文件。磨坊、马厩和市政厅仍掌握在肯瑞托手中，而密探们正从森林的阴影中对他们展开行动。",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "博伦的巢穴",
			short = "博伦的巢穴位于安伯米尔西南方的丘陵之中。",
			full = "博伦的巢穴位于安伯米尔西南方的丘陵之中。第三次战争过后数年，被遗忘者的斥候向暗影牧师奥利斯特报告，说亡灵正秘密地聚集在那里，准备向瑟伯切尔发动进攻。这些亡灵效命于死灵法师图勒·鸦爪，他选择这个地方，是为了在无人察觉的情况下召集他的仆从，这里离瑟伯切尔足够近，可以构成威胁，又离道路足够远，不会引人注意。",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "黎明岛",
			short = "黎明岛曾经平缓而低矮地从洛丹米尔湖晶莹的湖水中升起，是一片从未受过纷扰的宁静小岛。亡灵瘟疫改变了这一切。",
			full = "黎明岛曾经平缓而低矮地从洛丹米尔湖晶莹的湖水中升起，是一片从未受过纷扰的宁静小岛。亡灵瘟疫改变了这一切。岛上的树木染上了病害，鱼人和沼泽兽占据了这些小岛。如今沼泽兽已经消失，但邪鳍鱼人却不受约束地繁衍，现在已经完全占据了这片岛屿。",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "亡者农场",
			short = "亡者农场被遗弃在银松森林北部，田地早已腐烂，最初的佃户也已被人遗忘。",
			full = "亡者农场被遗弃在银松森林北部，田地早已腐烂，最初的佃户也已被人遗忘。人们所知道的，只是此后占据了这里的东西：为天灾军团效力的腐皮豺狼人，它们把这座残破的农场当作基地，数量不断增加，这种集结表明，某种进攻仍在这里酝酿之中。\n\n被遗忘者不止一次地攻击这座农场，希望在豺狼人采取行动之前将它们击溃。每一次尝试都失败了。每当腐皮豺狼人受到威胁，就会有一个女妖回应它们的召唤，那是一个名叫夜鞭的幽灵，她把这些豺狼人当作自己的部下来指挥，会凭空出现来保护它们。",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "破旧渡口",
			short = "破旧渡口曾经载着货物往返于芬里斯岛，一位领主和他的家人在岛上拥有一座庄园，每趟付给摆渡人几枚硬币。",
			full = "破旧渡口曾经载着货物往返于芬里斯岛，一位领主和他的家人在岛上拥有一座庄园，每趟付给摆渡人几枚硬币。\n\n后来，天灾军团降临洛丹伦。摆渡人在他工作的地方被杀，他的渡船也被砸得粉碎。\n\n如今，食尸鬼、骷髅战士和腐皮豺狼人出没在残破的码头上，渡口已被遗弃，除了强者之外，对任何人来说都十分危险。",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "埃利姆矿洞",
			short = "埃利姆矿洞位于银松森林之中。阿鲁高让他的魔法蔓延到了矿洞里，狼人便把这座矿洞当作了巢穴，由曾经是这里工头的苍白的格瑞姆森率领。",
			full = "埃利姆矿洞位于银松森林之中。阿鲁高让他的魔法蔓延到了矿洞里，狼人便把这座矿洞当作了巢穴，由曾经是这里工头的苍白的格瑞姆森率领。\n\n达拉尔·道恩维沃尔希望除掉格瑞姆森，好让被遗忘者以瓦里玛萨斯的名义将这座矿洞据为己有，作为他们的资源。",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "芬里斯岛",
			short = "芬里斯岛位于洛丹米尔湖的中央，与黎明岛一同构成一圈断断续续的陆地，它被粗略地算作银松森林的一部分。",
			full = "芬里斯岛位于洛丹米尔湖的中央，与黎明岛一同构成一圈断断续续的陆地，它被粗略地算作银松森林的一部分。\n\n第三次战争之前，岛上坐落着芬里斯城堡，那是洛丹伦的一座军事前哨。当天灾军团席卷这片土地时，城堡陷落了。城中的人们或逃离，或当场被杀，岛上从此空无一人。\n\n腐皮豺狼人趁虚而入，把这座被遗弃的城堡当作了它们的巢穴。它们的主人是图勒·鸦爪，即使在豺狼人之中，他也以奸诈而闻名，他统治着腐皮豺狼人，并通过它们统治着整座芬里斯岛，占据着他夺来的城堡以及附近的破旧渡口。",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "芬里斯城堡",
			short = "芬里斯城堡矗立在洛丹米尔湖的中央，位于银松森林的芬里斯岛上，曾经驻扎着洛丹伦相当一部分军队。",
			full = "芬里斯城堡矗立在洛丹米尔湖的中央，位于银松森林的芬里斯岛上，曾经驻扎着洛丹伦相当一部分军队。\n\n当天灾军团席卷这片土地时，城堡也随之陷落。图勒·鸦爪来到了这片废墟，他曾是肯瑞托的一名年轻法师，后来投靠了天灾军团，并让岛上的豺狼人屈服于他的意志，将它们锻造成了腐皮豺狼人。有了这个部族撑腰，他成了芬里斯城堡的主人，而腐皮豺狼人则会扑向任何靠近它们主人的人。",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "格雷迈恩之墙",
			short = "吉恩·格雷迈恩国王在第三次战争之前修筑了他的城墙，他厌倦了吉尔尼斯的钱财被花在兽人收容所上，也被洛丹伦联盟诸王之间的争吵弄得心力交瘁。",
			full = "吉恩·格雷迈恩国王在第三次战争之前修筑了他的城墙，他厌倦了吉尔尼斯的钱财被花在兽人收容所上，也被洛丹伦联盟诸王之间的争吵弄得心力交瘁。他让他的王国闭关自守，将吉尔尼斯与洛丹伦以及群山之外的世界隔绝开来。\n\n城墙抵挡住了亡灵瘟疫，却也为此付出了代价。当天灾军团席卷洛丹伦时，难民们向南逃难，在城门外扎营，而城门多年来一直没有打开。难民们就死在了那里，无人理会。",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "伊瓦农场",
			short = "伊瓦农场曾是一座值得拥有的农场，田垄上结满了沉甸甸的南瓜，农舍里住满了为一个名叫伊瓦的人耕种田地的雇工。",
			full = "伊瓦农场曾是一座值得拥有的农场，田垄上结满了沉甸甸的南瓜，农舍里住满了为一个名叫伊瓦的人耕种田地的雇工。那本是一份不错的生计，直到亡灵瘟疫降临洛丹伦，将它从他手中夺走。\n\n伊瓦并不只是死去了。他复活了，他的家人也复活了，每一个曾在他的土地上劳作过的雇工都复活了，全都变成了腐烂的食尸鬼，如今会扑向任何靠近的人。伊瓦本人则复活成了更加可怕的东西，如今人们称他为邪恶的伊瓦。\n\n三名被派往北方评估危险的亡灵哨兵在这里被食尸鬼困住，邪恶的伊瓦打伤了其中的奎恩·尤瑞克，之后奎恩和他的亲人兰妮躲进伊瓦的旧宅，筑起了路障。",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "洛丹米尔湖",
			short = "洛丹米尔湖延展在那些曾以湖岸为家的王国的阴影之下。",
			full = "洛丹米尔湖延展在那些曾以湖岸为家的王国的阴影之下。洛丹伦崛起于它的北岸，这片湖泊很可能就是以那座伟大的城市命名的，而那座城市本身又得名于古时的洛丹。在洛丹伦联盟将人类王国团结在一起的年代，达拉然和奥特兰克也曾在湖畔繁荣昌盛。\n\n那个时代已经过去，留下来的只是一条边界。如今这片湖泊横亘在被遗忘者控制的提瑞斯法林地、银松森林与争夺不休的奥特兰克山脉之间，将死者与生者分隔开来。\n\n湖的中心是芬里斯岛，岛上的城堡被图勒·鸦爪统领的腐皮豺狼人占据着。\n\n在芬里斯岛以东，邪鳍鱼人占据了那些小小的黎明岛，将它们完全据为己有。",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "玛尔丁果园",
			short = "玛尔丁果园里的树木已经变得阴暗而常青，果实一季又一季地挂在枝头，无人采摘。玛尔丁本人早已离去，当天灾军团降临洛丹伦时，他被赶出了自己的家园。",
			full = "玛尔丁果园里的树木已经变得阴暗而常青，果实一季又一季地挂在枝头，无人采摘。玛尔丁本人早已离去，当天灾军团降临洛丹伦时，他被赶出了自己的家园。\n\n如今，这座果园属于座狼，它们成群地在树林间和那座仍然矗立着的小屋周围筑窝。亡灵哨兵埃尔兰·麦克基正是走进了这样一个地方，他奉命在侦察森林北部期间探查这座果园。他还没走多远就被座狼逼得无路可逃，只好躲进那座废弃的小屋，筑起路障，在那里被困了好几天，直到其他被遗忘者特工帮助他逃脱，回到了等待着他的同伴身边。",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "北流谷",
			short = "北流谷位于银松森林中瑟伯切尔的正北方。这里是月怒狼人的众多巢穴之一，它们效命于大法师阿鲁高。",
			full = "北流谷位于银松森林中瑟伯切尔的正北方。这里是月怒狼人的众多巢穴之一，它们效命于大法师阿鲁高。它们在这里搭起简陋的营地，只保留生存所需的最基本的必需品，对于这些靠利齿和蛮力生存的生物来说，这样的栖身之所已经足够了。",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "北流海岸",
			short = "银松森林的西北海岸线，也就是海滩与寒冷的无尽之海相接的地方，被称为北流海岸。",
			full = "银松森林的西北海岸线，也就是海滩与寒冷的无尽之海相接的地方，被称为北流海岸。一艘残破的部落船只半沉在浅滩上，船体陷在浪花之中，是这段海岸上最显眼的标志。",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "奥森农场",
			short = "奥森农场曾经坐落在穿越银松森林的商路边上，是一座正常运作的农庄，它的田地为过往的商旅提供食粮。",
			full = "奥森农场曾经坐落在穿越银松森林的商路边上，是一座正常运作的农庄，它的田地为过往的商旅提供食粮。\n\n第三次战争终结了这一切。短短几年之内，这座农场就沦为了废墟。",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "焚木村",
			short = "焚木村位于银松森林的边缘，是一群在第三次战争中天灾军团首次来袭时幸存下来的人类聚居之地。",
			full = "焚木村位于银松森林的边缘，是一群在第三次战争中天灾军团首次来袭时幸存下来的人类聚居之地。村子的北面矗立着一座城堡，曾经属于席瓦莱恩男爵，由圣骑士指挥官斯普林瓦尔和白银之手守卫。席瓦莱恩和他的部下被大法师阿鲁高的狼人屠杀殆尽，阿鲁高将城堡据为己有，并将它更名为影牙城堡。阿鲁高从那里将他的疯狂转向了焚木村本身，他诅咒了村民，让他们每到夜晚就变成垂涎欲滴的月怒狼人，撕咬任何挡住他们去路的人，到了黎明又重新变回人类。\n\n尽管如此，村子白天依然向旅人敞开大门，村民们被阿鲁高施加在他们身上的诅咒所束缚，看不到任何解脱的希望。",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "瑟伯切尔",
			short = "瑟伯切尔坐落在银松森林西部的丘陵之上，俯瞰着洛丹伦的海岸线，那里曾有一条道路穿过一座简朴的墓地，墓穴不过是死者的安息之所。",
			full = "瑟伯切尔坐落在银松森林西部的丘陵之上，俯瞰着洛丹伦的海岸线，那里曾有一条道路穿过一座简朴的墓地，墓穴不过是死者的安息之所。\n\n第三次战争之后，被遗忘者占据了这座古老的墓地，并将它改造成了一处行动基地，把一个为死者而建的地方，变成了为不死者服务的地方。\n\n这个选择出于迫不得已。南面有狼人出没，东面仍被天灾军团占据，东南方则有肯瑞托在虎视眈眈。在几乎四面受敌的情况下，被遗忘者发现，瑟伯切尔是银松森林中少数几个部落能够安全立足的地方之一。",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "影牙城堡",
			short = "影牙城堡矗立在焚木村上方的一座高崖之上。它曾经属于吉尔尼斯的一位领主席瓦莱恩男爵，直到天灾军团降临洛丹伦，皇家大法师阿鲁高开始寻找阻止他们的方法。",
			full = "影牙城堡矗立在焚木村上方的一座高崖之上。它曾经属于吉尔尼斯的一位领主席瓦莱恩男爵，直到天灾军团降临洛丹伦，皇家大法师阿鲁高开始寻找阻止他们的方法。阿鲁高借助法师乌尔的研究，在吉恩·格雷迈恩国王的准许下，却违背了肯瑞托的忠告，召唤出了狼人。它们击退了亡灵的浪潮，随后却转而攻击吉尔尼斯本身，在格雷迈恩之墙上肆虐，接着又在银松森林中四处横行。它们扑向这座城堡，杀死了席瓦莱恩男爵和他的家人。\n\n阿鲁高被他亲手释放出来的东西击垮了，却没有逃离。他称狼人为自己的孩子，将城堡据为己有，并将其更名为影牙城堡。他与他在狼之教团中侍奉的一位主人交流，将诅咒散布到整片森林，直到连焚木村本身也被转化，村民们白天是人，夜晚是野兽，由一个只听命于他的议会统治着。",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "闪光湖岸",
			short = "闪光湖岸沿着洛丹米尔湖延伸，从北方的洛丹伦都城一直延伸到分隔银松森林与奥特兰克山脉的崎岖丘陵。",
			full = "闪光湖岸沿着洛丹米尔湖延伸，从北方的洛丹伦都城一直延伸到分隔银松森林与奥特兰克山脉的崎岖丘陵。\n\n邪鳍鱼人部族在湖岸上密密麻麻地建起了他们的聚居地，那些不熟悉这段湖岸的旅人已经学会了对它心存畏惧。已故的药剂师伯拉德在他的日记中写到，可以从邪鳍鱼人那里得到一种稀有的东西，那就是硬化肿瘤，他推测这种东西或许可以被用来制造一种新的瘟疫。",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "粘丝洞",
			short = "这座被称为粘丝洞的矿洞已被粘丝蜘蛛占据，它们的蛛网覆盖在破损的木梁和生锈的工具上。",
			full = "这座被称为粘丝洞的矿洞已被粘丝蜘蛛占据，它们的蛛网覆盖在破损的木梁和生锈的工具上。在矿洞深处藏着粘丝蛛母，一只长得无比巨大的蜘蛛，她在自己从不离开的黑暗中统治着蛛群。在洞外，稀有的织影者克雷希斯有时会独自在岩石间潜行。\n\n地上散落着一个个虫茧，里面裹着狼人、座狼和熊，还有从西边海岸的一艘沉船上拖来的兽人。",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "南流海岸",
			short = "南流海岸沿着银松森林的西南海岸延伸，那里是陆地与无尽之海相接的地方。",
			full = "南流海岸沿着银松森林的西南海岸延伸，那里是陆地与无尽之海相接的地方。",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "瓦尔甘牧场",
			short = "瓦尔甘牧场位于银松森林北部那些荒凉的农场之间，在闪光湖岸以西，一条小河以北。",
			full = "瓦尔甘牧场位于银松森林北部那些荒凉的农场之间，在闪光湖岸以西，一条小河以北。它得名于一位农夫，当天灾军团席卷银松森林时，他被杀害或被赶出了这片土地。在它的鼎盛时期，这座农场可以俯瞰洛丹米尔湖，那景色不负它曾经的名声。\n\n如今，这座农场空无一人，只剩下昔日模样的一片废墟，不过偶尔还能看到夜鞭在这里出没。",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- 西瘟疫之地: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "亡灵壁垒",
			short = "亡灵壁垒矗立在提瑞斯法林地与西瘟疫之地的交界处，是被遗忘者抵御仍在东方集结的天灾军团的防线。",
			full = "亡灵壁垒矗立在提瑞斯法林地与西瘟疫之地的交界处，是被遗忘者抵御仍在东方集结的天灾军团的防线。在这里，被遗忘者的守卫者与银色黎明放下了彼此的分歧，共同对抗这个共同的敌人，他们一同守望着边界，并向东派出战士，打击巫妖王的爪牙。\n\n与提瑞斯法的其他地方不同，这一带看上去完全不像林地。一层瘟疫之雾笼罩在上空，将天空染成了与更远处的西瘟疫之地一样病态的黄灰色。",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "凯尔达隆",
			short = "在达隆米尔湖的岛上，矗立着一座很久以前由人类建造的要塞，其中保存着一块古老的高等精灵符文石。",
			full = "在达隆米尔湖的岛上，矗立着一座很久以前由人类建造的要塞，其中保存着一块古老的高等精灵符文石。第二次战争期间，部落攻占了这座岛屿，洗劫了城堡，并将符文石拆开，铸造成风暴祭坛，古尔丹正是通过这些祭坛，将魔法注入了他部落中的食人魔体内。\n\n城堡得到了重建，成为巴罗夫家族的府邸。随着岁月流转，战争日渐逼近，巴罗夫家族越来越害怕失去他们数十年来积累的一切，于是与诅咒神教的首领克尔苏加德达成了一笔交易。庄园下方的地下墓穴变成了通灵学院，一所研习死灵法术的学校，而这个家族自己的仆人则被交出去，成了亡灵瘟疫的实验对象。不到半年，疫病便爆发开来，杀死了岛上所有的人。受害者并没有就此死去：他们复活成了鬼魂，被束缚着一遍又一遍地重温自己的最后时刻，至今仍在凯尔达隆残破的厅堂中游荡。",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "寒风营地",
			short = "寒风营地位于西瘟疫之地的南大门，在那里，奥特兰克的群山让位于被毒害的土地。它是联盟的旅人还能站立其上、仍可称之为洁净之土的最后一个地方。",
			full = "寒风营地位于西瘟疫之地的南大门，在那里，奥特兰克的群山让位于被毒害的土地。它是联盟的旅人还能站立其上、仍可称之为洁净之土的最后一个地方。\n\n一支规模不大的银色黎明分队驻守在这里，他们手下只有寥寥几名士兵和专家。营地在人数上的不足，由勇气来弥补：这里的人们对安多哈尔的天灾军团要塞和那些向大地播撒死亡的瘟疫之锅展开游击战，他们依靠的是愿意发动突袭然后迅速消失的雇佣兵，而不是去坚守他们根本守不住的阵地。\n\n格雷森·沙东布瑞克公爵将一些前途无量的年轻白银之手骑士派到这里，与指挥官阿什拉姆·瓦罗菲斯特一同在这一地区对抗天灾军团。",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "达尔松之泪",
			short = "达尔松果园曾为一个以自己的姓氏为它命名的家族结出果实。如今，这些果树矗立在西瘟疫之地，名字所铭记的不再是丰收，而是哀伤：达尔松之泪。",
			full = "达尔松果园曾为一个以自己的姓氏为它命名的家族结出果实。如今，这些果树矗立在西瘟疫之地，名字所铭记的不再是丰收，而是哀伤：达尔松之泪。\n\n天灾军团占领了这座农场，将它变成了大地上的一道伤口。他们在农场中心安放了一口巨大的瘟疫之锅，从那以后它就从未停歇，不断向空中喷吐着疫病，由药锅领主玛尔维尼乌斯和为他效力的枯萎亡灵看守着。\n\n达尔松一家从未离开。达尔松夫人至今仍在这片土地上行走，化作一具四处游荡的骷髅，在她生前曾经照料过的土地上翻找着。她的丈夫并没有死在她的身边。他被关进了屋外的厕所，被丢在那里不管，而他在那片上了锁的黑暗中变成的东西，已经不再是一个人，而是一只食尸鬼。",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "达隆米尔湖",
			short = "达隆米尔湖的湖水至今仍记得第二次战争，那时湖面上帆影密布。",
			full = "达隆米尔湖的湖水至今仍记得第二次战争，那时湖面上帆影密布。停泊在这里的船只大多挂着普罗德摩尔舰队的旗帜，在奎尔萨拉斯被焚烧之前，海军上将派出了其中一些船只横渡这片水域，载着图拉扬、奥蕾莉亚·风行者和他们的军队前往斯坦索姆。图拉扬曾考虑继续航行进入奎尔萨拉斯本土，但奥蕾莉亚警告他，精灵绝不会允许人类的船只沿着他们的河流逆流而上，于是舰队转而驶向了斯坦索姆。也正是在这场战争中，祖尔金和他的部下被逼退到湖岸边，这位巨魔督军也被俘虏了。\n\n湖的中央坐落着岛上的城镇凯尔达隆，如今空无一人，曾经由巴罗夫家族掌管。在这座城镇的石头下面隐藏着通灵学院，诅咒神教在那里与他们的亡灵一同行事，一片黑暗就潜伏在这座岛屿那被湖水淹没的寂静之下。",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "费尔斯通农场",
			short = "费尔斯通农场曾经养活过生者。当天灾军团来到这里，不再让它重新成为一座农场时，这一切便终结了。",
			full = "费尔斯通农场曾经养活过生者。当天灾军团来到这里，不再让它重新成为一座农场时，这一切便终结了。\n\n天灾军团在田地的中心安放了一口巨大的瘟疫之锅，从那以后，它就从未停止过运作。蒸汽从锅中源源不断地涌出，充满了疫病。药锅领主比勒莫守卫着它，身边还有骷髅巫师、骷髅剥皮者和垂涎欲滴的食尸鬼，任何活物都无法靠近它而不被沾染。\n\n在东北角，那座老房子依然矗立，詹妮丝·费尔斯通仍然守在那里，在这片曾经为她的家族出产庄稼的土地上徘徊不去。",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "盖罗恩农场",
			short = "西瘟疫之地东缘的这座农场曾经属于德尔·盖罗恩，在它的鼎盛时期，人们称它为盖罗恩的萌发之地，是一片播种与生长的土地。",
			full = "西瘟疫之地东缘的这座农场曾经属于德尔·盖罗恩，在它的鼎盛时期，人们称它为盖罗恩的萌发之地，是一片播种与生长的土地。如今这里寸草不生。天灾军团占领了这片田地，并在中心安放了一口巨大的瘟疫之锅，这口锅从未停止运作，不断向空中喷吐着充满疫病的蒸汽，直到连大地本身似乎都患上了疾病。药锅领主魂怒与天灾军团的其他军官一同守卫着它，而那些蒸汽还唤来了本不该行走于世间的东西：在残破的田垄间飘荡的萦绕幻象，以及只听从自己饥渴、不受任何主人支配的哀嚎死灵和饥饿怨灵。",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "壁炉谷",
			short = "壁炉谷位于安多哈尔以北，城墙环绕着一座城堡、一座法师塔、一座磨坊和一座矿井，在一片满目疮痍的地区中呈现出一派井然有序的景象。",
			full = "壁炉谷位于安多哈尔以北，城墙环绕着一座城堡、一座法师塔、一座磨坊和一座矿井，在一片满目疮痍的地区中呈现出一派井然有序的景象。多年来，它一直在玛登霍尔德领主提里奥·弗丁的治理下维持着这份秩序，直到他因援助兽人伊崔格而被以叛国罪驱逐。后来，他的儿子泰兰接替了他，成为玛登霍尔德的领主。\n\n后来，壁炉谷庇护了白银之手骑士团的残部，他们在王城陷落之后接受了泰兰提供的庇护。在随后的岁月里，圣骑士们从这里出击，赢得了一场场胜利，直到骑士团被扭曲成血色十字军，并将这座城镇据为己有。",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "玛登霍尔德城堡",
			short = "玛登霍尔德城堡矗立在壁炉谷的中心，早在如今行走于其厅堂中的大多数人有记忆之前便已存在，即使在兽人入侵洛丹伦最黑暗的日子里，它的城墙也从未被攻破。",
			full = "玛登霍尔德城堡矗立在壁炉谷的中心，早在如今行走于其厅堂中的大多数人有记忆之前便已存在，即使在兽人入侵洛丹伦最黑暗的日子里，它的城墙也从未被攻破。多年来，这里一直是提里奥·弗丁的府邸，在一间以一张巨大的橡木桌和一幅将壁炉谷最小的道路都描绘出来的地图为主的议事厅里，这位圣骑士与他的顾问们商讨着领地的事务。提里奥因援助兽人伊崔格而被控叛国，被逐出教会并遭到放逐，玛登霍尔德最终传到了他自己的儿子泰兰手中。\n\n洛丹伦天灾浩劫之后，泰兰在壁炉谷为幸存的白银之手骑士提供了一个家园。亚历山德罗斯·莫格莱尼的死讯传到了这些城墙之内，对背叛的怀疑使骑士团分裂：玛克斯韦尔·泰罗索斯带领他的追随者离开，建立了银色黎明，而留下来的人则自称血色十字军，玛登霍尔德成了他们的要塞，泰兰也被擢升为大领主。",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "北山伐木场",
			short = "北山伐木场位于西瘟疫之地北部，靠近壁炉谷，山坡已被血色十字军砍伐得光秃秃的。",
			full = "北山伐木场位于西瘟疫之地北部，靠近壁炉谷，山坡已被血色十字军砍伐得光秃秃的。十字军经营着这里的磨坊来获取木材，而联盟和部落都有理由想要破坏这一补给。\n\n第三次战争之前，这座磨坊属于纳萨尼尔·杜马一家，他们一直在这片土地上劳作，直到战争和瘟疫将他们赶走。米克·莱文一家也曾在这里劳作过。",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "安多哈尔废墟",
			short = "安多哈尔的废墟位于西瘟疫之地的中心，房屋残破不堪，散落在开阔的土地上。",
			full = "安多哈尔的废墟位于西瘟疫之地的中心，房屋残破不堪，散落在开阔的土地上。残存下来的一切被召唤者阿拉基所占据，他是一个拥有相当强大力量的巫妖，还有为他效力的亡灵：在倒塌的石块间拖着身躯前行的食尸鬼，在卫兵曾经站岗的地方站岗放哨的骷髅，哭嚎声回荡在废墟上空的女妖，以及在房屋残骸中笨重地蹒跚而行的憎恶。\n\n阿拉基依然盘踞在这一切的中心，统治着一座再也没能复兴的城市。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "通灵学院",
			short = "在废弃的城市凯尔达隆上方的一处高地上，矗立着一座曾是巴罗夫家族府邸的庄园，这个家族的势力范围从凯尔达隆一直延伸到布瑞尔、南海镇和塔伦米尔。",
			full = "在废弃的城市凯尔达隆上方的一处高地上，矗立着一座曾是巴罗夫家族府邸的庄园，这个家族的势力范围从凯尔达隆一直延伸到布瑞尔、南海镇和塔伦米尔。几十年来，他们过着舒适的统治生活，但随着战争日渐逼近，巴罗夫家族变得愤懑而贪婪，不愿让死亡终结他们所建立的一切。于是他们与诅咒神教的首领克尔苏加德达成了一笔交易，以便在凡人的寿命之外继续保有他们的财富和土地。\n\n短短六个月之内，城堡就腐化成了截然不同的东西。神教的侍僧们在这里研习死灵法术，而这个家族自己的仆人则被交出去，作为亡灵瘟疫的活体实验品。在光明使者乌瑟尔按计划前来拜访这座庄园之前，一种在它的厅堂中培育出来的疫病就被释放到了凯尔达隆。它没有留下一个活口，并将它的受害者束缚起来，让他们此后化作鬼魂四处游荡。\n\n巴罗夫家族的成员自己也复活成了亡灵，仍被束缚在他们出卖了的厅堂之中。如今，凡人死灵法师黑暗院长加丁担任着院长一职，他接替了召唤者阿拉基，而阿拉基自己则是克尔苏加德的继任者。",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "悔恨岭",
			short = "在较为平和的日子里，悔恨岭为安多哈尔服务，是镇上的死者安息的地方，无论贫富，都被安葬在墓穴和简朴的墓碑之下。",
			full = "在较为平和的日子里，悔恨岭为安多哈尔服务，是镇上的死者安息的地方，无论贫富，都被安葬在墓穴和简朴的墓碑之下。当亡灵瘟疫来临时，那份安宁便终结了。随着天灾军团一次又一次地猛攻安多哈尔，这座山丘被填满的速度远远超过了它所能容纳的限度，那些匆忙挖掘、没有标记的坟墓至今仍在守卫者倒下的地方留下一道道伤痕。最终，幸存者们干脆不再安葬他们的死者，他们太害怕瘟疫会让自己的亲人复活过来与自己为敌，于是在墓地以南挖了一个万人坑来焚烧尸体。\n\n这座城镇的最后一个举动也是最令人悲伤的。当阿尔萨斯杀死乌瑟尔大人之后，安多哈尔剩下的人们在山顶上建起了一座宏伟的陵墓，将这位圣骑士残破的遗体安放其中，然后永远地离开了他们的家园。有人说，这座山丘的名字就只是来自那座坟墓。\n\n附近的瘟疫之锅也没有放过这座山丘上的死者。士兵和镇民从他们的墓穴中爬起，守卫着那些曾经由他们填满的坟墓。",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "索多里尔河",
			short = "索多里尔河将西瘟疫之地和东瘟疫之地分隔开来。它发源于遥远的北方恶蛛隧道附近，一路向南流淌，直到注入达隆米尔湖，然后作为达隆米尔河继续向前流去。",
			full = "索多里尔河将西瘟疫之地和东瘟疫之地分隔开来。它发源于遥远的北方恶蛛隧道附近，一路向南流淌，直到注入达隆米尔湖，然后作为达隆米尔河继续向前流去。\n\n河岸已被枯萎所占据。蛆虫和吸血蝙蝠挤满了潮湿的土地，瘟疫熊和蜘蛛在浅滩中潜行，钳嘴龟则潜伏在水流变缓的地方。",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "乌瑟尔之墓",
			short = "乌瑟尔之墓矗立在悔恨岭上，是西瘟疫之地唯一一处圣光仍在抵御这片土地死亡的地方。",
			full = "乌瑟尔之墓矗立在悔恨岭上，是西瘟疫之地唯一一处圣光仍在抵御这片土地死亡的地方。\n\n光明使者乌瑟尔曾经坚守安多哈尔，抵御天灾军团，他与智者图斯贝尔和光明的巴拉多尔并肩作战，身后是白银之手的骑士们。终结那场坚守的正是阿尔萨斯·米奈希尔，他率领他的亡灵大军进攻这座城市，杀死了图斯贝尔、巴拉多尔，以及乌瑟尔本人。\n\n阿尔萨斯留下的遗骸，由乌瑟尔自己的士兵收殓起来。他们将他的遗体运到安多哈尔废墟以南，并在上面建起了一座陵墓。他的墓碑刻画着他生前的模样，一手持着圣光之书，一手握着战锤，墓碑前的碑石上用通用语刻着铭文。\n\n高阶牧师赛尔丹尼斯至今仍守护着这座陵墓，是它的看护者和守卫者。对于追随圣光的人来说，这座坟墓是神圣的，是瘟疫之地少数几个这种虔诚仍有意义的地方之一。",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "哭泣之洞",
			short = "哭泣之洞位于索多里尔河以西，洞中挤满了在被瘟疫污染的土地上滋生的沼泽兽和软泥怪。腐烂的巨兽和腐朽的恐魔在黑暗中蹒跚而行。",
			full = "哭泣之洞位于索多里尔河以西，洞中挤满了在被瘟疫污染的土地上滋生的沼泽兽和软泥怪。腐烂的巨兽和腐朽的恐魔在黑暗中蹒跚而行。据说在更深处，一个名叫空壳的元素生物偶尔会浮出地面，那是一个令人不安的怪异之物。",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "嚎哭鬼屋",
			short = "嚎哭鬼屋曾经是一片农田，为养活生者而耕种。那个用途已经不复存在。",
			full = "嚎哭鬼屋曾经是一片农田，为养活生者而耕种。那个用途已经不复存在。天灾军团占据了这片田地，在中心安放了一口巨大的瘟疫之锅，从那以后它就从未停止运作：充满疫病的蒸汽源源不断地喷涌而出，翻滚着漫过那些曾经生长庄稼的田垄。\n\n这口锅并非无人看守。药锅领主拉扎克在一旁守卫，腐烂食尸鬼、冰冻食尸鬼和恶臭僵尸在他周围游荡，作为这里的看守者被束缚在此地。",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- 东瘟疫之地: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "黑木湖",
			short = "黑木湖的湖水污浊不堪，被腐化的水元素在浑浊的水中盘旋游动。达隆郡的古老编年史声称，掠夺者霍古斯的头颅就沉在湖底那片黑暗中的某处。",
			full = "黑木湖的湖水污浊不堪，被腐化的水元素在浑浊的水中盘旋游动。达隆郡的古老编年史声称，掠夺者霍古斯的头颅就沉在湖底那片黑暗中的某处。\n\n在瘟疫爆发之前，这里曾有一座名叫黑木的城镇，是大元帅奥斯玛·加里索斯的故乡。如今它已荡然无存，只剩下这片以它命名的湖泊。",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
