		["corins crossing"] = {
			name = "考林路口",
			short = "考林路口位于通往安多哈尔、达隆郡、斯坦索姆和提尔之手的道路交汇处，处在魔刃之痕和米雷达尔湖之间。",
			full = "考林路口位于通往安多哈尔、达隆郡、斯坦索姆和提尔之手的道路交汇处，处在魔刃之痕和米雷达尔湖之间。它曾经是一座普通的十字路口小镇，有一座市政厅和一间铁匠铺。\n\n如今，天灾军团挤满了它的街道，而在亡灵之间还游荡着一些根本无法看见的东西，那就是隐形仆从，它们能够看穿潜行，仿佛那根本不存在。穿过考林路口，没有任何一条安静的小路可走。",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "皇冠哨塔",
			short = "皇冠哨塔作为东瘟疫之地的侦察塔之一，守望着这片土地。天灾军团对洛丹伦的入侵席卷了这一地区，这座哨塔至今仍带着伤痕，默默地标记着这片死亡之地。",
			full = "皇冠哨塔作为东瘟疫之地的侦察塔之一，守望着这片土地。天灾军团对洛丹伦的入侵席卷了这一地区，这座哨塔至今仍带着伤痕，默默地标记着这片死亡之地。",
