		["darrowshire"] = {
			name = "达隆郡",
			short = "达隆郡曾经是一座独立的村庄，直到第三次战争将天灾军团带到了它的门前。一个名叫掠夺者霍古斯的食尸鬼领主率领了这次进攻，与他一同进攻的还有死亡骑士马杜克·布莱克波尔。",
			full = "达隆郡曾经是一座独立的村庄，直到第三次战争将天灾军团带到了它的门前。一个名叫掠夺者霍古斯的食尸鬼领主率领了这次进攻，与他一同进攻的还有死亡骑士马杜克·布莱克波尔。村子的守卫者起初的抵抗颇有成效，但战局随后逆转，最终他们每一个人都被屠杀殆尽。\n\n死亡并没有终结他们。倒下的人们复活成了食尸鬼，被束缚着为杀死他们的那支天灾军团效力，他们的灵魂被困在曾经属于自己的腐烂血肉之中。\n\n如今，达隆郡本身寂静而残破，除了鬼魂与回忆之外，空无一物。",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
