		["fungal vale"] = {
			name = "蘑菇谷",
			short = "在玛瑞斯农场和皇冠哨塔以北，坐落着蘑菇谷，这里的土地在一层浑浊的雾霭下变成了深紫色。",
			full = "在玛瑞斯农场和皇冠哨塔以北，坐落着蘑菇谷，这里的土地在一层浑浊的雾霭下变成了深紫色。亡灵瘟疫在这里扎根最深，天灾军团和诅咒神教在这片腐化之中自由来去，将这片谷地完全据为己有。",
