		["northdale"] = {
			name = "北谷",
			short = "北谷是圣光之愿礼拜堂北面的一座废弃城镇，位于奎尔萨拉斯的边缘。泰兰·弗丁正是在这里放弃了白银之手骑士团，投身血色十字军。",
			full = "北谷是圣光之愿礼拜堂北面的一座废弃城镇，位于奎尔萨拉斯的边缘。泰兰·弗丁正是在这里放弃了白银之手骑士团，投身血色十字军。\n\n如今，女妖和隐形的守望者在废墟中出没。附近的湖泊里栖息着被腐化的水元素。这里已经没有任何活物留存。",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "北地哨塔",
			short = "北地哨塔是东瘟疫之地诸座哨塔中最北的一座，标志着通往奎尔萨拉斯幽魂之地的道路。",
			full = "北地哨塔是东瘟疫之地诸座哨塔中最北的一座，标志着通往奎尔萨拉斯幽魂之地的道路。天灾军团席卷了洛丹伦，这座哨塔至今仍带着伤痕。",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "剧毒林地",
			short = "剧毒林地坐落在圣光之愿礼拜堂北面的一座山丘上，比周围瘟疫之地的其他地方受到了更深的枯萎污染。",
			full = "剧毒林地坐落在圣光之愿礼拜堂北面的一座山丘上，比周围瘟疫之地的其他地方受到了更深的枯萎污染。空气浓重，泛着病态的绿色，大地被染成了深紫色，任何绿色的植物都无法在此生长。\n\n天灾军团将这片林地据为己有：一口瘟疫之锅、一座屠宰场和几座通灵塔矗立在被毒害的土地上，成群的天灾生物在其中游荡。",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "瘟疫之痕",
			short = "瘟疫之痕是枯萎的东瘟疫之地中一道深深的峡谷，很可能原本是一片湖泊，在亡灵瘟疫来袭时干涸了。",
			full = "瘟疫之痕是枯萎的东瘟疫之地中一道深深的峡谷，很可能原本是一片湖泊，在亡灵瘟疫来袭时干涸了。如今它大部分都已干涸，是大地上的一道伤口，谷底栖息着由昔日的腐化所孕育出的软泥怪。",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "病木林",
			short = "斯坦索姆以南的树林曾经青翠而安宁，是一片与艾尔文森林不无相似的林地，林边的石拱附近还坐落着一座小村庄。",
			full = "斯坦索姆以南的树林曾经青翠而安宁，是一片与艾尔文森林不无相似的林地，林边的石拱附近还坐落着一座小村庄。正是在这里，当克尔苏加德开始他的行动时，出生在那座村庄的洛丹伦士兵莫里甘中士第一个注意到，来自安多哈尔的毒粮正在这片土地上造成异变。他的警告对王国来说来得太晚了，而他所守望的那条道路，正是阿尔萨斯王子后来前往斯坦索姆时所走的那条路。\n\n此后留下来的已经不再是一片森林了。脚下的土壤本身变得松软如海绵，蘑菇和毒蕈膨胀得像树木一样大，高耸在古老林地的残迹之上。它们呼出一种深褐色的气体，与天灾军团的瘟疫之锅中升起的烟雾颇为相似，但没有人能够确定，这些真菌只是生长在被毒害的土地上，还是天灾军团特意培育它们来进一步传播疫病。这片树林正是因为这种转变而得到了它的新名字。",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "奎尔林斯小屋",
			short = "奎尔林斯小屋曾是奎尔萨拉斯附近的一座远行者营地，一个温暖而好客的地方。洛瑟玛·塞隆在自己的拜访中对它的记忆便是如此，那些以此为家的同胞们总是热情地迎接他。",
			full = "奎尔林斯小屋曾是奎尔萨拉斯附近的一座远行者营地，一个温暖而好客的地方。洛瑟玛·塞隆在自己的拜访中对它的记忆便是如此，那些以此为家的同胞们总是热情地迎接他。小屋里曾经保存着许多精灵文献，其中一些与王室以及银月城的游侠将军有关。到第二次战争时，伦萨尔·鹰矛领导着那里的猎手。",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "血色十字军营地",
			short = "在米雷达尔湖的东岸，离宗教堡垒提尔之手不远的地方，血色十字军营地矗立在它的路障之后，防御工事已经加固，以应对任何可能到来的威胁。",
			full = "在米雷达尔湖的东岸，离宗教堡垒提尔之手不远的地方，血色十字军营地矗立在它的路障之后，防御工事已经加固，以应对任何可能到来的威胁。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "血色十字军教堂",
			short = "血色十字军教堂矗立在提尔之手之中，是血色十字军信仰的最高圣所，与附近的修道院以及远在提瑞斯法林地的血色修道院紧密相连。",
			full = "血色十字军教堂矗立在提尔之手之中，是血色十字军信仰的最高圣所，与附近的修道院以及远在提瑞斯法林地的血色修道院紧密相连。十字军领主瓦德玛尔掌管着这里，他对十字军事业的忠诚毫无保留。",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "斯坦索姆",
			short = "斯坦索姆的毁灭始于粮食。来自安多哈尔的粮食被诅咒神教暗中感染，做成了面包，被毫不知情的居民吃下，他们从不知道自己正在走向死亡。",
			full = "斯坦索姆的毁灭始于粮食。来自安多哈尔的粮食被诅咒神教暗中感染，做成了面包，被毫不知情的居民吃下，他们从不知道自己正在走向死亡。阿尔萨斯·米奈希尔王子与光明使者乌瑟尔和吉安娜·普罗德摩尔一同抵达时，发现瘟疫已经开始蔓延。阿尔萨斯相信，唯一剩下的仁慈就是让人们干干净净地死去，而不是慢慢变成行尸走肉，于是他下令焚毁这座城市。乌瑟尔和吉安娜拒绝服从，带着他们的部下撤离了。阿尔萨斯却没有。大火席卷了街道，斯坦索姆几乎每一个人都被杀死了，而阿尔萨斯前来追杀的恐惧魔王玛尔加尼斯却大笑着溜走了，只留下这位王子去焚烧剩下的一切。\n\n这还不够。死者依然复活了，这座城市成了天灾军团在洛丹伦的都城，先后由巫妖克尔苏加德和后来的死亡骑士瑞文戴尔男爵统治。\n\n斯坦索姆至今仍在燃烧。",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "恐惧谷",
			short = "恐惧谷坐落在病木林的边缘，街道空荡荡的，已被天灾军团和染上瘟疫的动物所占据。只有商人被感动的奥古斯图斯和幽灵猎人埃根还逗留在这片废墟之中。",
			full = "恐惧谷坐落在病木林的边缘，街道空荡荡的，已被天灾军团和染上瘟疫的动物所占据。只有商人被感动的奥古斯图斯和幽灵猎人埃根还逗留在这片废墟之中。\n\n这座城镇闹鬼。灵魂在它的小巷中游荡，在某些地方，恐惧谷本身似乎摇摇欲坠，物质世界在它之外那个领域的重压下扭曲变形，仿佛这片土地记得某种它无法释怀的古老折磨。\n\n正是这种不安吸引了格雷森·沙东布瑞克公爵，他从这些灵魂身上看到了一场合适的试炼，适合那些寻求证明自己配得上审判与牺牲的圣骑士，这是赢得那些只留给真正值得之人的战马的一步。这些灵魂生前是什么人，并没有记载，只知道它们所受的折磨真实到足以扭曲它们周围的城镇。",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "恶蛛隧道",
			short = "这条隧道从恐惧谷西北方的山中穿过，向南一直延伸到与索多里尔河交汇的地方。",
			full = "这条隧道从恐惧谷西北方的山中穿过，向南一直延伸到与索多里尔河交汇的地方。蛛魔地穴恶魔塞满了整条通道，而在它们之间还潜行着更可怕的东西：一只蛛魔监工，远比它的同类致命。\n\n在河边的隧道口，提里奥·弗丁守望着，从外面的光明中直面通道里的黑暗。",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "索多里尔河",
			short = "索多里尔河将西瘟疫之地和东瘟疫之地分隔开来。它发源于遥远的北方恶蛛隧道附近，一路向南流淌，直到注入达隆米尔湖，然后作为达隆米尔河继续向前流去。",
			full = "索多里尔河将西瘟疫之地和东瘟疫之地分隔开来。它发源于遥远的北方恶蛛隧道附近，一路向南流淌，直到注入达隆米尔湖，然后作为达隆米尔河继续向前流去。\n\n河岸已被枯萎所占据。蛆虫和吸血蝙蝠挤满了潮湿的土地，瘟疫熊和蜘蛛在浅滩中潜行，钳嘴龟则潜伏在水流变缓的地方。",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "提尔之手",
			short = "提尔之手是一座设防的人类城市，也是这一地区生者抵抗天灾军团的最后据点之一。",
			full = "提尔之手是一座设防的人类城市，也是这一地区生者抵抗天灾军团的最后据点之一。它的周边环境比瘟疫之地的其他地方要好得多，尽管树木和花草依然在腐朽。\n\n这座城市是圣光教会最古老、最受尊崇的圣地之一，几乎全部由教堂组成，其中最为宏伟的是血色十字军教堂和那座设防的修道院。\n\n当天灾军团到来，东威尔德变成瘟疫之地的时候，提尔之手并没有陷落。在瓦德玛尔领主的统治下，它经受住了每天的攻击，先是由白银之手骑士庇护，后来又由血色十字军守护，并不断向其他血色十字军据点输送补给和援军，每天都有信使从斯坦索姆带来报告，而他们不得不在瘟疫弥漫的道路上一路杀出一条血路。",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "墓室",
			short = "墓室是东瘟疫之地西南部的一座地穴，是亡灵巨魔的家园，由复活的恐怖巨魔流亡者塞达尔统领。",
			full = "墓室是东瘟疫之地西南部的一座地穴，是亡灵巨魔的家园，由复活的恐怖巨魔流亡者塞达尔统领。他从这里袭击银色黎明在圣光之愿礼拜堂的墓坑，把尸体偷走据为己有。",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "祖玛沙尔",
			short = "祖玛沙尔曾是苔皮部族的都城，他们是东瘟疫之地东北部的森林巨魔。",
			full = "祖玛沙尔曾是苔皮部族的都城，他们是东瘟疫之地东北部的森林巨魔。与洛丹伦人类之间的长期战争使这个部族的土地陷入混乱，而随后而来的亡灵瘟疫更是带来了更深重的毁灭。曾经统治这里的城市，如今只剩下昔日荣光的一抹残影。\n\n它的金字形神塔玛兹拉罗依然矗立在城市的中心，如今由督军塞雷辛和祖尔布林·扭枝占据。然而苔皮部族自己的族人正在被瘟疫暗中转化，祖玛沙尔正面临着沦为亡灵堡垒的危险。",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- 希尔斯布莱德丘陵: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "碧玉矿洞",
			short = "碧玉矿洞位于希尔斯布莱德丘陵的西南部，在格雷迈恩之墙拔地而起、将那个王国与世隔绝之前，它所在的山丘曾被算作吉尔尼斯的一部分。",
			full = "碧玉矿洞位于希尔斯布莱德丘陵的西南部，在格雷迈恩之墙拔地而起、将那个王国与世隔绝之前，它所在的山丘曾被算作吉尔尼斯的一部分。\n\n这座矿洞属于联盟，矿工们在卫兵的看守下劳作，开采出的铁矿供给联盟的军械库。",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
