			full = "破碎岭城堡耸立在奥特兰克废墟附近，是一个在土丘中挖出的洞穴。破碎岭食人魔在它的周围建起了营地，他们数量众多，性情粗暴，占据着下方那座废墟之城上方的山坡。",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "达隆山",
			short = "达隆山位于希尔斯布莱德丘陵北部，在山头营地的下方。",
			full = "达隆山位于希尔斯布莱德丘陵北部，在山头营地的下方。美洲狮和雄鹿在它开阔的原野上游荡，而在丘陵洞穴中，雪人筑起了巢穴，周围是贯穿岩石的奥特兰克花岗岩矿脉。",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "丹加洛克",
			short = "丹加洛克矗立在希尔斯布莱德丘陵的山丘之中，是一座由达伦·铁山上尉指挥的矮人城堡。",
			full = "丹加洛克矗立在希尔斯布莱德丘陵的山丘之中，是一座由达伦·铁山上尉指挥的矮人城堡。他的守军保护着希尔斯布莱德的人类，并守卫着碧玉矿洞，这是被遗忘者无法容忍的存在，他们悬赏黄金，招募任何愿意潜入城堡、将城中矮人斩尽杀绝的人。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "敦霍尔德城堡",
			short = "敦霍尔德城堡残破地矗立在塔伦米尔以东，兵营和法师塔都已坍塌，竞技场也一片寂静。",
			full = "敦霍尔德城堡残破地矗立在塔伦米尔以东，兵营和法师塔都已坍塌，竞技场也一片寂静。它曾经是第二次战争后建立的兽人收容体系的中枢，由中将艾德拉斯·布莱克摩尔统治，这个自私自利的酒鬼利用收容所来谋求自己的晋升。\n\n正是布莱克摩尔在一对被杀害的父母的尸体中发现了一个兽人婴儿，并把他带回了城堡，为他取名萨尔。这个男孩在那里被抚养长大，接受教育，由一名人类妇女为他哺乳，而她的女儿塔蕾莎·福克斯顿与他变得十分亲近。多年来，布莱克摩尔一直殴打这个男孩，让他在角斗场里搏斗，利用他的力量来往上爬。塔蕾莎偷偷地给他写信，他也给她回信，直到最后他告诉她，他打算逃走。她制造了一场骚乱让他得以脱身，在城墙外与他会合，并在他离开之前给了他补给。\n\n多年以后，他确实回来了，率领着他召集起来的自由兽人。萨尔围攻了敦霍尔德，在单挑中杀死了布莱克摩尔，并召唤大地之灵将这座要塞彻底夷为平地。此后，残存下来的废墟吸引了辛迪加，他们将这片废墟据为己有。",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "东部海滩",
			short = "东部海滩沿着希尔斯布莱德丘陵的东南海岸延伸，与它相对应的那片海滩则位于同一海岸更靠西的地方。",
			full = "东部海滩沿着希尔斯布莱德丘陵的东南海岸延伸，与它相对应的那片海滩则位于同一海岸更靠西的地方。这片沙滩属于刺脊纳迦，他们占据着海滩以及海滩外的浅水。",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "绞刑场",
			short = "在绞刑场，也就是奥特兰克山脉中靠近奥特兰克残破厅堂的道路交汇处，一座侦察塔残破而空荡地矗立着。",
			full = "在绞刑场，也就是奥特兰克山脉中靠近奥特兰克残破厅堂的道路交汇处，一座侦察塔残破而空荡地矗立着。如今破碎岭食人魔占据着这个路口，在塔的残骸周围的石头间徘徊，除此之外，那里再没有任何动静。",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "加文高地",
			short = "加文高地是希尔斯布莱德四座山丘中的最后一座，也是守卫最严密的一座。",
			full = "加文高地是希尔斯布莱德四座山丘中的最后一座，也是守卫最严密的一座。\n\n美洲狮在这座山丘上游荡，其中就有毛色与众不同的阿拉加。",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "无草洞",
			short = "在奥特兰克山脉中，一个洞穴庇护着山地雪人，洞口外常常可以见到斯克豪尔。",
			full = "在奥特兰克山脉中，一个洞穴庇护着山地雪人，洞口外常常可以见到斯克豪尔。洞穴深处矗立着乌泽尔之火，那是人类赫尔库拉为了让自己变成巫妖的仪式而堆起的火堆。在火堆上焚烧的肉会把强大的雪人霜喉雪人引到洞口。",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "山头营地",
			short = "山头营地是伸向希尔斯布莱德的几片指状陆地之一。",
			full = "山头营地是伸向希尔斯布莱德的几片指状陆地之一。\n\n在这里的崖壁上，阿拉加与她的幼崽们一同休憩。",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "希尔斯布莱德农场",
			short = "希尔斯布莱德农场肥沃而精耕细作，遍布希尔斯布莱德丘陵的西部，养活着南海镇，此外还有希尔斯布莱德镇。",
			full = "希尔斯布莱德农场肥沃而精耕细作，遍布希尔斯布莱德丘陵的西部，养活着南海镇，此外还有希尔斯布莱德镇。苹果园、南瓜田和吃草的牛群覆盖着这片土地，碧玉矿洞至今仍有镇上的居民在开采。\n\n第二次战争初期，毁灭之锤率军进攻希尔斯布莱德，以一场骇人的屠戮将其摧毁，作为对人类王国的警告。战后，它得到了重建，至今依然人丁兴旺，是昔日洛丹伦少数几个既没有沦为废墟、也没有被血色十字军吞并的角落之一；这里的卫兵仍然身穿他们王国的战袍，伯恩赛德镇长在希尔斯布莱德议会和书记员霍拉斯·怀特斯迪的辅佐下，在市政厅中治理着这里。\n\n如今，这些农田再次受到威胁，这次的威胁来自高级执行官达萨利亚在塔伦米尔的部队。农夫和佃户们承受着一次又一次的袭击，但许多人也以自己的伏击反击亡灵，他们的武器由铁匠维林坦和他的学徒们提供。",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "雾气湖岸",
			short = "雾气湖岸沿着洛丹米尔湖延伸，位于达伦德农场和达拉然之间。海龟在它的浅滩中缓缓爬行。",
			full = "雾气湖岸沿着洛丹米尔湖延伸，位于达伦德农场和达拉然之间。海龟在它的浅滩中缓缓爬行。\n\n两名血色十字军的成员占据着这片湖岸，扑向任何过于靠近的人，仿佛这片土地本身需要守卫一般。\n\n隔着湖水可以望见黎明岛，芬里斯城堡在雾气中若隐若现，阴沉地矗立着。",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "奈杉德哨岗",
			short = "奈杉德哨岗位于南海镇的正东方，它的田地早已荒废，被泥鼻豺狼人占据，这是这个部族唯一的栖身之地。",
			full = "奈杉德哨岗位于南海镇的正东方，它的田地早已荒废，被泥鼻豺狼人占据，这是这个部族唯一的栖身之地。一种名叫泥鼻花的巨大白色蘑菇在那里野蛮生长，药剂师林度恩曾经寻找过它们，用来调制他那致命的苦楚药剂。",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "赎罪岛",
			short = "一座螺旋状的石岛耸立在希尔斯布莱德海岸以南，岛顶有一片墓地和一座侦察塔的残骸。第一次战争之前，赎罪岛属于库尔提拉斯。",
			full = "一座螺旋状的石岛耸立在希尔斯布莱德海岸以南，岛顶有一片墓地和一座侦察塔的残骸。第一次战争之前，赎罪岛属于库尔提拉斯。\n\n此后发生了什么已无从知晓，但死者并没有安息。数十个灵魂在岛上游荡，有人类也有矮人，有圣骑士和牧师，也有武僧和法师，都是被束缚在这些石头上的罪人之魂。",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "拉文霍德庄园",
			short = "拉文霍德庄园是有意与世隔绝的。",
			full = "拉文霍德庄园是有意与世隔绝的。只有一条狭窄而曲折的小路可以通往那里，它从敦霍尔德城堡西北方的一座高原上攀升，蜿蜒穿过群山和一个小洞穴，然后才通向庄园的地界，这座庄园不是一个人们会偶然撞见的地方。这里不欢迎外人，而那些效忠于乔拉齐·拉文霍德公爵的人则确保这一点始终如此。\n\n这座庄园是他的产业，屋顶是橙色的，保留着奥特兰克的古老风格，在第一次战争之前，奥特兰克王国曾经拥有这片土地。\n\n在此后的岁月里，辛迪加一直在这片高地上游荡，而拉文霍德则凭借它隐秘的小路和戒备森严的大门，抵御着这一祸患。",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "屠杀谷",
			short = "在奥特兰克山脉深处，破碎岭食人魔在屠杀谷安了家，那是一座陷入山丘之中的土丘。",
			full = "在奥特兰克山脉深处，破碎岭食人魔在屠杀谷安了家，那是一座陷入山丘之中的土丘。人们对这个地方所知甚少，只知道占据它的是食人魔，但单凭这个名字，就足以说明任何过于靠近的人会遭遇什么。",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "索菲亚高地",
			short = "索菲亚高地是希尔斯布莱德四指之一。辛迪加占据着这座山丘，监视着下方的土地。",
			full = "索菲亚高地是希尔斯布莱德四指之一。辛迪加占据着这座山丘，监视着下方的土地。",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "南点哨塔",
			short = "南点哨塔矗立在希尔斯布莱德丘陵的最西端，就在通往银松森林的道路以南。",
			full = "南点哨塔矗立在希尔斯布莱德丘陵的最西端，就在通往银松森林的道路以南。它的石砌结构古老而开裂，是一座被遗弃而日渐荒废的侦察哨所，不过在经过这里的战斗中，哨塔本身从未被摧毁。在附近，塔伦米尔和南海镇之间还矗立着另一座没有名字的哨塔，它也躲过了席卷丘陵其他地方的破坏。",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "斯坦恩布莱德",
			short = "斯坦恩布莱德坐落在奥特兰克山脉东北部的山麓，它的市政厅和铁匠铺如今都已空无一人。",
			full = "斯坦恩布莱德坐落在奥特兰克山脉东北部的山麓，它的市政厅和铁匠铺如今都已空无一人。它曾经属于奥特兰克王国，第二次战争之后又落入了洛丹伦之手。\n\n这座城镇的毁灭始于第三次战争前不久，当时黑石兽人袭击了这里，要抓捕奴隶献祭给燃烧军团。斯坦恩布莱德只有寥寥几名步兵来保卫它，但消息及时传到了白银之手骑士那里。光明使者乌瑟尔先行一步，试图拦截这次袭击，而阿尔萨斯·米奈希尔王子则奉命前去守卫城镇本身。阿尔萨斯没能及时赶到。在他抵达斯坦恩布莱德之前，迪恩、乔、迈克、斯科特和其他许多人都已被杀，剩下的守卫者与他一同击溃了兽人，并杀死了领导这次袭击的奴隶主。联盟赢得了这场战斗，但斯坦恩布莱德的人民早已不在了。\n\n后来，辛迪加占据了这座残破的城镇，把它当作夺取奥特兰克山脉的要塞，并将兽人高迪尔关押在其中一间牢房里，把他当作奴隶，让他搬运和挖掘。",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "塔伦米尔",
			short = "塔伦米尔曾经是奥特兰克山脉下方草原上一座普通的洛丹伦小镇。",
			full = "塔伦米尔曾经是奥特兰克山脉下方草原上一座普通的洛丹伦小镇。第二次战争初期，来自银月城的高等精灵弓箭手被派往南方，亲眼察看兽人的威胁，却在小镇附近遭到伏击，被拖进了附近的一座囚营。泰瑞纳斯国王派出联盟士兵去解救他们，营救取得了成功。正是这次成功，促使银月议会让奎尔萨拉斯的军队加入了洛丹伦联盟。\n\n塔伦米尔并没有一直掌握在人类手中。后来被遗忘者占领了它，并像对待他们的其他据点一样对待它：一座教堂，几间零散的房屋，几片已经腐烂的果园，一切都还立着，却没有一样是完整的。被遗忘者从这里发动对南海镇和丹加洛克联盟军队的战争，而塔伦米尔与南海镇之间的土地，也因为这两座城镇之间一场又一场的冲突而恶名远扬，双方谁也无法击溃对方。",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "索拉丁之墙",
			short = "索拉丁国王修筑了这道城墙以抵御阿曼尼巨魔，那时斯托姆还年轻，阿拉索也才刚刚为人类夺得这片土地。",
			full = "索拉丁国王修筑了这道城墙以抵御阿曼尼巨魔，那时斯托姆还年轻，阿拉索也才刚刚为人类夺得这片土地。世世代代以来，它如同一名坚定的哨兵屹立于此，是任何巨魔大军都无法逾越的防线。\n\n几百年后，它依然屹立，却已严重损毁，石块破碎，它漫长的守望也沦为了一片废墟。",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "西部海岸",
			short = "西部海岸位于希尔斯布莱德丘陵的西南海岸。碎鳍鱼人沿着海岸建起了小型营地，而安迪·莫戈尔在这片水域巡逻，监视着它们所栖居的海岸线。",
			full = "西部海岸位于希尔斯布莱德丘陵的西南海岸。碎鳍鱼人沿着海岸建起了小型营地，而安迪·莫戈尔在这片水域巡逻，监视着它们所栖居的海岸线。",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- 辛特兰: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "鹰巢山",
			short = "蛮锤矮人最初选择的并不是辛特兰。",
			full = "蛮锤矮人最初选择的并不是辛特兰。他们的家园是深藏于山中的格瑞姆巴托，直到三锤之战结束，矮人们回到那里，才发现他们的要塞已被莫德古德之死所污染。格瑞姆巴托再也无法居住。于是蛮锤矮人在这里重建家园，他们把家建在山坡之上，而不是山体之中，因为在经历了与黑铁矮人在隧道中作战的恐怖之后，他们再也不愿把自己埋进岩石里。鹰巢山之所以向天空敞开，正是因为那场战争。\n\n正是在这里，库德兰·蛮锤率领他的狮鹫骑士迎击兽人军队，那支兽人军队被派来进攻辛特兰作为佯攻，而部落的真正主力则向奎尔萨拉斯进军。安度因·洛萨的军队前来援助他，帮助他将兽人和森林巨魔赶出了蛮锤的土地，为此，库德兰承诺他的氏族将效忠联盟。\n\n在库德兰没有归来之后，弗斯塔德·蛮锤被留下来担任大领主，至今仍统治着鹰巢山。辛特兰的森林巨魔称蛮锤矮人为侵占祖先土地的外来者，他们仍在袭击狮鹫栖地，而奎尔丹尼的高等精灵则始终是矮人对抗这同一敌人的盟友。",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "亚戈瓦萨",
			short = "亚戈瓦萨的石头比最后一批将它们奉为圣物的巨魔更加古老，它是在阿曼尼帝国覆灭之前作为帝国的神庙而建造的。",
			full = "亚戈瓦萨的石头比最后一批将它们奉为圣物的巨魔更加古老，它是在阿曼尼帝国覆灭之前作为帝国的神庙而建造的。后来的邪枝巨魔将这片遗迹据为己有。如今，这座神庙已被活化的软泥占据，它们填满了它那破碎的庭院。",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "祖尔祭坛",
			short = "祖尔祭坛耸立在辛特兰，是邪枝森林巨魔为举行他们古老的仪式而建造的。守护者奇尔加守在石坛顶上，守护着祭坛中仍然蕴藏的任何力量。",
			full = "祖尔祭坛耸立在辛特兰，是邪枝森林巨魔为举行他们古老的仪式而建造的。守护者奇尔加守在石坛顶上，守护着祭坛中仍然蕴藏的任何力量。",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
