		["hiriwatha"] = {
			name = "西利瓦萨",
			short = "枯木巨魔占据着西利瓦萨，这座村庄位于辛特兰的奎尔丹尼小屋以南，深藏在他们视为己有的森林之中。",
			full = "枯木巨魔占据着西利瓦萨，这座村庄位于辛特兰的奎尔丹尼小屋以南，深藏在他们视为己有的森林之中。",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "辛萨罗",
			short = "辛萨罗层层叠叠地耸立在辛特兰之上，在森林巨魔的城市中，它的规模仅次于祖阿曼。",
			full = "辛萨罗层层叠叠地耸立在辛特兰之上，在森林巨魔的城市中，它的规模仅次于祖阿曼。它建于阿曼尼帝国时期，得名于阿曼尼古代的领袖之一辛萨。\n\n这座城市属于邪枝部族，他们将城市的高处变成了一座献祭的堡垒。邪恶祭司海克斯在那里统治，侍奉着夺魂者哈卡，邪枝巨魔毫不留情地捕食较弱小的恶齿部族，以满足他们神灵的饥渴。恶齿部族的断齿长者就是在一次这样的袭击中被掳走的，至今仍被囚禁在城中；他的卫队队长猎手玛尔克霍也在同一次袭击中被俘并遭到处决，他的遗骸被扔给了城墙内豢养的狼和软泥怪。\n\n蛮锤氏族和恶齿部族因对邪枝巨魔怀有共同的仇恨而走到了一起，他们联手围攻这座城市，力图终结它的袭掠，为他们的死者报仇雪恨。",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "望海崖",
			short = "望海崖标志着辛特兰不再是群山、而化为天空的地方。",
			full = "望海崖标志着辛特兰不再是群山、而化为天空的地方。蜿蜒流经这一地区的大河在这里汇聚，化作一道巨大的瀑布从崖边倾泻而下，落向下方的海岸线。\n\n这些悬崖陡峭异常，高度也极具欺骗性。许多走到崖边的人错判了落差，失足坠亡。",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "毒雾峡谷",
			short = "在奎尔丹尼小屋以西，一层雾气笼罩在山壁裂开的地方，标志着那道向北切向凯尔达隆的峡谷。通道里没有任何生命。",
			full = "在奎尔丹尼小屋以西，一层雾气笼罩在山壁裂开的地方，标志着那道向北切向凯尔达隆的峡谷。通道里没有任何生命。没有鸟儿飞过，也没有野兽在它的岩石间筑窝。\n\n周围的辛特兰依然青翠而洁净，但这道峡谷却吐出别样的气息，一种不属于这片森林的雾霭。这就是这个地方如今拥有这个名字的原因：毒雾，这个名字来自那层病态的雾气，它玷污了这唯一的一条通道，而这片土地的其他地方却安然无恙。",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "奎尔丹尼小屋",
			short = "奎尔丹尼小屋是高等精灵最后几处真正的聚居地之一，也是洛丹伦仅存的两处此类定居点中较大的一处。",
			full = "奎尔丹尼小屋是高等精灵最后几处真正的聚居地之一，也是洛丹伦仅存的两处此类定居点中较大的一处。第三次战争之后，这里成了一个通信往来之地，它的使节们与联盟的其他种族建立联系。这种外交为高谷精灵赢得了与蛮锤矮人的同盟，却也为他们招来了恶齿巨魔的仇恨，后者企图屠杀这些精灵，焚毁他们的记录。那些文献保存了下来，记录着死亡、出生、季节的更替，以及精灵们签订过的每一份条约。",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "恶齿村",
			short = "恶齿村坐落在辛特兰的海岸边，是一个选择了忠诚而非生存的森林巨魔部族最后的家园。",
			full = "恶齿村坐落在辛特兰的海岸边，是一个选择了忠诚而非生存的森林巨魔部族最后的家园。\n\n当旧部落在第二次战争中崩溃时，俘获兽人的人转而对付他们昔日的盟友，而各地的森林巨魔部族都毫不犹豫地抛弃了部落。恶齿部族却没有。他们没有足够的人手去解救被俘的兽人，何况那些兽人本身也没有表现出多少想要获得自由的意愿，但他们始终如一的忠诚，使他们成了其他那些再也不想与兽人有任何瓜葛的巨魔的攻击目标。恶齿部族被赶出了自己的土地，逃到了辛特兰的海岸，希望与世隔绝能保他们平安，并在那里建起了他们的村庄。\n\n最终，消息传到了他们那里：萨尔重建了部落，带领他的人民回归了祖先的萨满之道。恶齿部族派出他们跑得最快的信使去寻找他，那次会面之后，部族与新部落之间便缔结了友好的盟约。其他森林巨魔从未原谅这件事，他们称恶齿部族懦弱而奸诈，而恶齿部族则称那些背弃部落的人才是真正的叛徒。",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "瑟拉丹",
			short = "在辛特兰的东北部坐落着瑟拉丹，那里矗立着一座巨大的环形传送门，向翡翠梦境敞开。这片森林属于绿龙军团，它们被吸引到这里，守护着它们的族类视为神圣的门槛。",
			full = "在辛特兰的东北部坐落着瑟拉丹，那里矗立着一座巨大的环形传送门，向翡翠梦境敞开。这片森林属于绿龙军团，它们被吸引到这里，守护着它们的族类视为神圣的门槛。幼龙罗索斯和追梦者在这些树林间安了家。\n\n守护这片森林的大多是龙人，它们诞生于龙族的力量。它们三个一组行动，一名翠绿先知由枝干守卫和树木守护者护卫在两侧，在纠缠交错的小径上巡逻，常驻守望着通往梦境的道路。",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
