	-- 丹莫罗: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "冻石农场",
			short = "冻石农场坐落在通往洛克莫丹的道路旁，位于古博拉采掘场以北，冻石家族的矮人们在这里饲养牲畜，抵御丹莫罗的严寒。",
			full = "冻石农场坐落在通往洛克莫丹的道路旁，位于古博拉采掘场以北，冻石家族的矮人们在这里饲养牲畜，抵御丹莫罗的严寒。鲁德拉·冻石在这里培育珍贵的公羊，而年幼的雅琳则让她的雪鞋兔在脚边跑来跑去。\n\n这些牲畜并非无忧无虑。一只名叫瓦加什的温迪戈开始尾随农场的牲畜，冻石一家不得不保护他们饲养的动物，免遭它的吞食。",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "安威玛尔",
			short = "在寒脊山谷中矗立着安威玛尔，那是一座围绕着一座巨大锻炉建造的大厅。这是矮人在这片北方地区建立的第一个真正的定居点，在其他任何定居点成形之前，它就已是一处聚会之所。",
			full = "在寒脊山谷中矗立着安威玛尔，那是一座围绕着一座巨大锻炉建造的大厅。这是矮人在这片北方地区建立的第一个真正的定居点，在其他任何定居点成形之前，它就已是一处聚会之所。它中心的锻炉至今仍在燃烧，尽管如今已经没有铁匠在那里传授手艺了。",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "烈酒村",
			short = "烈酒村坐落在寒风峡谷中，靠近诺莫瑞根，是麦酒家族的家园。麦酒家族全身心地投入了一项追求：完善矮人的酿酒艺术。",
			full = "烈酒村坐落在寒风峡谷中，靠近诺莫瑞根，是麦酒家族的家园。麦酒家族全身心地投入了一项追求：完善矮人的酿酒艺术。他们派家中的年轻人走出村子，保护村子免受野兽侵扰，并寻找稀有的原料来酿造终极麦酒。",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "寒风峡谷",
			short = "寒风峡谷在诺莫瑞根和卡拉诺斯之间东西延伸，年轻的矮人和侏儒经常从这里经过，把这条路踩得熟悉无比。",
			full = "寒风峡谷在诺莫瑞根和卡拉诺斯之间东西延伸，年轻的矮人和侏儒经常从这里经过，把这条路踩得熟悉无比。但峡谷也向南北两侧弯折，而在那里，积雪讲述着一个不同的故事：血迹在白雪上大片蔓延，被撕碎的动物尸体被丢弃在地上。很少有人愿意走这条岔路。那些走进去的人是去猎杀罪魁祸首的野兽，希望终结它们对矮人土地的威胁，而许多人再也没有回来。在其中一个洞穴深处，盘踞着一只温迪戈，它正是雪地上那些血迹的最大元凶。",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "寒脊山小径",
			short = "寒脊山小径是走出寒脊山谷的狭窄通道，也是矮人在抵达卡拉诺斯和丹莫罗更宽阔的道路之前必须穿过的最后一段路。",
			full = "寒脊山小径是走出寒脊山谷的狭窄通道，也是矮人在抵达卡拉诺斯和丹莫罗更宽阔的道路之前必须穿过的最后一段路。穴居人占据了这条小径，旅人们只剩下两个选择：要么拼尽全力飞奔而过，要么在入侵者之中杀出一条血路。\n\n芬德里格·红须曾率领另外十二名矿工进入小径，调查这场侵扰。在深处，他被一场落石压住了。其他人折返回去想要把他挖出来，但他们的努力却让整条通道在他们周围坍塌了。十二名矿工丧生。只有从瓦砾中被拖出来的芬德里格幸存了下来。",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "寒脊山谷",
			short = "寒脊山谷积雪深厚，四面环山，唯一的出口是东北方寒脊山小径那条狭窄的隧道。",
			full = "寒脊山谷积雪深厚，四面环山，唯一的出口是东北方寒脊山小径那条狭窄的隧道。那条通道被穴居人掠夺者所侵扰，这些野蛮的家伙长期以来一直让独自前往卡拉诺斯和铁炉堡的旅人身处险境。\n\n过了小径，道路先是向东攀升，然后向北穿过卡拉诺斯，接着蜿蜒穿过群山，一直通往铁炉堡的大门。",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "霜鬃巨魔要塞",
			short = "霜鬃巨魔要塞矗立在丹莫罗寒冷群山的西部边缘，位于诺莫瑞根以南，是一片与深入山坡的洞穴系统相连的零散建筑。",
			full = "霜鬃巨魔要塞矗立在丹莫罗寒冷群山的西部边缘，位于诺莫瑞根以南，是一片与深入山坡的洞穴系统相连的零散建筑。这里是霜鬃冰巨魔的大本营，他们派猎头者和剥皮者守卫着每一条通道，牢牢占据着这片土地。",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "铁炉堡大门",
			short = "铁炉堡大门耸立在丹莫罗那条宏伟的坡道攀升至山体的地方，旅人在抵达之前，隔着雪原数里之外便能望见它们。",
			full = "铁炉堡大门耸立在丹莫罗那条宏伟的坡道攀升至山体的地方，旅人在抵达之前，隔着雪原数里之外便能望见它们。它们是开阔的矮人土地与铁炉堡本身之间的门槛。\n\n穿过大门，便会置身于一座为至高王莫迪姆斯·安威玛尔竖立的巨大雕像的注视之下，雕像就守望在入口内侧，因此任何人进入这座城市之前，都要先从他的目光下经过。",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "诺莫瑞根",
			short = "诺莫瑞根是与它同名的侏儒王国的地下都城，是以锻铁铸就的侏儒才华、雄心和创造力的证明。",
			full = "诺莫瑞根是与它同名的侏儒王国的地下都城，是以锻铁铸就的侏儒才华、雄心和创造力的证明。\n\n第三次战争期间，一场穴居人的入侵导致了它的覆灭。穴居人因泰坦遗址的剧变而从沉睡中被惊醒，从地下蜂拥进入城市。为了杀死入侵者，大工匠格尔宾·梅卡托克在他的顾问希科·瑟玛普拉格的建议下孤注一掷，命令他的人民打开他们那些巨大的研磨机器的压力阀，向整个诺莫瑞根释放有毒的辐射。尽管这种毒气杀死了一些穴居人，却只让另一些变得更加强大，而将近百分之八十的侏儒在几天之内死去。幸存者逃到了铁炉堡寻求庇护。其他人则被扭曲成了可怕、没有心智、作恶多端的麻风侏儒，至今仍在残破的隧道中出没。\n\n瑟玛普拉格自己也被辐射逼疯了，他自封为诺莫瑞根之王，夺取了这座被污染的城市的控制权，率领一支由穴居人和麻风侏儒组成的军队在残破的大厅和工坊中横行。",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "古博拉采掘场",
			short = "古博拉采掘场挖掘在丹莫罗的东南部，这座采矿营地因从地下爬上来的东西而半途而废。",
			full = "古博拉采掘场挖掘在丹莫罗的东南部，这座采矿营地因从地下爬上来的东西而半途而废。矮人们开凿这处采掘场，是为了寻找山中蕴藏的宝物，但挖掘惊醒了穴居人，它们从矿井深处蜂拥而上，占领了矿工们开凿出的矿坑和隧道。\n\n留下来的营地只是一个立足点，而不是一场胜利：矮人们守住了地面，而下方的矿井依然落在穴居人手中。",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "灰色洞穴",
			short = "卡拉诺斯西南方有一片巨大的洞穴群，深深地切入丹莫罗的冰层之中。温迪戈在这里筑起了巢穴，这些毛发蓬乱、口吐寒气的野兽会聚集在一起对付任何闯入者。",
			full = "卡拉诺斯西南方有一片巨大的洞穴群，深深地切入丹莫罗的冰层之中。温迪戈在这里筑起了巢穴，这些毛发蓬乱、口吐寒气的野兽会聚集在一起对付任何闯入者。它们的鬃毛被视为制作坐垫的珍品，但很少有人进去猎取它们之后能不经一番搏斗就出来，因为温迪戈不会四散逃开，而是紧密地聚拢在一起，用利爪和冰冷的吐息将入侵者赶出去。",
