			short = "黑石山并非诞生于寻常的火焰。",
			full = "黑石山并非诞生于寻常的火焰。三锤之战期间，当铜须和蛮锤两大氏族的军队进军去清除黑铁氏族时，巫师领主索瑞森将手伸进了世界熔融的核心，将它的力量拖上来作为武器。回应他的是拉格纳罗斯。炎魔之王的重生撕裂了群山，让周围的土地淹没在火海之中，两位国王都宁可调转他们的军队撤退，也不愿与他正面交锋。在黑铁王国曾经屹立的地方，如今一座火山正在闷燃，南面是燃烧平原，北面是灼热峡谷。拉格纳罗斯退入了山体的核心，奴役了幸存的黑铁矮人，让他们在自己残破的家园下方开凿出暗影熔炉城。",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "大熔炉",
			short = "大熔炉是在灼热峡谷中心挖出的一处巨大采掘场，黑铁矮人在召唤出拉格纳罗斯之后的某个时候对它进行了加固。",
			full = "大熔炉是在灼热峡谷中心挖出的一处巨大采掘场，黑铁矮人在召唤出拉格纳罗斯之后的某个时候对它进行了加固。他们用来将它撕开的巨大机器至今仍环绕在它的边缘。在下方，火元素和熔岩元素在龟裂发光的缝隙间游走。\n\n被黑铁矮人抓来的奴工在那下面无休止地劳作，被繁重的劳动和令人窒息的酷热折磨得精神崩溃。他们已经分不清谁是朋友，谁是俘虏他们的人，面对任何进入的人，他们都会像监工一样以毫无理智的暴力相向。",
