			full = "熔渣之池深深地陷入灼热峡谷的大熔炉采掘场之中，奴隶们在黑铁矮人的残酷驱使下在这里劳作。奴隶贩子和监工驱赶着劳工，就连那些唯唯诺诺的工人也会攻击任何袭击他们监工的人。黑铁矮人对任何干扰他们采矿的行为都报以公开的敌意，而在矿坑更深的黑暗之中，饥饿的熏火龙在挖掘场间筑巢。",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "石坝小径",
			short = "被称为石坝小径的隧道穿过群山，在尘火谷的北端将灼热峡谷与洛克莫丹的国王谷连接起来。",
			full = "被称为石坝小径的隧道穿过群山，在尘火谷的北端将灼热峡谷与洛克莫丹的国王谷连接起来。它出自弗兰克罗恩·铸铁之手，他还建造了巨石水坝，以及东部王国各地许多其他的矮人石工建筑。\n\n洛克莫丹一侧的大门被巡山人贝波蒂紧紧关闭着，除了那些已经在狂暴者玛尔戈面前证明过自己的人之外，任何人都不得通过。",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "制皮匠营地",
			short = "精通元素制皮术的大师萨拉·坦尼在灼热峡谷中守着一顶孤零零的帐篷。帐篷后面有一条长长的通道蜿蜒深入山中，尽头是雷霆蜥蜴狂暴者玛尔戈等候的地方。",
			full = "精通元素制皮术的大师萨拉·坦尼在灼热峡谷中守着一顶孤零零的帐篷。帐篷后面有一条长长的通道蜿蜒深入山中，尽头是雷霆蜥蜴狂暴者玛尔戈等候的地方。",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
