		["thorium point"] = {
			name = "瑟银哨塔",
			short = "在灼热峡谷焦灼的北部矗立着瑟银哨塔，这是一座由瑟银兄弟会控制的中立小镇，居民大多是黑铁矮人，但他们效忠于兄弟会，而不是山脉之下的黑暗力量。",
			full = "在灼热峡谷焦灼的北部矗立着瑟银哨塔，这是一座由瑟银兄弟会控制的中立小镇，居民大多是黑铁矮人，但他们效忠于兄弟会，而不是山脉之下的黑暗力量。一座锻炉和一块铁砧在这里随时待命，在灰烬和酷热之中始终燃着炉火，尽管峡谷已经变成了如今这副模样，这里却仍在锻造金属。",
