	-- 燃烧平原: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "黑石山",
			short = "黑石山并非诞生于寻常的火焰。",
			full = "黑石山并非诞生于寻常的火焰。三锤之战期间，当铜须和蛮锤两大氏族的军队进军去清除黑铁氏族时，巫师领主索瑞森将手伸进了世界熔融的核心，将它的力量拖上来作为武器。回应他的是拉格纳罗斯。炎魔之王的重生撕裂了群山，让周围的土地淹没在火海之中，两位国王都宁可调转他们的军队撤退，也不愿与他正面交锋。在黑铁王国曾经屹立的地方，如今一座火山正在闷燃，南面是燃烧平原，北面是灼热峡谷。拉格纳罗斯退入了山体的核心，奴役了幸存的黑铁矮人，让他们在自己残破的家园下方开凿出暗影熔炉城。",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "黑石小径",
			short = "黑石小径是两个世界之间的门槛。一边是赤脊山，青翠而宁静。另一边则是燃烧平原，焦灼扭曲得面目全非。",
			full = "黑石小径是两个世界之间的门槛。一边是赤脊山，青翠而宁静。另一边则是燃烧平原，焦灼扭曲得面目全非。边界上矗立着一道大门，清清楚楚地标明了这条界线。\n\n穿过这道门，就意味着一步之间将安全抛在身后。那些毫无准备就闯进去的人会发现这种变化十分残酷：门那边的生物，远比身后山中出没的任何东西都要凶残得多。",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "黑石要塞",
			short = "这座要塞耸立在燃烧平原的边缘，紧贴着黑石塔的阴影，是一座由黑石氏族把守的黑石堡垒。",
			full = "这座要塞耸立在燃烧平原的边缘，紧贴着黑石塔的阴影，是一座由黑石氏族把守的黑石堡垒。在它的城墙外，在荣耀之地上，氏族的战士和他们的盟友集结操练，被黑石中士的鞭子和吼声管束着。\n\n要塞的指挥权落在索尔吉佐格将军手中，他管教着聚集在荣耀之地上的部队，确保他的命令被不折不扣地执行。",
