		["ruins of thaurissan"] = {
			name = "索瑞森废墟",
			short = "燃烧平原上这片灰烬覆盖的平地曾经一片青翠，这里的城市以它的建立者命名：索瑞森城，那是黑铁氏族的都城，三锤之战期间，这个氏族被逐出铁炉堡，由巫师领主索瑞森带领着南下来到这里。",
			full = "燃烧平原上这片灰烬覆盖的平地曾经一片青翠，这里的城市以它的建立者命名：索瑞森城，那是黑铁氏族的都城，三锤之战期间，这个氏族被逐出铁炉堡，由巫师领主索瑞森带领着南下来到这里。\n\n黑铁矮人正在输掉那场战争。他们的军队刚刚在另外两个氏族的要塞前被击溃，索瑞森为了扭转战局而不顾一切，召集了七名他最信任的矮人，向沉睡在地下的力量发出召唤，想要得到一个能帮他们赢回这场战争的仆从。回应他们的并不是仆从，而是火焰元素领主拉格纳罗斯，他的降临以一座火山劈开了群山，将整个山谷烧成了灰烬。这座城市被彻底毁灭，幸存的黑铁矮人沦为了炎魔之王的奴隶。他们放弃了这片废墟，在黑石山下建起了新的家园，而从索瑞森的灰烬中，崛起了黑石塔和一个新的黑铁国度。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
