	-- 艾尔文森林: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "布莱克威尔南瓜田",
			short = "在艾尔文森林的东南部坐落着一座农庄，曾经属于布莱克威尔一家。他们后来怎么样了，没有人说得清。",
			full = "在艾尔文森林的东南部坐落着一座农庄，曾经属于布莱克威尔一家。他们后来怎么样了，没有人说得清。迪菲亚兄弟会将这里据为己有，而布莱克威尔一家就这样从田地和篱笆间消失了。\n\n关于他们，只有一段记忆留存了下来：一头名叫公主的获奖母猪，在强盗到来之前很久，它夜复一夜地溜到邻近的斯通菲尔德农场偷吃蔬菜，把自己吃得硕大无比。",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "水晶湖",
			short = "水晶湖位于闪金镇以东，湖中挤满了鱼人，让湖岸成了粗心大意之人的险地。一座人类的农舍在南岸守望着这片湖水。",
			full = "水晶湖位于闪金镇以东，湖中挤满了鱼人，让湖岸成了粗心大意之人的险地。一座人类的农舍在南岸守望着这片湖水。",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "东谷伐木场",
			short = "东谷的伐木营地散布在艾尔文森林东部，生活区夹在锯木坑之间，这里的工作从来不曾真正停歇。",
			full = "东谷的伐木营地散布在艾尔文森林东部，生活区夹在锯木坑之间，这里的工作从来不曾真正停歇。木材的订单来得比期限允许的还要快，伐木工们在等待暴风城木材的买家们不断的催促下辛苦劳作。\n\n曾经统领暴风城卫兵的治安官哈迦德几年前卸下了指挥之职，选择在营地里的一座宅邸中度过余生，而不是住在他曾经保卫过的那座城市里。塞娅·诺斯布鲁克也是在这里长大的。\n\n森林从四面八方紧紧逼近，它的野性可不容小觑。狼和熊不断侵扰伐木工，冲散工作队伍，眼看就要让营地的工期彻底泡汤。麻烦变得如此严重，以至于暴风城卫兵不得不寻求外界的帮助来清剿这些野兽。",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "回音山矿洞",
			short = "回音山矿洞的坑道位于北郡山谷的西北部。",
			full = "回音山矿洞的坑道位于北郡山谷的西北部。狗头人蜂拥而入，将矿井据为己有，这让住在附近的人类大为恼火，而治安官玛克布莱德能做的，也只是一次又一次地派人去削减它们的数量。",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "法戈第矿洞",
			short = "法戈第矿洞曾为暴风城开采黄金，矿井深深地扎入艾尔文森林的土地之中。如今它已被废弃，坑道被一个狗头人部族所占据。",
			full = "法戈第矿洞曾为暴风城开采黄金，矿井深深地扎入艾尔文森林的土地之中。如今它已被废弃，坑道被一个狗头人部族所占据。下层矿井位于主矿区下方更深处，向黑暗中延伸得更远。\n\n负责艾尔文森林安全的治安官杜汉在确认矿洞中有狗头人出没之后，便下令加强了周边的巡逻。在狗头人之中潜伏着金牙，他手里有一条从伯尼斯·斯通菲尔德婶婶那里偷来的项链，那是她的一件纪念品，她至今仍未放弃找回它的希望。",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "林边空地",
			short = "林边空地位于暴风城的西南方，是一片夹在明镜湖果园、纳菲瑞提河和一条流向西部荒野的小溪之间的狭长林地。",
			full = "林边空地位于暴风城的西南方，是一片夹在明镜湖果园、纳菲瑞提河和一条流向西部荒野的小溪之间的狭长林地。野猪在灌木丛中拱食，河岸边分布着铜矿脉。这片森林属于一群豺狼人，而在它们之中，有一个绝非普通的野兽。霍格与那些低等的豺狼人一起在林中游荡，他可不是它们之中寻常的野狗。",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "闪金镇",
			short = "闪金镇坐落在艾尔文森林的中心，它的田地与北郡遥遥相望，道路通往暴风城、西部荒野和赤脊山。",
			full = "闪金镇坐落在艾尔文森林的中心，它的田地与北郡遥遥相望，道路通往暴风城、西部荒野和赤脊山。它是在暴风城建立之后的那些年里发展起来的，当时王国的人民从都城向周围的乡野扩散开来。\n\n这座城镇最黑暗的时刻发生在第一次战争期间，当时酋长黑手率领部落攻击连接暴风要塞与它的人民之间的生命线。闪金镇和月溪镇是兽人与都城之间最后的两座城镇，它们陷落之后，通往要塞的道路便门户大开。直到第二次战争之后，闪金镇才得以重建，当时洛丹伦联盟重建了它，最高指挥官图拉扬亲自监督四散的暴风城市民返回家园。\n\n如今留下来的一切要安宁得多：狮王之傲旅店矗立在城镇的中心，它的炉火与麦酒吸引着从每一条在此交汇的道路上走来的旅人。暴风城卫兵的治安官杜汉依然守望着这座城镇，他牢记着失去它曾经付出过怎样的代价。",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "英雄哨岗",
			short = "一圈立石环绕着石碑湖中的小岛，中央是阵亡英雄的纪念碑。",
			full = "一圈立石环绕着石碑湖中的小岛，中央是阵亡英雄的纪念碑。它纪念的是第一次战争中的死者，当时兽人洗劫了闪金镇和周围的土地，并将它们付之一炬。\n\n如今，流浪巫师占据着这座小岛。在石头之间躺着亨兹·法奥克的尸体，他倒在哪里，就被留在了哪里。",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "玉石矿洞",
			short = "玉石矿洞曾经为暴风城的锻炉提供原料，是艾尔文森林中为这座城市的战争供应所需原矿的地点之一。",
			full = "玉石矿洞曾经为暴风城的锻炉提供原料，是艾尔文森林中为这座城市的战争供应所需原矿的地点之一。那份工作如今已经结束了。狗头人占据了坑道，而暴风城的军队正被更加严重的威胁牵制，兵力捉襟见肘，抽不出人手来清除它们。\n\n地下的危险并不只有狗头人。在矿洞的最深处，一群矿洞蜘蛛已经扎下了根，对它们来说，狗头人不是需要惧怕的入侵者，而是可供猎食的猎物。它们的女王毒牙之母在黑暗中盘踞，绝不容许任何东西闯入她的巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
