		["maclure vineyards"] = {
			name = "马科伦农场",
			short = "马科伦农场位于艾尔文森林南部，马科伦一家在一排排葡萄藤和土地间辛勤耕作。",
			full = "马科伦农场位于艾尔文森林南部，马科伦一家在一排排葡萄藤和土地间辛勤耕作。马科伦一家与邻近的斯通菲尔德一家之间有着积怨很深的竞争，他们互相交换的，除了厌恶之外别无他物。然而，马科伦家的一个孩子和斯通菲尔德家的一个孩子却彼此相爱了，这违背了他们两家所坚持的一切，有人希望，这样的爱情或许能弥合世世代代的积怨都无法弥合的裂痕。",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
