		["mirror lake"] = {
			name = "明镜湖",
			short = "明镜湖小巧而宁静地坐落在艾尔文森林西部，它的瀑布在附近一座果园旁明亮地倾泻而下，看上去就像是一个专为游泳或钓鱼而生的地方。",
			full = "明镜湖小巧而宁静地坐落在艾尔文森林西部，它的瀑布在附近一座果园旁明亮地倾泻而下，看上去就像是一个专为游泳或钓鱼而生的地方。然而如今已不再那么简单了。迪菲亚强盗已经盘踞在周围的树林中，本该是一处休憩之地的地方，如今却成了需要小心穿过的地方。",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
