		["mirror lake orchard"] = {
			name = "明镜湖果园",
			short = "明镜湖果园位于明镜湖的南岸，一排排果树和一座孤零零的小屋矗立在艾尔文森林西部的田野之间。",
			full = "明镜湖果园位于明镜湖的南岸，一排排果树和一座孤零零的小屋矗立在艾尔文森林西部的田野之间。迪菲亚强盗曾经占据了这座果园和旁边的小屋，把这个地方当作自己的地盘，至于果园真正的主人是否是被他们赶走的，没有人能说得准。",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "北郡修道院",
			short = "北郡修道院坐落在以它命名的山谷之中，位于艾尔文森林的山麓，它的主厅、兵器大厅和图书馆侧翼所在之处，正是圣光教会的牧师们从洛丹伦南下之后最早定居的地方。",
			full = "北郡修道院坐落在以它命名的山谷之中，位于艾尔文森林的山麓，它的主厅、兵器大厅和图书馆侧翼所在之处，正是圣光教会的牧师们从洛丹伦南下之后最早定居的地方。北郡牧师圣教团从这里为暴风城带来慰藉与智慧，而提瑞斯法守护者麦迪文在他漫长的昏迷岁月里，也正是在这些墙壁之内接受照料的。\n\n修道院并没有在第一次战争中安然无恙。它的院长将北郡的牧师们借给暴风城参与防御，而在半兽人迦罗娜作为俘虏被带到这里之后不久，兽人便攻占了北郡，将它焚毁成一片废墟。难民们向洛丹伦逃去，但在逃离之前，他们从废墟中抢救出了一些神圣的典籍，这些典籍后来教会了达拉然的法师们隐形之术。\n\n这片废墟并没有一直空着。第二次战争期间，古加尔的暮光之锤氏族将这里作为他们的总部，直到联盟收复了艾尔文森林，大主教阿隆索斯·法奥一砖一石地重建了修道院，并在它的厅堂中创立了北郡兄弟会。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "北郡山谷",
			short = "北郡山谷除了一面之外四面封闭，群山无法穿越，唯一通往南方的山口被厚厚的石墙和一道有人把守的大门所封锁。",
			full = "北郡山谷除了一面之外四面封闭，群山无法穿越，唯一通往南方的山口被厚厚的石墙和一道有人把守的大门所封锁。一条河流穿过这片宁静，蜿蜒流向水晶湖，途经修道院和一排排葡萄园，正是它们赋予了这个地方一派祥和的气息。\n\n那份祥和并非一直如此确定。第二次战争期间，北郡修道院曾是效忠于古尔丹的古加尔的暮光之锤氏族的总部，它的墙壁之内庇护的是兽人的战争会议，而不是见习牧师和农夫。\n\n如今，治安官玛克布莱德指挥着修道院的守军，负责整个北郡的安全，但即使在他的守望之下，山谷也并非完全太平。狼群从暮色森林不断涌入，数量多得无人能解释，而狗头人则在回音山矿洞中挖洞钻营。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "北郡农场",
			short = "这片葡萄园在修道院的东面铺展开来，在迪菲亚兄弟会占领这片土地之前，人们曾在这里照料葡萄、收获果实。",
			full = "这片葡萄园在修道院的东面铺展开来，在迪菲亚兄弟会占领这片土地之前，人们曾在这里照料葡萄、收获果实。加瑞克·帕德弗特率领着占据这里的特工，把这一排排葡萄藤当作兄弟会爪牙的立足点，他们还带走了米莉·奥斯沃斯被偷的财物。",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "山巅之塔",
			short = "山巅之塔守望着艾尔文森林的边界，是暴风城卫兵的侦察塔之一。",
			full = "山巅之塔守望着艾尔文森林的边界，是暴风城卫兵的侦察塔之一。塔上的哨兵们把目光投向赤脊山，那里聚集着豺狼人和兽人；投向暮色森林，那里的死者不会安息于地下；也投向附近的迪菲亚营地。守军防守严密，足以抵御这三方的威胁。",
