		["stone cairn lake"] = {
			name = "石碑湖",
			short = "石碑湖得名于英雄哨岗，那是湖心岛上竖立的石冢，用来纪念与兽人之间的第一次战争中的死者，那时倒下的人太多，没有哪一座坟墓能够容纳对他们的追忆。",
			full = "石碑湖得名于英雄哨岗，那是湖心岛上竖立的石冢，用来纪念与兽人之间的第一次战争中的死者，那时倒下的人太多，没有哪一座坟墓能够容纳对他们的追忆。这里曾是人们静静朝拜的地方。\n\n那份安宁已经不复存在。流浪巫师占据了这座小岛，那座本为哀悼而立的石冢如今就立在他们身后。在南岸，一个鱼人部族建起了他们自己简陋的住所，对湖对岸的纪念碑毫不在意。",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
