		["stonefield farm"] = {
			name = "斯通菲尔德农场",
			short = "斯通菲尔德农场位于艾尔文森林南部，由斯通菲尔德一家耕种，他们与附近的马科伦一家之间有着积怨很深的竞争。",
			full = "斯通菲尔德农场位于艾尔文森林南部，由斯通菲尔德一家耕种，他们与附近的马科伦一家之间有着积怨很深的竞争。然而两家各有一个孩子坠入了爱河，无视他们家族之间的宿怨。有人希望，这段恋情或许能在多年的争吵从未成功的地方取得成功，弥合这场世仇所撕裂的一切。",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
