		["thunder falls"] = {
			name = "雷霆瀑布",
			short = "从明镜湖的瀑布向上的小路陡峭而狭窄地攀入群山，然后豁然开朗，通向雷霆瀑布，这道峡谷与艾尔文森林中的其他峡谷不同，它的两端都有瀑布倾泻而下。",
			full = "从明镜湖的瀑布向上的小路陡峭而狭窄地攀入群山，然后豁然开朗，通向雷霆瀑布，这道峡谷与艾尔文森林中的其他峡谷不同，它的两端都有瀑布倾泻而下。第三道瀑布从北面的悬崖上奔腾而下，从上方为峡谷注水。在高地下方矗立着一座小小的乡间小屋，屋里的铁砧和炉火一直燃着，房子旁边的河面上还有一座小码头和一条小船。强盗们在小屋附近徘徊。河水继续向前，在西部荒野边缘附近经过第二道瀑布倾泻而下。据说，在这片水域中游弋的紫色鲈鱼，在其他任何地方都不如在这里容易找到。",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "阿祖拉之塔",
			short = "阿祖拉之塔耸立在艾尔文森林中部的田野之间，里面住着一群侏儒仆从，他们听命于大法师塞欧克瑞图斯。",
			full = "阿祖拉之塔耸立在艾尔文森林中部的田野之间，里面住着一群侏儒仆从，他们听命于大法师塞欧克瑞图斯。\n\n在遥远的赤脊山矗立着它的对手，伊尔加拉之塔，由术士莫甘斯统治。这两座塔从未公开交战，但它们一直通过魔法手段互相监视，都在等待着抓住对方的某个失误。\n\n高塔自身的魔法不断外溢到周围的田野中，任何在附近逗留太久的东西都可能被它触及，变成比原来更加古怪的东西。仆从们一边照料着他们的高塔，应付这种细小而持续不断的麻烦，一边始终留着一只眼睛注视着赤脊山。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "西泉要塞",
			short = "西泉要塞矗立在艾尔文森林的西部边缘，在那里，树林让位于西部荒野那片更加贫瘠的乡野，对于暴风城卫兵来说，这里一直是一个孤寂的岗位。",
			full = "西泉要塞矗立在艾尔文森林的西部边缘，在那里，树林让位于西部荒野那片更加贫瘠的乡野，对于暴风城卫兵来说，这里一直是一个孤寂的岗位。\n\n它最艰难的岁月，是在女伯爵卡特拉娜·普瑞斯托的腐化沉重地笼罩着王国、暴风城军队的主力被调往他处的时候。由于抽不出足够的士兵，来自西部荒野的豺狼人和盗贼一季比一季更猛烈地进逼森林，要塞几乎无法保障道路的安全。\n\n在豺狼人之中，河爪豺狼人的首领霍格成了一个令人闻风丧胆的名字。每一次试图抓捕他的行动都被他挫败了，悬赏通缉他的告示至今仍挂在要塞的大门上，却始终无人领赏。",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- 逆风小径: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "埃瑞丁营地",
			short = "这座营地被遗弃在穿越逆风小径的道路以北，在终年幽暗的树林下，只剩下一些冰冷的火坑和空荡荡的铺盖。",
			full = "这座营地被遗弃在穿越逆风小径的道路以北，在终年幽暗的树林下，只剩下一些冰冷的火坑和空荡荡的铺盖。埃瑞丁曾在这片土地上率领黑暗骑士，在他遭受诅咒之前，他就在这里扎营，并试图从这里兜售一些他声称曾属于麦迪文的伪造文物。如今这里除了营地本身之外，什么也没有留下。",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
