			name = "主宰的庇护所",
			short = "在卡拉赞南面那座残破的村庄下方，那里曾是高塔仆人们的居所，大地向下敞开，通往一些已不再属于生者的地窖。",
			full = "在卡拉赞南面那座残破的村庄下方，那里曾是高塔仆人们的居所，大地向下敞开，通往一些已不再属于生者的地窖。有两个入口通往下面。一个通向一座巨大的酒窖，它的酒架和酒桶早已被遗弃给了死者。另一个则通向第二座地窖，那里的地面已经完全塌陷，陷入一个深入地下的洞穴系统。\n\n两处都挤满了不得安宁的亡魂：那些不死的看守者似乎仍在照料着一座没有主人的宅邸，还有被诅咒的灵魂、不肯平息的阴影，以及哀嚎声穿过破碎岩石传上来的幽灵。无论生前是什么样的侍奉将他们与卡拉赞捆绑在一起，如今都已凝结成某种在他们死后也不肯放他们离去的东西。\n\n只有那座酒窖里有一些在死者之中格外引人注目的东西。下方的洞穴系统寂静无声，淹没在黑暗之中，除了更多同样不得安宁的死者之外，一无所有，没有任何有名有姓的东西，也没有任何人认为值得记住的东西。",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "摩根墓场",
			short = "一座破旧的小教堂矗立在卡拉赞的后面，它的墓地和地穴深陷在逆风小径的阴霾之中。",
			full = "一座破旧的小教堂矗立在卡拉赞的后面，它的墓地和地穴深陷在逆风小径的阴霾之中。这座礼拜堂长久以来一直栖息着一些无法安息的东西，而在它下方的山坡上，至今仍有别的东西在巡逻。\n\n一个本该安置死者的地方，却常常留不住他们，这足以说明它背后所隐藏的是什么。",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "沉睡峡谷",
			short = "沉睡峡谷横穿逆风小径的东部，是一道小小的裂谷，从南面前往卡拉赞的旅人在小路转向东方、进入罪恶谷之前，必须先穿过这里。",
			full = "沉睡峡谷横穿逆风小径的东部，是一道小小的裂谷，从南面前往卡拉赞的旅人在小路转向东方、进入罪恶谷之前，必须先穿过这里。",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "罪恶谷",
			short = "罪恶谷位于通往卡拉赞的道路的南段，逆风食人魔在那里的峭壁间建起了他们的土丘和营地。",
			full = "罪恶谷位于通往卡拉赞的道路的南段，逆风食人魔在那里的峭壁间建起了他们的土丘和营地。这是一片荒凉的土地，除了不得安宁的亡魂和在它们上空盘旋的秃鹫之外，几乎别无他物。至于食人魔为什么选择在这样一个空旷而不祥的地方扎根，任何见过这里的人都不得而知。",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- 暮色森林: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "腐草农场",
			short = "腐草农场被遗弃在暮色森林西南部的田野之间，是黑暗笼罩这片土地时被弃之腐烂的众多农庄之一。",
			full = "腐草农场被遗弃在暮色森林西南部的田野之间，是黑暗笼罩这片土地时被弃之腐烂的众多农庄之一。谷仓空空荡荡，农舍寂静无声，如今只有凄凉的灵魂在这里徘徊，据说它们是曾经占据这里的迪菲亚兄弟会死者的亡魂。\n\n迪菲亚兄弟会将腐草农场完全据为己有，他们在杂草丛生的田地里潜行，躲在谷仓中，在农舍的房间里出没。",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "乞丐鬼屋",
			short = "被称为乞丐鬼屋的这座塔楼被遗弃在通往逆风小径的道路上方，位于密斯特曼托庄园的东北方。",
			full = "被称为乞丐鬼屋的这座塔楼被遗弃在通往逆风小径的道路上方，位于密斯特曼托庄园的东北方。它原本是作为暴风城卫兵的侦察哨所而建的，如今却为被遗忘者所用，亡灵哨兵莱度斯和药剂师法奥斯丁在塔中进行着实验。\n\n一条小路蜿蜒而下，通往一汪由瀑布注入的小池，池边有一座没有标记的坟墓，坟墓上方矗立着两尊巨大的雕像，其雕刻风格与黑暗之门的雕像如出一辙。塔楼附近还有另一座小墓地，其中有一座无名战士之墓。",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "阳光树林",
			short = "阳光树林就在夜色镇以西，那里仅有的几座建筑早已沦为废墟。",
			full = "阳光树林就在夜色镇以西，那里仅有的几座建筑早已沦为废墟。如今这个地方残存的一切都属于夜灭狼人，它们成群结队地在黑暗的田野中游荡，在废墟之间搭起简陋的营地，扑向任何过于靠近的人。",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "暗色河滩",
			short = "暗色河滩沿着暮色森林的北岸延伸，从这片土地的西部边缘一直向东延伸到将它与赤脊山相连的桥梁。",
			full = "暗色河滩沿着暮色森林的北岸延伸，从这片土地的西部边缘一直向东延伸到将它与赤脊山相连的桥梁。在它的西端有一座小营地，难民斯温·约根和拉尔斯在那里栖身，不管是什么东西让暮色森林的其他地方变得太过危险而无法立足，他们都被它逼到了水边。",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "夜色镇",
			short = "夜色镇并非从来就叫这个名字。很久以前，它作为格兰德村而兴起，是暴风城的人民向附近土地扩散时建立起来的一座林间小镇。",
			full = "夜色镇并非从来就叫这个名字。很久以前，它作为格兰德村而兴起，是暴风城的人民向附近土地扩散时建立起来的一座林间小镇。然而这片土地本身再也没能从卡拉赞发生的事情中恢复过来。当守护者麦迪文在那座高塔中被杀死时，他的死所释放出的邪能渗入了周围的森林，将它扭曲成了至今依然荆棘丛生、不见天日的地方。阳光森林变成了暮色森林，而格兰德村也有了一个更加名副其实的名字：夜色镇。\n\n这座城镇的民兵组织守夜人之所以存在，是因为暴风城抛弃了它。当女伯爵卡特拉娜·普瑞斯托在暴风城的阴谋使王国的驻军撤离森林时，镇民们宁可自己武装起来，也不愿去等待那些永远不会到来的士兵。他们完全由森林里的人们组建和训练，从那以后，他们一直守卫着道路，抵御狼群、行尸走肉以及更加可怕的东西，除了他们自己之外，已经没有任何军队可以求助了。",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "黎明墓穴",
			short = "在乌鸦岭墓地的下方，大地敞开，通往黎明墓穴，这是一片曲折深邃的隧道迷宫，很少有人独自进去之后还能出来。",
			full = "在乌鸦岭墓地的下方，大地敞开，通往黎明墓穴，这是一片曲折深邃的隧道迷宫，很少有人独自进去之后还能出来。有两条路通往下面。东边的通道通向一个食尸鬼的巢穴，它们身染疫病，凶猛无比。西边的通道则通向一座骷髅的大厅，它们站岗守卫着那些曾经就是它们自己的死者的坟墓。",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "荒弃鬼屋",
			short = "荒弃鬼屋是乌鸦岭墓地北缘的一座山丘，笼罩在一片比周围树林的阴影更加浓重的黑暗之中。",
			full = "荒弃鬼屋是乌鸦岭墓地北缘的一座山丘，笼罩在一片比周围树林的阴影更加浓重的黑暗之中。这里矗立着死灵法师摩本特·费尔的家，他用邪恶的奥术魔法让森林中的亡灵屈从于他的意志。只有一件拥有强大力量的武器才有希望让他平息。",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "寂静河岸",
			short = "寂静河岸沿着暮色森林西部的河流延伸，从西部荒野、艾尔文森林和暮色森林的交汇处一直向南通往荆棘谷。",
			full = "寂静河岸沿着暮色森林西部的河流延伸，从西部荒野、艾尔文森林和暮色森林的交汇处一直向南通往荆棘谷。一座有顶棚的桥在这里横跨河流，将暮色森林与西部荒野连接起来。\n\n在河岸的北角，拉尔斯和斯温·约根兄弟俩守着一座营地。\n\n狼和蜘蛛在河岸边的树林间游荡。",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "密斯特曼托庄园",
			short = "密斯特曼托庄园矗立在暮色森林的东北部，庭院腐朽，花园荒芜。",
			full = "密斯特曼托庄园矗立在暮色森林的东北部，庭院腐朽，花园荒芜。这里曾是斯塔文·密斯特曼托的家，他是一名教师和家庭教师，后来成了亡灵的爪牙，只留下食尸鬼代替他在宅邸中蹒跚游荡。在这片腐化之中，仍有一样东西在生长：一朵名叫提洛亚之泪的花，它是这座几乎完全被腐朽吞噬的花园中仅存的生命迹象。",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "乌鸦岭",
			short = "乌鸦岭的房屋空荡荡地矗立在暮色森林的西部，被弃置给了腐朽与黑暗。尽管如此，仍有几个人坚守在这里：基特斯，还有布里兹提克，一个躲在楼上不露面的地精。",
			full = "乌鸦岭的房屋空荡荡地矗立在暮色森林的西部，被弃置给了腐朽与黑暗。尽管如此，仍有几个人坚守在这里：基特斯，还有布里兹提克，一个躲在楼上不露面的地精。\n\n这座城镇被隐形者所困扰，它们不仅名字叫隐形者，而且确实无影无形，在空荡荡的房间中穿行。",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "乌鸦岭墓地",
			short = "乌鸦岭墓地在以它命名的城镇北面蔓延开来，自从暮色森林被腐化以来，它已经远远超出了原来的边界。",
			full = "乌鸦岭墓地在以它命名的城镇北面蔓延开来，自从暮色森林被腐化以来，它已经远远超出了原来的边界。如今亡灵在墓碑之间行走，巨大的蜘蛛和成群的盗墓贼在坟墓间肆意作业，赶走任何误打误撞闯入他们勾当的人。\n\n在墓地的西北角矗立着荒弃鬼屋，那是死灵法师摩本特·费尔的家，他的黑暗行径惊扰着墓地中的死者。\n\n拉迪莫尔这个名字，标志着这座墓地最古老的悲伤。摩根·拉迪莫尔从第三次战争中归来，却发现他的妻子和孩子已经被埋葬在这里。悲痛击垮了他；他在他们的坟前杀死了墓地的三名看守人。如今，亡灵摩拉迪姆在墓地中巡逻，任何在墓碑间被他发现的粗心之人，都会在不知不觉中迅速死去。",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "罗兰之墓",
			short = "罗兰之墓是暮色森林东南部的一座矿洞，位于烂果园以东。",
			full = "罗兰之墓是暮色森林东南部的一座矿洞，位于烂果园以东。暗夜精灵女祭司维琳德·星歌在失踪之前曾将艾露恩之镰带进了这片山丘，这件圣物就此遗失在了矿洞之中。一个叫基特斯的人在那里找到了它，而它的发现却引来了更多的狼人涌向暮色森林和夜色镇。\n\n如今，这座矿洞属于夜灭狼人群中的流肠和奈法鲁，它们的狼人一直游荡到烂果园。",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "烂果园",
			short = "这座果园位于暮色森林的南部，果树已经腐烂发黑，建筑在约根农场和静谧花园墓场之间沦为了废墟。",
			full = "这座果园位于暮色森林的南部，果树已经腐烂发黑，建筑在约根农场和静谧花园墓场之间沦为了废墟。\n\n夜灭狼人群将这里据为己有。暗影编织者在残破的建筑间施展魔法，而潜伏者则隐身在树木之间的黑暗中等待。\n\n如今站在这里，就是站在一个已经不再是农场、而变成了猎场的地方。",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "静谧花园墓场",
			short = "静谧花园墓场位于夜色镇的东南方，如今它的名字成了一个苦涩的笑话。",
			full = "静谧花园墓场位于夜色镇的东南方，如今它的名字成了一个苦涩的笑话。这里的死者并不安宁，尽管它们比暮色森林其他地方的亡灵要弱一些，在墓碑和墓地中心那座残破的教堂之间游荡。疯狂的食尸鬼在这片土地上出没，有时在破败的教堂里，有时在坟墓之间。在它的正北方矗立着盲眼玛丽的房子。",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "黎明森林",
			short = "在暮色森林深处的黎明森林中心，矗立着一棵无名的巨树，旁边是一座月亮井和一座古老的暗夜精灵凉亭。",
			full = "在暮色森林深处的黎明森林中心，矗立着一棵无名的巨树，旁边是一座月亮井和一座古老的暗夜精灵凉亭。在它的枝干下方，是通往翡翠梦境的仅有的四座传送门之一，与隐藏在菲拉斯、辛特兰和灰谷的那几座传送门互为姊妹。\n\n林中的传送门并非无人守护。四条巨龙曾是梦境守护巨龙伊瑟拉引以为傲的副官，她选中它们作为梦境的守护者，在这里守望。然而翡翠梦魇又腐化了它们，将守护者扭曲成了只渴望死亡的毁灭者，于是联盟和部落都不得不拿起武器，对抗这些曾经在这里守望的巨龙。",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "沃古尔食人魔山",
			short = "暮色森林南部陷下去一片小小的盆地，道路在这里分岔通往荆棘谷，在食人魔到来之前，这里曾矗立着一些农舍。",
			full = "暮色森林南部陷下去一片小小的盆地，道路在这里分岔通往荆棘谷，在食人魔到来之前，这里曾矗立着一些农舍。如今碎拳食人魔占据着这里，这个地方便以他们的首领扎尔克·沃尔命名，他在土丘里统治着这里。\n\n那些残破的农舍是这里在食人魔占据盆地之前曾有人居住的唯一迹象。无论那些家庭后来遭遇了什么，食人魔都只留下了残垣断壁。\n\n守夜人不会为这个地方抽调人手，他们认为这里的威胁不如其他压在暮色森林身上的威胁那样紧迫，因此在需要的时候，削减食人魔数量的任务便落到了外人的头上。在食人魔的战利品中，有一箱从死灵法师亚伯克隆比那里偷来的工具和草药，他们打垮他之后便把它们搬进了土丘。而扎尔克·沃尔本人还戴着一枚单片眼镜，一位研究者曾经为了自己的研究对它垂涎不已，这是一个野蛮的生物身上的小小虚荣。",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "约根农场",
			short = "约根农场被遗弃在暮色森林南部，田地已经腐烂。斯温·约根曾经在这片土地上耕作，如今却栖身在暗色河滩上的一座小营地里。",
			full = "约根农场被遗弃在暮色森林南部，田地已经腐烂。斯温·约根曾经在这片土地上耕作，如今却栖身在暗色河滩上的一座小营地里。此后，这座农庄落入了迪菲亚兄弟会之手，他们的刺客在田野中无影无踪地穿行，只在为时已晚之时才出手。",
