		["stonewatch"] = {
			name = "石堡",
			short = "石堡曾经属于湖畔镇的人类，是一座背靠悬崖的要塞，瀑布在城堡下方倾泻而下，它守望着赤脊山，抵御来自燃烧平原的兽人威胁。",
			full = "石堡曾经属于湖畔镇的人类，是一座背靠悬崖的要塞，瀑布在城堡下方倾泻而下，它守望着赤脊山，抵御来自燃烧平原的兽人威胁。\n\n那份守望被背叛所打破。术士莫甘斯与加塞尔佐格和他的黑石兽人结成同盟，他们的联军以一种击垮守军的凶残扑向了石堡要塞。兽人夺取了城堡，但他们的胜利在信任上却是短暂的，因为莫甘斯转而背叛了为他赢得胜利的盟友。他为自己建起了伊尔加拉之塔，并让范高雷中尉麾下的一支暗皮豺狼人战团为他自己的目的效力。自那次反目以来，无论是兽人还是人类，凡是挡住这些豺狼人去路的人都付出了代价。\n\n黑石兽人被利用他们的术士抛弃之后，便独自占据着这座城堡，由加塞尔佐格和他的副官萨瑞尔祖恩统治。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
