		["stonewatch keep"] = {
			name = "石堡要塞",
			short = "石堡要塞曾经属于湖畔镇的人类，负责守望赤脊山。",
			full = "石堡要塞曾经属于湖畔镇的人类，负责守望赤脊山。当术士莫甘斯与黑石兽人督军加塞尔佐格结成同盟时，它陷落了，他们的联军在莫甘斯黑暗魔法的助长下，以凶残的攻势扑向城堡。守军溃败，城堡被攻陷。\n\n这个同盟并没有持续多久。石堡刚一陷落，莫甘斯就背叛了曾在他身边为之流血的兽人。他在附近建起了伊尔加拉之塔，并在塔中安置了范高雷中尉麾下的暗皮豺狼人，这些生物只服从他一个人的意志。从那以后，兽人和人类都倒在了他所放出的这些野兽手下。\n\n黑石兽人被他们的术士盟友抛弃之后，便独自占据着这座城堡，由加塞尔佐格和他的副官萨瑞尔祖恩统治着残存的一切。在那场战斗中，他们俘虏了暴风城军队的基沙恩下士，并把他拖到了北方的营地。所罗门镇长为此悬赏加塞尔佐格的首级，而湖畔镇的治安官玛里斯也发誓要让萨瑞尔祖恩为他的罪行付出代价。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "石堡高塔",
			short = "石堡高塔曾经矗立在石堡要塞旁边，二者都由湖畔镇的人类把守，直到黑石氏族夺取了这座要塞。",
			full = "石堡高塔曾经矗立在石堡要塞旁边，二者都由湖畔镇的人类把守，直到黑石氏族夺取了这座要塞。这座塔如今是加塞尔佐格手下的一个侦察哨所，黑石氏族的兽人在这里守望着他们的同族从湖畔镇的人手中夺来的要塞。",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
