		["misty valley"] = {
			name = "迷雾谷",
			short = "雾气低低地笼罩着悲伤沼泽的这个角落，浓得足以吞没声音。在山谷后部的一个洞穴深处，曾经住着泥沼之王，那是一股元素之力。",
			full = "雾气低低地笼罩着悲伤沼泽的这个角落，浓得足以吞没声音。在山谷后部的一个洞穴深处，曾经住着泥沼之王，那是一股元素之力。",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
