		["pool of tears"] = {
			name = "泪水之池",
			short = "泪水之池宽阔而平静地卧在悲伤沼泽的东缘。在它平静的水面下，沉睡着阿塔哈卡神庙，巨魔建起它之后，伊瑟拉将它沉入了这里，使它从世人的眼中消失。",
			full = "泪水之池宽阔而平静地卧在悲伤沼泽的东缘。在它平静的水面下，沉睡着阿塔哈卡神庙，巨魔建起它之后，伊瑟拉将它沉入了这里，使它从世人的眼中消失。绿龙军团长久以来一直守望着这个被淹没的地方，防范任何可能唤醒沉睡在下方之物的东西。\n\n如今，嗜血的狂鱼在水中游弋，残破的阿塔莱石雕散落在岸边。",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "流沙泥潭",
			short = "流沙泥潭的淤泥从来不会静止。它在地面上聚成细细的一堆堆，在沼泽中缓缓移动，仿佛有什么看不见的东西在拖着它，像活物一样卷曲着、汇聚着。",
			full = "流沙泥潭的淤泥从来不会静止。它在地面上聚成细细的一堆堆，在沼泽中缓缓移动，仿佛有什么看不见的东西在拖着它，像活物一样卷曲着、汇聚着。\n\n有人说，这种移动背后的力量并不邪恶，而是某种积极的能量在搅动着淤泥，毫无伤人的意图。",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "忧伤湿地",
			short = "忧伤湿地位于泪水之池以东，靠近沉没的神庙。",
			full = "忧伤湿地位于泪水之池以东，靠近沉没的神庙。它属于龙类，绿色龙人在一头巨大的绿色幼龙的注视下在泥沼中爬行，除了最鲁莽的旅人之外，所有人都被挡在了外面。",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "断矛路口",
			short = "在进入悲伤沼泽的道路分岔的地方，一座古老的兽人瞭望塔依然矗立，部落的巡逻队监视着这个路口。",
			full = "在进入悲伤沼泽的道路分岔的地方，一座古老的兽人瞭望塔依然矗立，部落的巡逻队监视着这个路口。\n\n这座塔是基洛斯的遗迹，那是第一次战争期间在这里建立的一座兽人前哨。基洛斯比部落在沼泽中的任何其他据点都更靠近人类的格兰德村，暴风城绝不能容忍它的存在。于是派出了一支支战斗部队去摧毁它。\n\n这座塔至今仍守望着道路的岔口。",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "雄鹿沼泽",
			short = "在泪水之池以南，悲伤沼泽逐渐隆起成为群山的地方，沼泽变得越发浓密，形成了雄鹿沼泽。在这片湿漉漉的荒野以西，在山脚下，一个洞穴通向岩石深处。",
			full = "在泪水之池以南，悲伤沼泽逐渐隆起成为群山的地方，沼泽变得越发浓密，形成了雄鹿沼泽。在这片湿漉漉的荒野以西，在山脚下，一个洞穴通向岩石深处。",
