		["stagalbog cave"] = {
			name = "雄鹿沼泽洞穴",
			short = "在悲伤沼泽中雄鹿沼泽的东部，一个洞穴向泥沼敞开。",
			full = "在悲伤沼泽中雄鹿沼泽的东部，一个洞穴向泥沼敞开。",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
