		["stonard"] = {
			name = "斯通纳德",
			short = "斯通纳德从悲伤沼泽的泥沼中崛起，它的大厅依然屹立，而其他许多兽人大厅却早已倒塌。",
			full = "斯通纳德从悲伤沼泽的泥沼中崛起，它的大厅依然屹立，而其他许多兽人大厅却早已倒塌。两座地洞守卫着通往这里的道路，兽人巡逻队出发去守住附近的小营地，每一座营地都是在这片沼泽中宣示的又一处主权。\n\n这座前哨十分古老，比世界这一边几乎任何其他兽人据点都更古老，它与曾经被称为洛卡德的要塞是姊妹据点。它是黑暗之门第一次开启之后的那些日子里，由旧部落在黑色沼泽中建立的。当第二次战争来临、部落崩溃时，斯通纳德陷入了沉寂，很可能与兽人建造的许多其他东西一起被遗弃或摧毁了。\n\n它并没有一直空着。随着新部落的崛起，以及守住这片土地的决心重新燃起，斯通纳德得以重建，它的大厅被修复，它的地洞被重新挖掘。洛卡德就没有这么幸运了：巨槌食人魔将这座古老的要塞据为己有，并将它更名为巨槌要塞，使斯通纳德成了部落在沼泽中唯一的前哨，也是这片低地上仍然亮着灯火的最后一座同类大厅。",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "阿塔哈卡神庙",
			short = "一千多年前，古拉巴什帝国在内战中分崩离析。内战的核心是阿塔莱，这些巨魔祭司企图将血神夺魂者哈卡带回这个世界。",
			full = "一千多年前，古拉巴什帝国在内战中分崩离析。内战的核心是阿塔莱，这些巨魔祭司企图将血神夺魂者哈卡带回这个世界。他们战败被逐，向北逃进了悲伤沼泽，并在那里建起了一座神庙，为他的回归做准备。\n\n守护巨龙伊瑟拉得知了他们的计划，将神庙沉入了沼泽之下，意图将他们的所作所为永远埋葬。事情却并未如她所愿。在被淹没的黑暗中，阿塔莱不受打扰，也没有任何可能阻止他们的目光，他们在平静中继续进行着他们的仪式。伊瑟拉派来守卫这片废墟的绿龙从那以后一直在此守望，守着一扇从未被真正封死的门。\n\n这座神庙至今仍然沉在水下，一半被淹没，供奉哈卡的祭坛完好无损，而那些进入其中的人所冒的风险比死亡更加可怕。鲜血洛阿所要的不仅是血肉，还有灵魂，而献给它的每一个灵魂，都在滋养着它终将得逞的那一天。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- 西部荒野: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "阿历克斯顿农场",
			short = "在迪菲亚兄弟会将这片土地据为己有之前，阿历克斯顿农场的田地曾经养活过许多家庭。",
			full = "在迪菲亚兄弟会将这片土地据为己有之前，阿历克斯顿农场的田地曾经养活过许多家庭。如今，只有机械的麦田傀儡在田垄间走动，它们不知疲倦，无人照管，守护着再也没有人耕种的田垄。\n\n后来成为暴风城建筑师的巴隆斯·阿历克斯顿就出生在这片土地上。在塑造了他的这片土地落入他人之手之前，他小时候曾在这里劳作，就在如今麦田傀儡巡逻的这些田地里。",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
