		["longshore"] = {
			name = "长滩",
			short = "西部荒野的海岸绵长而空旷，是艾泽拉斯最宽阔的海滩之一。",
			full = "西部荒野的海岸绵长而空旷，是艾泽拉斯最宽阔的海滩之一。鱼人沿着海岸成群地移动，数量多得根本无法阻挡，而在它们之中游着老瞎眼，这个生物让海边的渔民学会了畏惧，也给它起了名字。在浪花之外，躺着那些没能驶进来的船只的残骸，其中还有精灵的驱逐舰，任凭潮水摆布。\n\n在海滩的最西南端，坐落着达芙妮·斯迪威尔的农场。迪菲亚兄弟会不止一次来找她，想要把她烧出家门，就像他们在西部荒野烧毁其他许多东西一样。她的困境传到了达索瑞恩·拉尔的耳中，他派出一些有志成为白银之手骑士的人来到海岸，守卫她的土地，他们守住了它。",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "摩尔森农场",
			short = "摩尔森农场是西部荒野众多被迪菲亚兄弟会占据的农庄之一。",
			full = "摩尔森农场是西部荒野众多被迪菲亚兄弟会占据的农庄之一。它的田垄已被铁锈和机器所占据，机械的麦田傀儡在田野里游荡，攻击任何过于靠近的人。",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "月溪镇",
			short = "在月溪镇的田野下方，曾经流淌着暴风城国库的三分之一，那是从后来被称为死亡矿井的坑道中开采出来的黄金。",
			full = "在月溪镇的田野下方，曾经流淌着暴风城国库的三分之一，那是从后来被称为死亡矿井的坑道中开采出来的黄金。这座城镇曾是王国的粮仓，直到石匠工会的解散引发了暴乱，蒂芬·乌瑞恩王后在暴乱中丧生。瓦里安国王为她的死所进行的报复，最沉重地落在了工会的头上，石匠们为了躲避他，逃进了西部荒野的农田。在暗中有人煽风点火之下，他们的愤怒化作了迪菲亚兄弟会。在艾德温·范克里夫的领导下，他们沦为了强盗，把农民赶出了月溪镇，并将镇子下方废弃的矿井坑道作为他们的总部，在那里秘密地建造一件意在从海上摧毁暴风城的武器。\n\n多年来，一直没有军队前来对付他们。兄弟会至今仍占据着月溪镇，只有格里安·斯托曼的西部荒野人民军与他们对抗，在哨兵岭积蓄力量，等待着一场尚未到来的清算。",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "萨丁农场",
			short = "萨丁农场是西部荒野唯一从未被迪菲亚兄弟会攻占的农场。迪菲亚的收割傀儡在它的田地里游荡，但农夫萨丁和他的妻子萨尔玛却拒绝离开。",
			full = "萨丁农场是西部荒野唯一从未被迪菲亚兄弟会攻占的农场。迪菲亚的收割傀儡在它的田地里游荡，但农夫萨丁和他的妻子萨尔玛却拒绝离开。多年来，他们的农舍一直充当着中途歇脚之所，这对夫妇竭尽所能地让他们的客人活下去。",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "哨兵岭",
			short = "哨兵岭矗立在西部荒野农田上方的高地上，它的塔楼守望着建在下方山坡上的小屋、锻炉和磨坊。",
			full = "哨兵岭矗立在西部荒野农田上方的高地上，它的塔楼守望着建在下方山坡上的小屋、锻炉和磨坊。\n\n河爪豺狼人和迪菲亚兄弟会都曾袭击过这座山岭和它所守护的土地。",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "斯特登的池塘",
			short = "哨兵岭的西南方有一个小池塘，池水在一圈豺狼人的包围下静止不动。",
			full = "哨兵岭的西南方有一个小池塘，池水在一圈豺狼人的包围下静止不动。池边有两座坟墓，还散落着一些旧骨头，水中似乎有什么东西不对劲，仿佛它再也不适合饮用了。\n\n在那里碰运气的渔夫们大多只能钓上普通的鼠尾鱼。但据说水面下还游着别的东西，一种名叫斯特登之祸的鱼，很少有人见过，被钓上来的就更少了。",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "西部荒野灯塔",
			short = "灯塔矗立在西部荒野的最南端，夜晚，它的光束仍在海面上旋转，只是如今照看它的手属于一个死人。",
			full = "灯塔矗立在西部荒野的最南端，夜晚，它的光束仍在海面上旋转，只是如今照看它的手属于一个死人。\n\n曾经有一家人照料着这盏灯火，直到鱼人老瞎眼从浪花中冒出来，把他们吓得逃走了。他们回来后重新点亮了灯火，但老瞎眼又回来了，这一次它带着海岸边的鱼人一起袭击了灯塔。这家人没能幸存下来。格雷森眼睁睁地看着他们死在自己面前，却无力阻止，如今照看着这盏灯的正是他的鬼魂，他在塔外站岗，再也没有人来接替他。",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- 湿地: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "怒牙营地",
			short = "怒牙营地横跨湿地中部，是龙喉氏族在这一地区占据的最大营地，也是怒牙兽人的家园。",
			full = "怒牙营地横跨湿地中部，是龙喉氏族在这一地区占据的最大营地，也是怒牙兽人的家园。\n\n在耐克鲁斯·碎颅之子纳克罗什·碎颅的领导下，这座营地已经成了一个集结地，他们在这里集结投石车，准备进攻米奈希尔港。这个威胁千真万确，以至于斯托菲队长已经发誓，要在投石车出动之前让纳克罗什毙命，并扯下这个氏族的战旗。",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "巴拉丁海湾",
			short = "巴拉丁海湾的海水冲刷着卡兹莫丹与洛丹伦交界处的海岸，触及米奈希尔港和激流堡的海岸。",
			full = "巴拉丁海湾的海水冲刷着卡兹莫丹与洛丹伦交界处的海岸，触及米奈希尔港和激流堡的海岸。鱼人和鳄鱼在它的浅滩中漂游，而鲨鱼和螃蟹则占据着更深的水域。\n\n这座海湾真正的历史残破地躺在它的海底。第二次战争期间，库尔提拉斯的舰队在这片水域巡逻，守卫着海岸，抵御蔓延整个东部王国的战火。但库尔提拉斯为这份警惕付出了惨重的代价：这个国家的第三舰队在战斗中全军覆没。它的一些残骸至今仍支离破碎地躺在湿地的海岸边，在它们碎裂的浅滩中清晰可见，而另一些则完全沉没了，沉入下方的黑暗之中，从那以后再也没有人把它们打捞上来。",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "黑水沼泽",
			short = "通往米奈希尔港的道路绕过湿地西南部的黑水沼泽。",
			full = "通往米奈希尔港的道路绕过湿地西南部的黑水沼泽。迅猛龙在整片沼泽中筑巢，其中一些更饥饿的会游荡到路边，所以经过这段路的旅人最好保持警惕。",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "蓝腮沼泽",
			short = "在湿地西部的蓝腮沼泽中，散布着蓝腮鱼人的营地，它们从不单独行动，而是在芦苇丛中两三成群。",
			full = "在湿地西部的蓝腮沼泽中，散布着蓝腮鱼人的营地，它们从不单独行动，而是在芦苇丛中两三成群。它们的首领是狼吞者，一只比其他鱼人更加凶猛的鱼人，有它在，这片沼泽最好还是小心进入。",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "深水旅店",
			short = "深水旅店坐落在米奈希尔港，大堂里满是过往水手的谈笑声。",
			full = "深水旅店坐落在米奈希尔港，大堂里满是过往水手的谈笑声。这是个粗野的地方：椅子被扔出去的次数和麦酒被倒出来的次数一样多，斗殴常常是在“干柴”塔伯克·贾恩的怂恿下开始的。",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "恶铁岭",
			short = "恶铁岭曾是黑铁矮人的一处主要营地，由术士卑劣的巴尔加拉斯率领。",
			full = "恶铁岭曾是黑铁矮人的一处主要营地，由术士卑劣的巴尔加拉斯率领。",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "龙喉大门",
			short = "龙喉大门由幼龙艾克斯托兹统领的红龙军团把守，他守住这条道路，阻挡那些想要前往格瑞姆巴托的人。",
			full = "龙喉大门由幼龙艾克斯托兹统领的红龙军团把守，他守住这条道路，阻挡那些想要前往格瑞姆巴托的人。",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "丹奥加兹",
			short = "穿过丹奥加兹的隧道比导致矮人分裂的那场争端还要古老。当三锤之战将蛮锤矮人逐出铁炉堡时，他们正是经由这条通道撤退的。",
			full = "穿过丹奥加兹的隧道比导致矮人分裂的那场争端还要古老。当三锤之战将蛮锤矮人逐出铁炉堡时，他们正是经由这条通道撤退的。\n\n它也见证了部落的撤退。兽人在丹莫德被击退之后，向南越过萨多尔山谷，在这里的前哨掘壕固守，而安度因·洛萨希望将他们彻底赶出卡兹莫丹，便派出他的部队去摧毁这座要塞。进攻失败了。兽人坚守了下来，丹奥加兹成了部落在这一地区保留的最后一块土地，一个无法被撬动的立足点。\n\n守望这条通道的矮人巡山人大多驻守在它上方的山丘上，但龙喉氏族攻占了他们的哨所，将他们赶回了上层隧道，他们至今仍在那里坚守。由于下层通道失守，矮人家园与米奈希尔港之间的道路变得危险了许多。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "丹莫德",
			short = "丹莫德位于萨多尔大桥以南，是一座早已沦为废墟的古老矮人城市，它的铁匠铺和兼作酒馆的酿酒坊依然矗立在一片被黑铁矮人据为己有的残骸之中。",
			full = "丹莫德位于萨多尔大桥以南，是一座早已沦为废墟的古老矮人城市，它的铁匠铺和兼作酒馆的酿酒坊依然矗立在一片被黑铁矮人据为己有的残骸之中。\n\n第二次战争期间，兽人部落占领了这片废墟，并在那里建起了一座前哨，用它来击退联盟军队、袭掠周围的农田，这是他们的军队至关重要的集结地。激流堡的战士们从岛上的要塞托尔巴拉德出击，要摧毁那座前哨，他们展开围攻，将兽人向南赶到了他们在丹奥加兹的第二据点。部落进行了反击，夺回了丹莫德，甚至将矛头指向了托尔巴拉德本身。直到部落在王城前被击溃，安度因·洛萨才将他们经由萨多尔大桥赶回了卡兹莫丹，丹莫德也随之归属了联盟。\n\n那份和平并没有持续下去。由于铁炉堡的士兵在远离家乡的战争中消耗殆尽，黑铁矮人冲破了萨多尔大桥，丹莫德不久之后也落入了术士卑劣的巴尔加拉斯之手，如今他占据着这座被他的族人据为己有的城市。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "绿带草地",
			short = "绿带草地上挤满了鳄鱼、沼泽兽和软泥怪，绿色守卫者雷希尔在这里守望，这片变得怪异而不安的土地让他满腔怒火。",
			full = "绿带草地上挤满了鳄鱼、沼泽兽和软泥怪，绿色守卫者雷希尔在这里守望，这片变得怪异而不安的土地让他满腔怒火。\n\n在西边，泥潭兽变得充满恶意。在东北方，火元素出人意料地从恶铁岭中冒了出来。这两者都是雷希尔所守护的这片土地上的伤口，而且都丝毫没有减弱的迹象。\n\n在绿带草地中，有一支龙喉氏族车队的残骸，如今红色雏龙在它的废墟中筑窝，那是一次企图偷走黑龙军团幼龙的行动所留下的唯一遗迹，那次行动在这里走到了尽头，被沼泽所吞没。",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "格瑞姆巴托",
			short = "格瑞姆巴托是一座位于湿地东部的山中要塞。它有着高大的城墙和直指钢灰色天空的尖塔，但要塞的主体却位于地下。",
			full = "格瑞姆巴托是一座位于湿地东部的山中要塞。它有着高大的城墙和直指钢灰色天空的尖塔，但要塞的主体却位于地下。它由蛮锤矮人建立，直到它在三锤之战中遭受诅咒。后来它被兽人占领，被用作关押守护巨龙阿莱克丝塔萨的监狱，直到她在格瑞姆巴托之战中获得自由。",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "铁须之墓",
			short = "铁须之墓位于湿地中北部通往丹莫德的道路以西。一尊矮人雕像矗立在这里的墓地上方，雕刻的大概就是铁须本人的模样。",
			full = "铁须之墓位于湿地中北部通往丹莫德的道路以西。一尊矮人雕像矗立在这里的墓地上方，雕刻的大概就是铁须本人的模样。\n\n死者在这里已经不再安息。黑色、深红色以及各种骇人颜色的软泥怪爬进了墓穴，玷污了它，并在整个墓地中蔓延开来，直到再也没有想要安葬亲人的人愿意靠近这个地方。",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "失落的舰队",
			short = "浪潮女主人号和无畏号的残骸躺在巴拉丁海湾的海底，位于蓝腮沼泽北部的海岸外。",
			full = "浪潮女主人号和无畏号的残骸躺在巴拉丁海湾的海底，位于蓝腮沼泽北部的海岸外。\n\n它们曾是第二次战争期间库尔提拉斯第三舰队的一部分，这支舰队由海军上将戴林·普罗德摩尔的长子德里克·普罗德摩尔指挥。在冠顶之战中，被龙喉氏族奴役的红龙从天而降，点燃了舰队。德里克爬上瞭望台，想要向他的父亲发出警告。在警告还没来得及发挥作用之前，一条巨龙就在那里杀死了他，不久之后，他的船也随着舰队的其他船只一起沉没了。只有一个人幸存了下来，那就是浪潮女主人号的大副菲茨西蒙斯。\n\n死者并没有安静下来。在无畏号船舱深处，它的指挥官哈林多尔船长出于贪婪藏起了一颗焦黑的宝珠：帕雷斯的诅咒之眼。多年以后，它的诅咒蔓延到了沉没的船员身上，将他们束缚成了亡灵。只有大副斯奈利格在这场诅咒中保住了神智，他的鬼魂至今仍在附近的海岸上游荡。",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "米奈希尔海湾",
			short = "米奈希尔海湾位于港口和丹莫罗的悬崖之间，嵌在巴拉丁海湾的入海口之中。",
			full = "米奈希尔海湾位于港口和丹莫罗的悬崖之间，嵌在巴拉丁海湾的入海口之中。\n\n在海湾入口附近，躺着飞鱼鹰号的残骸，它破损的船体沉在水中。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "米奈希尔港",
			short = "城墙是任何人首先注意到的东西，厚厚的石墙环绕着一座港口小镇，小镇一半建在岩石上，一半建在海上。",
			full = "城墙是任何人首先注意到的东西，厚厚的石墙环绕着一座港口小镇，小镇一半建在岩石上，一半建在海上。四座塔楼高耸其上，同时监视着海面和道路，要进入这里，除了桥梁、潮水，或者一条通往大陆的隐秘地下通道之外，别无他路。\n\n最早在这里建立造船厂的是兽人。第一次战争之后，酋长奥格瑞姆·毁灭之锤选中了这片海岸来建造舰队，以便载着部落绕过洛丹伦的地面防御，为此，他从卡兹莫丹的矮人矿井中搜刮铁矿和木材。第二次战争结束时，联盟占领了这里，并将它重建为自己的港口，海军上将戴林·普罗德摩尔以洛丹伦国王泰瑞纳斯·米奈希尔二世的名字，将它命名为米奈希尔港。\n\n此后多年，迅猛龙不断从山中出来袭击这座小镇，数量从来不多，但次数却相当频繁。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "米奈希尔城堡",
			short = "四座塔楼耸立在米奈希尔港的上方，像严厉的守护者一样注视着下方的小镇。这里就是米奈希尔城堡。",
			full = "四座塔楼耸立在米奈希尔港的上方，像严厉的守护者一样注视着下方的小镇。这里就是米奈希尔城堡。",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "藓皮沼泽",
			short = "藓皮沼泽是湿地东部一片积水的土地，地面上散布着藓皮豺狼人的营地。这个部族占据着沼泽，抓住并吞噬任何深入沼泽太远的人。",
			full = "藓皮沼泽是湿地东部一片积水的土地，地面上散布着藓皮豺狼人的营地。这个部族占据着沼泽，抓住并吞噬任何深入沼泽太远的人。",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
