		},
		["saltspray glen"] = {
			name = "盐沫沼泽",
			short = "盐沫沼泽位于湿地与巴拉丁海湾交界的地方，在蓝腮沼泽和铁须之墓之间。",
			full = "盐沫沼泽位于湿地与巴拉丁海湾交界的地方，在蓝腮沼泽和铁须之墓之间。它的名字来自海风：当海风从海湾猛烈地吹来时，海浪会把浪沫一直抛到这里的内陆深处，比这片海岸上的任何地方都要远，直到地面本身都被盐分浸得湿滑。迅猛龙在整个沼泽中密密麻麻地筑巢，就像在附近的沼泽和山岭上一样。",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "日落沼泽",
			short = "日落沼泽深藏在湿地的西北部，到处都是鳄鱼、豺狼人、迅猛龙、沼泽兽和软泥怪，让大多数旅人望而却步。",
			full = "日落沼泽深藏在湿地的西北部，到处都是鳄鱼、豺狼人、迅猛龙、沼泽兽和软泥怪，让大多数旅人望而却步。沼泽的中心矗立着迅轮岗哨，那是一座带有风车的小石屋，弗拉德·迅轮和温娜·丝须在那里安了家。这两人经营着沼泽出产的东西，从泥浆中捞出来的奇特物品，以及在别处难得一见的配方。",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "萨多尔大桥",
			short = "两座巨大的石拱横跨在湿地与阿拉希高地之间的峡谷上，它们由矮人亲手建造，三代以来一直由安威玛尔家族守护。",
			full = "两座巨大的石拱横跨在湿地与阿拉希高地之间的峡谷上，它们由矮人亲手建造，三代以来一直由安威玛尔家族守护。它们建于三锤之战之后，当时铁炉堡希望与鹰巢山的蛮锤同胞保持友好，这两座桥梁便成了两个矮人王国之间的道路与象征，承载着令双方都富足起来的贸易。\n\n如今，这两座桥伤痕累累。卡姆·深怒和卑劣的巴尔加拉斯率领黑铁矮人进攻大桥，彻底摧毁了两座石拱中的一座，还差点夺下了第二座。矮人部队奋力守卫剩下的部分，并试图夺回附近的丹莫德镇，许多人在那场战斗中牺牲，其中包括苏利·巴鲁、伊贝尼瑟·锈锁，以及布莱德·长须的兄弟。黑铁矮人至今仍占据着这片残骸，而卑劣的巴尔加拉斯依然活在他们之中。",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "瑟根石",
			short = "瑟根石耸立在湿地南部，它的洞穴深深地延伸进山体之中，到处都是有毒的蜘蛛，在每一道缝隙中吐丝结网。",
			full = "瑟根石耸立在湿地南部，它的洞穴深深地延伸进山体之中，到处都是有毒的蜘蛛，在每一道缝隙中吐丝结网。在更深处的坑道中的某个地方，有一些火岩矿脉，被成群的蜘蛛守护着。",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "维尔加挖掘场",
			short = "米奈希尔港以东的这处挖掘场，曾经是矮人们在比记忆还要古老的土地上静静挖掘的地方。后来斑点迅猛龙占领了这里，把挖掘者们困在了他们自己的挖掘场上方的一道山脊上。",
			full = "米奈希尔港以东的这处挖掘场，曾经是矮人们在比记忆还要古老的土地上静静挖掘的地方。后来斑点迅猛龙占领了这里，把挖掘者们困在了他们自己的挖掘场上方的一道山脊上。他们没能坚持下去，放弃了这处挖掘场，在主路旁建起了一座他们自己的营地，维尔加的居所。\n\n他们留下的东西至今仍半埋在土中。如今，活化石和古老的元素生物在矿坑中行走，对那些被丢在那里生锈的鹤嘴锄毫不在意。",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- 泰达希尔: 17 subzones
	[1438] = {
