		["oracle glade"] = {
			name = "神谕林地",
			short = "神谕林地位于泰达希尔的西北部，环抱着这棵巨树上第一口、也是力量最强大的一口月亮井。",
			full = "神谕林地位于泰达希尔的西北部，环抱着这棵巨树上第一口、也是力量最强大的一口月亮井。这里矗立着神谕之树，它宽大的树干向上伸展，枝干的形状就像一只栖息在熊背上的雄鹰。许多人私下里说，任何寻常的生长都不可能长成这样的形态，唯有自然魔法才能塑造出它来。\n\n这棵树与德鲁伊们一同守望着泰达希尔的成长。\n\n血羽鹰身人在附近筑巢，威胁着这棵树，一小队哨兵被派来阻挡她们。",
