		["pools of arlithrien"] = {
			name = "阿里斯瑞恩之池",
			short = "在达纳苏斯以南、泰达希尔西部，阿里斯瑞恩之池曾经一片宁静。当脊骨熊怪占领这一地区时，暗夜精灵放弃了那里的一口月亮井。",
			full = "在达纳苏斯以南、泰达希尔西部，阿里斯瑞恩之池曾经一片宁静。当脊骨熊怪占领这一地区时，暗夜精灵放弃了那里的一口月亮井。那口井依然无人照料地矗立在池塘之间，如今成了敌对野兽的栖息之地。",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "鲁瑟兰村",
			short = "鲁瑟兰村坐落在泰达希尔的树根处，在世界之树与海水相接的地方，头顶的高处便是达纳苏斯。",
			full = "鲁瑟兰村坐落在泰达希尔的树根处，在世界之树与海水相接的地方，头顶的高处便是达纳苏斯。与都城相比，它的建筑显得朴素，但却保持得极为清新，仿佛这里的人们引以为傲的是简朴，而不是宏大。\n\n卡多雷在这里照料着角鹰兽的栖所，收集和照看角鹰兽的蛋，并把幼崽抚养到它们能够飞翔为止。这是一份安静的工作，由那些平时辛勤劳作、维持村庄运转以支持上方城市的人们来完成，他们并不要求多少认可。\n\n不过，这座村庄并不只有劳作。每当仲夏火焰节到来时，村里的火盆就会被点燃，那些照料角鹰兽蛋、装卸船只的双手，便转而投入到庆典之中。",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "幽影谷",
			short = "在泰达希尔的枝干之下，藏在这座岛屿东北部的，是一片从未真正见过完整白昼的林间空地。幽影谷终年笼罩在暮色之中，除了一面之外，四面都被群山环绕。",
			full = "在泰达希尔的枝干之下，藏在这座岛屿东北部的，是一片从未真正见过完整白昼的林间空地。幽影谷终年笼罩在暮色之中，除了一面之外，四面都被群山环绕。只有在南面，岩石才断开，让一条小路穿过，通往多兰纳尔。\n\n在空地的中心矗立着奥达希尔，这棵巨树完全主宰着这片林间空地，仿佛整个山谷都是围绕着它布置的。在西北方，地面敞开，通向黑丝洞，那是切入环绕山谷的丘陵中的一道黑暗裂缝。",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
