			short = "黑丝洞位于幽影谷的西北角，在泰达希尔的树根之中。它一直属于岛上的巨型蜘蛛，但最近它们变得焦躁不安，洞穴也变得更加危险。",
			full = "黑丝洞位于幽影谷的西北角，在泰达希尔的树根之中。它一直属于岛上的巨型蜘蛛，但最近它们变得焦躁不安，洞穴也变得更加危险。\n\n在最深处住着卑鄙的吉瑟斯，它是这窝蜘蛛中最大的一只，不止一个深入太远的年轻卡多雷葬送在它的手中。",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "星风村",
			short = "星风村曾经属于暗夜精灵，是幽影谷东南方的一小片房屋。如今那里已经没有暗夜精灵了，房屋被腐化的脊骨熊怪占据。",
			full = "星风村曾经属于暗夜精灵，是幽影谷东南方的一小片房屋。如今那里已经没有暗夜精灵了，房屋被腐化的脊骨熊怪占据。乌鲁森在它的小路上来回踱步，而在村子的边缘潜伏着噬梦者菲罗斯塔，单凭这头野兽的存在，就足以说明这座村庄已经从昔日的模样堕落到了何种地步。",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
