		["wellspring lake"] = {
			name = "涌泉湖",
			short = "涌泉湖的湖水来自泰达希尔内部深处的一眼泉水，溢出的湖水化作涌泉河流走。暗夜精灵的渔夫们曾经钟爱这片宁静的水域。",
			full = "涌泉湖的湖水来自泰达希尔内部深处的一眼泉水，溢出的湖水化作涌泉河流走。暗夜精灵的渔夫们曾经钟爱这片宁静的水域。如今栖息在这里的树人已经被腐化，夜刃豹和蜘蛛也悄悄潜入了周围的土地，让这个曾经宁静的垂钓之地变成了一个危险的地方。",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "涌泉河",
			short = "涌泉河发源于泰达希尔内部深处的一眼泉水，从涌泉湖向北流到巨树的边缘，在那里化作一道巨大的瀑布，坠入下方的大海。",
			full = "涌泉河发源于泰达希尔内部深处的一眼泉水，从涌泉湖向北流到巨树的边缘，在那里化作一道巨大的瀑布，坠入下方的大海。\n\n如今，发狂的树人在它的岸边潜行，攻击任何靠近的人。",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- 黑海岸: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "亚米萨兰",
			short = "亚米萨兰的废墟位于黑海岸的奥伯丁东南方，这座城镇的某些东西至今仍在那里游荡。",
			full = "亚米萨兰的废墟位于黑海岸的奥伯丁东南方，这座城镇的某些东西至今仍在那里游荡。\n\n艾萨拉女王当年建造了亚米萨兰，作为巴莎兰的双子城，让她宠信的上层精灵居住在它的集市和供奉艾露恩的神殿之间。她任命阿斯利库斯·纳拉辛统治这里，他是一位法力高强的法师，平时待在他的奥萨拉克斯之塔中。\n\n当大分裂来临、城镇已经开始崩塌时，这里的人们紧紧依附着这片土地，仿佛只有这样才能拯救他们。阿斯利库斯·纳拉辛出现在他们之中，承诺施放一个法术，让他们免遭即将到来的毁灭，在他随身携带的灵魂宝石中赐予他们永生。当他念出咒语时，他周围的精灵们纷纷死去。他所给予他们的永恒是一座牢笼，而不是一场拯救，从那以后，一直徘徊在亚米萨兰的是他们的灵魂，而不是他们的生命。\n\n两块巨大的石碑至今仍矗立在废墟之中，上面刻着这座城镇陷落的故事。一名前来阅读石碑的哨兵还没来得及读完，就遭到了不得安宁的上层精灵的袭击，只好逃走了。",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "奥伯丁",
			short = "奥伯丁坐落在大分裂撕裂大地的地方，这片海岸吞没了古老的卡多雷帝国那些宏伟的城市。此后在黑海岸尝试建立的每一个定居点都失败了，只有迷雾之海边上的这一座城镇例外。",
			full = "奥伯丁坐落在大分裂撕裂大地的地方，这片海岸吞没了古老的卡多雷帝国那些宏伟的城市。此后在黑海岸尝试建立的每一个定居点都失败了，只有迷雾之海边上的这一座城镇例外。\n\n它的发展与暗夜精灵社会的其他部分截然不同。它的港口吸引着来自东部王国的船只和商人，街道上挤满了矮人、侏儒、人类，甚至还有高等精灵，因此奥伯丁比一座暗夜精灵城镇应有的样子要明亮得多，它的路标为了方便外来者而用两种文字书写。达纳苏斯因此看不起它。曾经到访过这座城镇的布洛尔·熊皮认为，这里的人们比流浪汉和怪人好不了多少，而驻扎在这里的哨兵也与她们所守护的人们保持着距离。然而，曾经驻扎在这里的珊蒂斯·羽月却记得，这是一个充满欢声笑语的地方。\n\n在灯塔附近，一艘曾由精灵艾鲁拉指挥的船只的残骸至今仍标记着那片礁石，船沉没时，它所载的月光石矿也一同遗失了。",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "巴莎兰",
			short = "在大海涌起、使世界破碎之前，艾萨拉女王在黑海岸北部为她宠信的上层精灵建造了两座双子城：亚米萨兰和巴莎兰。",
			full = "在大海涌起、使世界破碎之前，艾萨拉女王在黑海岸北部为她宠信的上层精灵建造了两座双子城：亚米萨兰和巴莎兰。她派一位魔法力量强大的精灵阿斯利库斯·纳拉辛统治它们，在他手下效力的是阿斯特利安，一位精通奥术和武艺的法师，他住在巴莎兰的人民之中，并时常前往亚米萨兰照料那里的居民。在那些日子里，这两座双子城拥有集市和供奉艾露恩的神殿，享受着女王本人的恩宠。\n\n当第一口永恒之井被摧毁时，两座城市都沦为了废墟。然而在某个时候，阿斯利库斯·纳拉辛用他的法术对付他自己的副手，将阿斯特利安封印在一块月光石封印之中，把他囚禁在巴莎兰的石头之间。主人为什么要背叛他的仆人，如今已经没有任何活着的人能够说清。阿斯特利安在漫长而痛苦的一生中忍受着这座牢狱，而当他终于死去时，他发现死亡并没有让他获得自由。他的灵魂依然被束缚着，就像他的肉体曾经被束缚那样牢固。",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "黑木洞穴",
			short = "在黑海岸的最南端，靠近灰谷的边界，一些零散的熊怪营地和一个小洞穴组成了被称为黑木洞穴的地方，有时也被称为黑木要塞。",
			full = "在黑海岸的最南端，靠近灰谷的边界，一些零散的熊怪营地和一个小洞穴组成了被称为黑木洞穴的地方，有时也被称为黑木要塞。占据这里的熊怪已经被腐化，被扭曲得面目全非。\n\n在洞穴里坐着一个名叫沃科尔的孤独的暗夜精灵，他被熊怪囚禁在这里。",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "峭壁之泉",
			short = "峭壁之泉是壁泉河的源头，曾经是河中最纯净的水，也是整个黑海岸的饮用水源。那水已经不再清澈了。",
			full = "峭壁之泉是壁泉河的源头，曾经是河中最纯净的水，也是整个黑海岸的饮用水源。那水已经不再清澈了。瀑布涌出的那个洞穴已经变得污秽不堪，腐化随着水流一路蔓延，流经这片它曾经滋养过的地区。\n\n没有人能说清其中的原因。有些人归咎于费伍德森林，说污秽只是从那片被毁的森林中向外渗透。另一些人则指向在洞穴深处发现的东西，如今纳迦正在水源处的黑暗中爬行。",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "壁泉河",
			short = "壁泉河从峭壁之泉流向黑海岸北部的大海。它的河水被暴鳞纳迦所污染，饮用河水的野生动物常常会生病。",
			full = "壁泉河从峭壁之泉流向黑海岸北部的大海。它的河水被暴鳞纳迦所污染，饮用河水的野生动物常常会生病。",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "古树之林",
			short = "古树之林是一座古老的暗夜精灵神殿，它的石头环绕着黑海岸群山中奔腾的急弯河。",
			full = "古树之林是一座古老的暗夜精灵神殿，它的石头环绕着黑海岸群山中奔腾的急弯河。知识古树安努与一位沉睡的德鲁伊和两名商人一同住在这里，古树议会至今仍在这里聚会。",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "长桥码头",
			short = "长桥码头从奥伯丁向南延伸到亚米萨兰以西的水域，尽管名字如此，它却是黑海岸最短的一段海岸。",
			full = "长桥码头从奥伯丁向南延伸到亚米萨兰以西的水域，尽管名字如此，它却是黑海岸最短的一段海岸。灰色的沙滩躺在终日阴霾的天空之下。潮水留下的除了浮木和死去的海洋生物的尸体之外，几乎别无他物。沿着海岸可以看到鱼人的身影。",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "主宰之剑",
			short = "在黑海岸的西南部，有一颗巨大的头骨，一半被泥土吞没，一把精金战刃仍然插在骨头之中。",
			full = "在黑海岸的西南部，有一颗巨大的头骨，一半被泥土吞没，一把精金战刃仍然插在骨头之中。这就是上古之神的使者滑行者索苟斯，而那把刀刃则被称为主宰之剑。\n\n在雷姆塔维尔挖掘场出土的石板讲述了这里发生的事情。泰坦曾派出二十个石巨人对抗索苟斯，随后的战斗是如此惨烈，以至于只有其中一个巨人活着看到了结局：克朗，二十个巨人中最高大的一个。当索苟斯的触须缠住他时，克朗并没有挣脱开来。他任由自己被拖向里面，越来越靠近这个怪物的头骨，直到近得足以发动攻击。杀死索苟斯的那一击，是在它自己的掌握之中发出的，而那把留在它头骨中的剑，也以那场胜利为名。\n\n此后，暮光之锤占据了这个地方，在索苟斯的遗骸中挖掘，力图消除克朗之剑所成就的一切，将上古之神的使者召回这个世界。",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "薄雾海",
			short = "被称为薄雾海的海岸贯穿黑海岸的全境，是这一地区最长的海岸线。",
			full = "被称为薄雾海的海岸贯穿黑海岸的全境，是这一地区最长的海岸线。\n\n这是一片阴郁的海岸：灰色的海滩和阴森的海湾，散落着死去的海洋动物的巨大尸体和沉船的残骸。\n\n螃蟹在整片海岸上爬来爬去，鱼人潜伏在浅浅的海湾中，对任何在岸边行走的人来说都是一个无处不在的威胁。",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "雷姆塔维尔挖掘场",
			short = "勘察员雷姆塔维尔将自己的名字给了黑海岸的这处挖掘场。",
			full = "勘察员雷姆塔维尔将自己的名字给了黑海岸的这处挖掘场。他在挖掘中发现了一块与众不同的化石，嗡嗡作响，蕴含着神秘的力量，但这位健忘的勘察员后来却忘了自己把它放在哪儿了。\n\n挖掘场本身也变得危险起来：砾石穴居人占据了它的坑道，被挖掘出来的巨大傀儡如今也在其中蠢蠢欲动。",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "玛塞斯特拉废墟",
			short = "越过奥萨拉克斯之塔，在黑海岸的北部，坐落着玛塞斯特拉的废墟。在大分裂之前，它是一座暗夜精灵的城市，建于上层精灵的时代。",
			full = "越过奥萨拉克斯之塔，在黑海岸的北部，坐落着玛塞斯特拉的废墟。在大分裂之前，它是一座暗夜精灵的城市，建于上层精灵的时代。当永恒之井自我毁灭、世界在它下方破碎时，玛塞斯特拉与许多其他东西一起毁于一旦，而幸存下来的暗夜精灵也没有回来重建它。他们转而退到了更南边沿海的一些小村庄，把这片废墟留在了身后。\n\n古老的上层精灵遗物至今仍零散地躺在倒塌的石头之间，年轻的暗夜精灵有时会来到玛塞斯特拉寻找它们，同时还要提防那些在他们的族人昔日建造的废墟中徘徊的幽灵豹。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "奥萨拉克斯之塔",
			short = "在大分裂的时代，当艾萨拉女王将上层精灵抬升到其他所有人之上时，她派一位名叫阿斯利库斯·纳拉辛的精灵去统治亚米萨兰和巴莎兰这两座双子城。",
			full = "在大分裂的时代，当艾萨拉女王将上层精灵抬升到其他所有人之上时，她派一位名叫阿斯利库斯·纳拉辛的精灵去统治亚米萨兰和巴莎兰这两座双子城。起初，阿斯利库斯为她效力得还算尽心，但这份工作让他感到厌倦，于是他开始远离城镇，在一座名为奥萨拉克斯的属于他自己的高塔中度日。\n\n一万年后，长久以来关于那座高塔的传言被证实了。一个自称暗链教派的邪教聚集在那里，其中有术士，还有一个萨特，而站在他们最前面的，正是阿斯利库斯·纳拉辛本人。他们的目的一直不甚明了，直到后来真相大白：这个教派听命于暗影议会，而奥萨拉克斯已经成了那个古老阴谋之网中的又一根丝线。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "暮光谷",
			short = "亚米萨兰以南、一直延伸到灰谷边界的森林被称为暮光谷。",
			full = "亚米萨兰以南、一直延伸到灰谷边界的森林被称为暮光谷。被腐化的熊怪、野性的夜刃豹和疯狂的熊在这片树林中出没，人们劝告旅人最好沿着道路走，而不要在树林间游荡。",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "急弯河",
			short = "急弯河将它的疾病从山上带下来，它是血毒河的延续，从费伍德森林流入黑海岸南部，靠近古树之林。",
			full = "急弯河将它的疾病从山上带下来，它是血毒河的延续，从费伍德森林流入黑海岸南部，靠近古树之林。它的河水已被污染，费伍德森林的腐化顺着水流一直蔓延到这些低地之中。",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- 灰谷: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "阿斯特兰纳",
			short = "阿斯特兰纳从灰谷中心的一座岛屿上崛起，是这一地区最大的暗夜精灵定居点，只能通过一对横跨水面的桥梁到达。",
			full = "阿斯特兰纳从灰谷中心的一座岛屿上崛起，是这一地区最大的暗夜精灵定居点，只能通过一对横跨水面的桥梁到达。湖泊将它与周围的森林分隔开来，使它成为一片争夺之地中心的一个安静而易守难攻的地方。\n\n它的墓地位于湖岸边，镇上的死者就安葬在一排排静谧的石碑之间。\n\n在城镇之外，蓟皮熊怪已经在北方积聚起了力量，阿斯特兰纳的人们担心，有朝一日它们可能会鼓起勇气，将力量转向城镇本身。",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "巴斯兰鬼屋",
			short = "巴斯兰鬼屋的石柱曾经是一座卡多雷遗迹的一部分，建于暗夜精灵仍在灰谷这一带行走的时代。",
			full = "巴斯兰鬼屋的石柱曾经是一座卡多雷遗迹的一部分，建于暗夜精灵仍在灰谷这一带行走的时代。那个时代过去了，精灵们撤走了，大理石也任其开裂倒塌。\n\n如今这里并非空无一人。被遗忘者的特工在残破的石柱之间住了下来，其中有草药师和保护他们的打手，而无论他们在哪里落脚，那里的土地都会以同样的方式回应：青草变得枯黄，花朵纷纷凋谢。他们在倒塌的石头之间搭起了一座临时实验室，为了他们自己的目的而研究着当地的草药。\n\n吸引他们来到这里的，主要是一种在附近别处都找不到的植物：巴斯兰的头发，这是一种治疗用的草药，稀有到单凭它就值得守住这个地方。",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "黑暗深渊",
			short = "在佐拉姆海岸之下，古老的城市佐拉姆沉入大海的地方，沉睡着拉萨·拉扎尔被淹没的厅堂，那里曾经是一座供奉艾露恩的神殿。",
			full = "在佐拉姆海岸之下，古老的城市佐拉姆沉入大海的地方，沉睡着拉萨·拉扎尔被淹没的厅堂，那里曾经是一座供奉艾露恩的神殿。人们原以为大分裂已将它彻底摧毁，数千年来，大海一直守着它。\n\n后来，暮光之锤来了，他们被低语和邪恶的梦境吸引，来到了这座神殿所化成的水下洞穴。这个邪教在那片深处献祭了无数无辜的人，并因此得到了一项使命：养育和保护上古之神的一个珍爱之物，那就是可怕的九头蛇吞噬者阿库麦尔，直到它被释放到世界上的那一天。这个地方如今被称为黑暗深渊，这个名字恰如其分。",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "血牙营地",
			short = "血牙营地位于弗伦河以西，在灰谷南部月亮井的西南方。它得名于兰·血牙，他是占据这里的熊怪部族的首领。",
			full = "血牙营地位于弗伦河以西，在灰谷南部月亮井的西南方。它得名于兰·血牙，他是占据这里的熊怪部族的首领。\n\n这些熊怪曾经和它们的其他同类一样，但腐化已经攫住了它们每一个，如今这座营地对任何靠近的外人都报以敌意。",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "大树荫",
			short = "在林歌神殿之外，在灰谷的树木长得茂密而古老的地方，大树荫守护着一座通往翡翠梦境的传送门。",
			full = "在林歌神殿之外，在灰谷的树木长得茂密而古老的地方，大树荫守护着一座通往翡翠梦境的传送门。\n\n绿龙军团守卫着这里。幼龙法恩提姆和梦境猎手守望着这条通道，龙人三个一组在周围的树林中巡逻，一名翡翠先知由枝干守卫和树木守护者护卫在两侧，在漫长的守望中一遍又一遍地走过同一片土地。",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "屠魔峡谷",
			short = "屠魔峡谷留下了兽人挣脱昔日枷锁那一刻的伤痕。",
			full = "屠魔峡谷留下了兽人挣脱昔日枷锁那一刻的伤痕。\n\n深渊领主玛诺洛斯正是在这里与格罗玛什·地狱咆哮和萨尔展开了殊死搏斗。恶魔击倒了萨尔，却没能及时躲开格罗姆的战斧，那把斧头劈进了他的胸膛。玛诺洛斯的死化作烈焰与光芒向外爆发，那同一股烈焰在吞噬恶魔的同时，也夺走了格罗姆的生命。兽人占据了他牺牲的地方，并以他的名字为它命名，因为正是在那里，燃烧军团施加在他们族人身上的诅咒被打破了。\n\n至今仍有许多兽人长途跋涉来到这里，缅怀那位为这份自由付出代价的战士，这里还矗立着一座纪念他的纪念碑。但这片土地依然被邪能所沾染，如今低等恶魔在峡谷中出没。",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "屠魔山",
			short = "在屠魔峡谷的上方，山岭破碎地耸立着，它的山坡和开凿在山侧的兽穴都被低等恶魔所占据。",
			full = "在屠魔峡谷的上方，山岭破碎地耸立着，它的山坡和开凿在山侧的兽穴都被低等恶魔所占据。在更深处，在日光照不到的地方，等待着寻找者迪亚索鲁斯，这个恐惧魔王统治着聚集在灰谷的恶魔集会，他在黑暗中坐镇，而低等恶魔则守卫着上方的山岭。",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "朵丹尼尔兽穴",
			short = "朵丹尼尔兽穴长久以来一直是暗夜精灵德鲁伊的安息之所，他们的身体在这里沉睡，而灵魂则自由地四处漫游。",
			full = "朵丹尼尔兽穴长久以来一直是暗夜精灵德鲁伊的安息之所，他们的身体在这里沉睡，而灵魂则自由地四处漫游。是被遗忘者将注意力转向了这些沉睡者，切断了德鲁伊与他们漫游的灵魂之间的联系。这场实验并没有杀死他们。它让他们发了疯。\n\n如今，这座兽穴里已经没有安详的沉睡者了。被遗忘者的刺客在其中无影无踪地穿行，而那些被切断联系的德鲁伊愤怒的灵魂则在土丘中肆虐，无处可归。在它们之中，有三个比其他灵魂更强大的灵魂徘徊不去：乌希尔·月唤、玛沃里斯·裂云和塔尼尔·暗木。",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "弗伦河",
			short = "弗伦河几乎将灰谷一分为二。河的西边是阿斯特兰纳治下的暗夜精灵；东边则是兽人据守的碎木岗哨。",
			full = "弗伦河几乎将灰谷一分为二。河的西边是阿斯特兰纳治下的暗夜精灵；东边则是兽人据守的碎木岗哨。河水浅得可以涉水而过，窄得不费什么力气就能过河，除非雨水使它漫过河岸，但它依然标志着一条边界，两个民族都心照不宣。\n\n它的河水发源于海加尔山的山坡上，经过一道道瀑布落入萨维亚的湖中，然后在碎木岗哨和夜道谷之间继续流淌，从大多数旅人穿越灰谷时所走的那座大桥下方流过，经过银翼哨站和净化月亮井，最后在北部山脉下方潜入地下，流向贫瘠之地。\n\n在冥火岭附近，这条河还隐藏着另一种危险。沼泽兽潜伏在那里的水面下，攻击任何在水中逗留太久的东西。",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "坠星湖",
			short = "在灰谷银翼哨站以南有一座小湖，湖水环绕着一座孤零零的小岛。",
			full = "在灰谷银翼哨站以南有一座小湖，湖水环绕着一座孤零零的小岛。岛上住着一位荆棘影先知，他是荆棘影族人中的一位长者，他的族人数量较少，环绕着湖岸，从周围的芦苇丛和灌木丛中守望着湖水。",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "冥火岭",
			short = "冥火岭至今仍带着第三次战争留下的伤痕，当时地狱火燃烧着从天而降，撞击在这里的大地上。从那以后，恶魔便一直逗留在这里，这些污秽之物在岩石间筑窝。",
			full = "冥火岭至今仍带着第三次战争留下的伤痕，当时地狱火燃烧着从天而降，撞击在这里的大地上。从那以后，恶魔便一直逗留在这里，这些污秽之物在岩石间筑窝。\n\n部落加固了通往山岭的两座桥梁，守住它们，以防恶魔涌向附近的定居点。",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "火痕神殿",
			short = "火痕神殿坐落在灰谷的西南部，它被暗影议会的恶魔影响所腐化，直到变成了一个极其邪恶的地方。",
			full = "火痕神殿坐落在灰谷的西南部，它被暗影议会的恶魔影响所腐化，直到变成了一个极其邪恶的地方。兽人术士伊尔克鲁德·玛格斯鲁尔曾经住在这里，为暗链教派的首领阿斯利库斯·纳拉辛效力。\n\n如今，恶魔被岩石中残留的污秽所吸引，在神殿中肆虐。在它们之中，一个名叫阿克里鲁斯的末日守卫不时在这一带出现，这是一个罕见而危险的迹象，表明腐化已经深入到了何种程度。",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "林歌神殿",
			short = "林歌神殿是灰谷森林中一座古老的暗夜精灵遗迹，长久以来一直任由苔藓覆盖、被人遗忘。有一段时间，这里几乎没有任何人。",
			full = "林歌神殿是灰谷森林中一座古老的暗夜精灵遗迹，长久以来一直任由苔藓覆盖、被人遗忘。有一段时间，这里几乎没有任何人。\n\n后来，德鲁伊凯尼斯·静风将这里据为己有，成了这片遗迹唯一的居民，他在这些石头之间指挥着这一地区对抗被遗忘者的战斗。一个被遗忘的地方就这样变成了一座哨所，守住它的不是人数，而是一位德鲁伊拒绝离开的决心。",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "绿爪村",
			short = "绿爪村是污林部族的家园，这些熊怪由穆尔古特酋长和萨满橡爪率领。这里的熊怪已经被腐化了。",
			full = "绿爪村是污林部族的家园，这些熊怪由穆尔古特酋长和萨满橡爪率领。这里的熊怪已经被腐化了。",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "狼嚎谷",
			short = "一个洞穴通向矗立着梅尔·萨恩德里斯神殿的山谷，神殿的石头上刻着一段赞美艾露恩的古老铭文，上方还用达纳苏斯语写着：真理是指路的明灯。",
			full = "一个洞穴通向矗立着梅尔·萨恩德里斯神殿的山谷，神殿的石头上刻着一段赞美艾露恩的古老铭文，上方还用达纳苏斯语写着：真理是指路的明灯。\n\n这座神殿是维琳德·星歌的母亲为纪念梅尔·萨恩德里斯而建造的，梅尔·萨恩德里斯曾受托保管艾露恩之镰。梅尔·萨恩德里斯去世后，这把镰刀被安放在这里，藏在神殿之中。它一直被人遗忘，直到维琳德在达纳苏斯找到一本讲述这个故事的书，来到这座山谷，亲手将它发掘出来。\n\n随着时间推移，神殿沦为了废墟，一个名叫恐狼的狼人部族占领了它，把洞穴当成了自己的巢穴。它们的嚎叫在岩石间回荡，为这座山谷赢得了如今的名字。",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "伊瑞斯湖",
			short = "伊瑞斯湖位于灰谷的中北部，在阿斯特兰纳以东、沙尔德林的月亮井以西。",
			full = "伊瑞斯湖位于灰谷的中北部，在阿斯特兰纳以东、沙尔德林的月亮井以西。它曾经是完整的暗夜精灵森林的一部分，后来却被从费伍德森林蔓延而来的腐化所吞噬，湖水变成了病态的黄绿色。如今，扭曲的沼泽兽在湖岸出没，攻击任何前来寻找月神之泪的人。",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "卡加希亚要塞",
			short = "卡加希亚要塞耸立在灰谷东部战歌伐木营地的尖刺路障之间，靠近怒水河。",
			full = "卡加希亚要塞耸立在灰谷东部战歌伐木营地的尖刺路障之间，靠近怒水河。它是战歌氏族军官们的驻地，之所以选择这个位置，是为了在联盟大举进攻营地时，能够从奥格瑞玛召来援军。\n\n这座要塞得名于卡加斯·刃拳，这位兽人英雄的名字也被用来命名荒芜之地的卡加斯和杜隆塔尔的刃拳海湾。监工格尔萨克在要塞的城墙内指挥着营地，指挥着对灰谷木材的砍伐。",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "法拉希姆湖",
			short = "法拉希姆湖位于灰谷的西部，无论白天黑夜，女神的月光总会洒在湖面上。暗夜精灵曾经自由自在地来这里游泳和钓鱼，直到鱼人占领了湖泊，让这里变得野蛮凶险。",
			full = "法拉希姆湖位于灰谷的西部，无论白天黑夜，女神的月光总会洒在湖面上。暗夜精灵曾经自由自在地来这里游泳和钓鱼，直到鱼人占领了湖泊，让这里变得野蛮凶险。学者泰洛尼斯最后一次被人看见是在湖岸附近，从此再也没有回来。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "迈斯特拉岗哨",
			short = "一座塔楼和一座孤零零的暗夜精灵大厅静静地矗立在这里，驻守着寥寥几名守卫者，而对灰谷来说最奇怪的是，在这些精灵之中还有两个人类：费罗·艾隆汉和净化者德尔格伦，他们是这座哨站上仅有的人类。",
			full = "一座塔楼和一座孤零零的暗夜精灵大厅静静地矗立在这里，驻守着寥寥几名守卫者，而对灰谷来说最奇怪的是，在这些精灵之中还有两个人类：费罗·艾隆汉和净化者德尔格伦，他们是这座哨站上仅有的人类。\n\n他们的人数很少，因为附近熊怪中不断蔓延的腐化抽走了本可以在这里站岗的人手，让哨站的守卫者们捉襟见肘。",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "密斯特拉湖",
			short = "密斯特拉湖的湖水曾经由忠于暗夜精灵的灵魂守护，它们作为湖泊的守护者被束缚在这里。",
			full = "密斯特拉湖的湖水曾经由忠于暗夜精灵的灵魂守护，它们作为湖泊的守护者被束缚在这里。萨瑞鲁斯·邪生让它们倒戈相向，腐化了这些元素生物，直到它们转而听命于他，而不是它们曾经效力的精灵。如今在湖中等待着的，已经不再是昔日的模样了。",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "夜道谷",
			short = "夜道谷坐落在一片伸入陆地的岬角上，悬崖陡峭得无法攀登，因此旅人必须沿着弗伦河几乎走到萨维亚的水边，然后再转向西方，或者找到林中树居北面那条狭窄的岩架。",
			full = "夜道谷坐落在一片伸入陆地的岬角上，悬崖陡峭得无法攀登，因此旅人必须沿着弗伦河几乎走到萨维亚的水边，然后再转向西方，或者找到林中树居北面那条狭窄的岩架。进去之后也没有什么可看的：只有一些零散的残破石柱和毁坏的石雕，它是灰谷三座萨特要塞中最小也最破败的一座，与萨维亚和萨提纳尔相比都相形见绌。在这些废墟中栖身的邪麝萨特并不需要城墙，因为这片土地本身就在守护着他们。在瓦砾中躺着一颗暗链教派的灵魂宝石，邪麝萨特与这个教派结成了同盟。",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "夜歌森林",
			short = "弗伦河将东部的森林一分为二，它划出的那条线，正是一场永无休止的战争的战线。",
			full = "弗伦河将东部的森林一分为二，它划出的那条线，正是一场永无休止的战争的战线。在河的西岸，银翼哨兵为联盟守卫着这片土地；在河的东边，战歌氏族已经将他们的木桩打进了大地，而在这里，两个民族之间的战斗最为激烈，也最为频繁。\n\n再往东，另一条无名的河流标志着又一条边界。一边矗立着碎木岗哨，那是部落在这片森林中的力量核心；另一边则是为联盟效力的银翼树林。在那条河的另一边，是一片谁也无法长久占据的土地，林歌神殿的暗夜精灵、萨提纳尔和萨维亚的萨特、战歌兽人，以及燃烧军团本身，都各自占据着其中的一部分。从来没有哪一面旗帜能在那里飘扬而不受挑战。\n\n在战场以南，森林为这场战争付出了代价。战歌氏族将这一带砍伐得光秃秃的，砍倒古老的树木来建造他们的定居点，在古老的森林曾经完整地屹立的地方，留下了一片开阔而满目疮痍的土地。",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "林中树居",
			short = "在为这个地方赋予名字的那棵巨树的高枝上，藏着奥达努斯，他是林地的守护者，也是塞纳留斯最年长的儿子之一。",
			full = "在为这个地方赋予名字的那棵巨树的高枝上，藏着奥达努斯，他是林地的守护者，也是塞纳留斯最年长的儿子之一。他来到这里是为了躲避暗影议会，这个议会的爪牙已经将他列为了必杀之人。其中为首的是布蕾琳·火手，她把他的死当作自己唯一的目标，并派出杀手去对付他。奥达努斯在那次刺杀中幸存了下来，至今仍藏在这棵树的高枝之中。\n\n在他的下方，塞纳里奥保护者、闪现龙和欢笑的姐妹在这座前哨中守望，守卫着通往费伍德森林那片枯萎之地的北方小路。",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "奥迪拉兰废墟",
			short = "奥迪拉兰如今只剩下一些残破的石头。暗链教派曾经将这片废墟据为己有，随时准备扑向任何靠得太近的人。",
			full = "奥迪拉兰如今只剩下一些残破的石头。暗链教派曾经将这片废墟据为己有，随时准备扑向任何靠得太近的人。这一切以流血告终：蓟皮熊怪将他们赶了出去，将这片废墟据为己有，而邪教徒的尸体至今仍散落在他们倒下的地方。\n\n在这片残骸之中矗立着同心树，它扎根于一座曾经颇有名望和地位的城市之中。那座城市已经没有任何其他东西留存下来，能说出它曾经是什么样子了。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "星尘废墟",
			short = "星尘废墟位于一座湖心岛上，它曾经沉浸在神圣之中，如今却沉浸在腐朽之中。从费伍德森林渗透下来的恶魔污秽已经渗入了湖水和岩石，将这座岛屿染成了病态的黄绿色。",
			full = "星尘废墟位于一座湖心岛上，它曾经沉浸在神圣之中，如今却沉浸在腐朽之中。从费伍德森林渗透下来的恶魔污秽已经渗入了湖水和岩石，将这座岛屿染成了病态的黄绿色。如今，被毒湖扭曲的沼泽兽拖着身躯在废墟中穿行。\n\n然而星尘灌木依然生长在那里，未被周围的腐化所触及。据说它们的叶子具有治愈的功效，这是这片废墟中唯一仍然与这个地方在腐朽来临之前应有的模样相似的部分。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "萨提纳尔",
			short = "萨提纳尔残破地矗立在灰谷东北部的树林之间，它的建筑早已沦为废墟，不过冷心萨特如今在废墟间搭起了帐篷，在这里安了家。",
			full = "萨提纳尔残破地矗立在灰谷东北部的树林之间，它的建筑早已沦为废墟，不过冷心萨特如今在废墟间搭起了帐篷，在这里安了家。在这片森林的三座萨特要塞中，只有萨提纳尔基本保持完整，而它位于从碎木岗哨通往艾萨拉的道路旁，这使它成了三者中最容易到达、也最常被争夺的一座。\n\n冷心萨特在这里拥有的不仅仅是栖身之所。萨提纳尔中存放着一颗暗链教派的灵魂宝石，这是将萨特与那个教派的黑暗目的联结在一起的盟约的信物。",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "林荫小径",
			short = "林荫小径位于林中树居以南、绿爪村以东，是一道静静地嵌在灰谷之中的小山谷。",
			full = "林荫小径位于林中树居以南、绿爪村以东，是一道静静地嵌在灰谷之中的小山谷。一个洞穴开在它的山坡上，里面住着一小家子熊，它们在树林和阴影中与世无争。",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
