		["shrine of aessina"] = {
			name = "艾森娜神殿",
			short = "艾森娜神殿坐落在灰谷的西南部，隐藏在迈斯特拉岗哨和阿斯特兰纳之间。",
			full = "艾森娜神殿坐落在灰谷的西南部，隐藏在迈斯特拉岗哨和阿斯特兰纳之间。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
