		["silverwind refuge"] = {
			name = "银风避难所",
			short = "银风避难所属于暗夜精灵，由哨兵和与她们一同效力的水元素守护着。",
			full = "银风避难所属于暗夜精灵，由哨兵和与她们一同效力的水元素守护着。它与阿斯特兰纳一起，是灰谷的主要前哨之一，而它的名声也是实至名归：这是一个热情好客的地方，它的旅店被认为是这一地区比较舒适的旅店之一。",
