		["silverwing grove"] = {
			name = "银翼树林",
			short = "银翼树林位于灰谷的中南部，是一片由银翼哨兵把守的树林，位于她们的哨站西南方、坠星湖以西。",
			full = "银翼树林位于灰谷的中南部，是一片由银翼哨兵把守的树林，位于她们的哨站西南方、坠星湖以西。哨兵轻歌与那些誓言保卫这片树林的人们一同在这里守望。",
