		["silverwing outpost"] = {
			name = "银翼哨站",
			short = "银翼哨站坐落在弗伦河错误的一侧，深入碎木岗哨的兽人一心想要清除的地域。",
			full = "银翼哨站坐落在弗伦河错误的一侧，深入碎木岗哨的兽人一心想要清除的地域。杜里尔·月火指挥着这里，而在这里指挥就意味着无休止的战争：兽人发动袭击不是为了掠夺，而是要抹掉这座哨站，将每一名哨兵永远赶出这片森林。",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "怒水河",
			short = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。",
			full = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。从那里开始，它奔流得又宽又急，将大地一分为二：它标志着灰谷与艾萨拉的分界，再往南，又是贫瘠之地的尽头和杜隆塔尔的起点。在入海口，河水从最后一道瀑布上奔腾而下，注入无尽之海，那里就在地精港口棘齿城的东北方。\n\n河上架着几座桥，一座连接艾萨拉与灰谷，另一座连接杜隆塔尔与贫瘠之地。就在最西边那座桥的北面，有一段水域同时触及四片土地，那是灰谷、艾萨拉、杜隆塔尔和贫瘠之地唯一的交汇之处。\n\n这条河依然滋养着两岸的田地，依然让它流经之处的土壤一片青翠。但它的水已经不能再喝了。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "碎木岗哨",
			short = "碎木岗哨的木料上至今仍留着建造它时斧头劈砍的痕迹，因为正是格罗玛什·地狱咆哮和他的战歌氏族，在第三次战争中兽人第一次挺进灰谷时建造了这座前哨，他们砍倒古老的树木来开辟道路、修建营地。",
			full = "碎木岗哨的木料上至今仍留着建造它时斧头劈砍的痕迹，因为正是格罗玛什·地狱咆哮和他的战歌氏族，在第三次战争中兽人第一次挺进灰谷时建造了这座前哨，他们砍倒古老的树木来开辟道路、修建营地。\n\n暗夜精灵从未与战歌氏族对他们的森林所做的一切达成和解，这些旧伤在部落与联盟之间紧张的停战协定之下隐隐作痛。因此，碎木岗哨比这片森林中的大多数前哨招来了更多的报复，双方对附近阿斯特兰纳的袭击都十分频繁。\n\n如今留下来的是一支驻军，而不是一个定居点：兽人和牛头人在这里担任斥候和守卫，监视着林线，提防着他们早已习以为常的袭击者。",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "石爪小径",
			short = "石爪小径是一条连接灰谷与石爪山脉的蜿蜒隧道，通道崎岖不平，岩石中磨出了许多小小的死胡同和奇怪的凹洞。",
			full = "石爪小径是一条连接灰谷与石爪山脉的蜿蜒隧道，通道崎岖不平，岩石中磨出了许多小小的死胡同和奇怪的凹洞。它的一端开在密斯特拉湖以西，另一端开在狂风峭壁的西北部。那里没有任何东西居住；它只是一条穿越群山的通道。",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "蓟皮村",
			short = "蓟皮村位于灰谷的中西部，在阿斯特兰纳以北。这里是蓟皮部族的家园，这些熊怪已经变得腐化而充满敌意，会攻击任何靠近的人。",
			full = "蓟皮村位于灰谷的中西部，在阿斯特兰纳以北。这里是蓟皮部族的家园，这些熊怪已经变得腐化而充满敌意，会攻击任何靠近的人。两名凶猛的战士，达尔·血爪和罗吉什·大颚，率领着这个部族，守卫着村庄，抵御一切来犯者。",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "战歌劳工营地",
			short = "在灰谷的东南部、坠星湖以东，战歌氏族设有一座劳工营地，伐木工和采集者在兽人的看守下劳作，为氏族的领地砍伐木材。",
			full = "在灰谷的东南部、坠星湖以东，战歌氏族设有一座劳工营地，伐木工和采集者在兽人的看守下劳作，为氏族的领地砍伐木材。\n\n这座营地远离战歌氏族的主力，它的守卫孤立无援，得不到任何增援的希望。",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "战歌伐木营地",
			short = "在战歌伐木营地，灰谷的森林中回荡着斧头的砍伐声，战歌氏族在这里将古老的树木砍伐殆尽，获取木材。",
			full = "在战歌伐木营地，灰谷的森林中回荡着斧头的砍伐声，战歌氏族在这里将古老的树木砍伐殆尽，获取木材。营地的支柱是一座战兽的兽栏和卡加希亚要塞，那是一座为守护伐木而建的要塞。\n\n这个氏族对木材的渴求并非没有遭到回击。艾蒂尔和她的姐妹们进入了这里的森林，用自然魔法对付那些啃噬树干的伐木机，堆叠的原木之间的土地已经成了联盟与部落之间的战场。\n\n即便如此，这座营地依然发挥着它的作用：源源不断的木材从这里运往碎木岗哨，那里的城墙和人们都依赖着战歌伐木营地送来的东西。",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "萨维亚",
			short = "萨维亚耸立在一座暗夜精灵神殿的旧址上，它的石头如今已归萨特所有。",
			full = "萨维亚耸立在一座暗夜精灵神殿的旧址上，它的石头如今已归萨特所有。在灰谷的三座萨特要塞中，力量正是在这里汇聚：雷兹王子和盖尔萨里斯都在这片废墟中坐镇，而萨特们也正是在这里将偷来的战歌油用于他们的仪式。\n\n这个地方得名于萨维斯，很久以前，他曾帮助燃烧军团经由一道从辛艾萨莉的永恒之井中汲取力量的传送门打开通道。萨格拉斯对那项工作进展之缓慢十分不满，于是将萨维斯扭曲成了第一个萨特。萨维亚离艾萨拉如此之近，这个名字看来绝非偶然。\n\n树妖们曾经向萨维亚发起过进攻，其中一位名叫阿妮莉亚的树妖在寻找被萨特夺走的一根塞纳留斯的树枝之后，被人发现在这里身受致命重伤，倒在她无法肃清的废墟之间。",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "佐拉姆海岸",
			short = "佐拉姆海岸沿岸的海浪，拍打着曾经是一座城市的地方。",
			full = "佐拉姆海岸沿岸的海浪，拍打着曾经是一座城市的地方。在世界于大分裂中被撕裂之前，佐拉姆作为一座暗夜精灵城镇矗立在这里，当大海涌起、要从破碎的世界中夺走它的那一份时，佐拉姆也随之沉入了海底。如今水面上除了这个名字之外，什么也没有留下。\n\n如今在海岸上行走的不是精灵，而是纳迦。他们将这片海岸据为己有，散落在沙滩上的残骸，那些破碎的船只和搁浅的海洋生物的尸体，都标志着这片海岸已经彻底落入了他们的手中。在附近的岩石和被淹没的洞穴之间，坐落着黑暗深渊，它沉入了地下，就像佐拉姆曾经沉入大海一样。\n\n部落在这里的佐拉姆加前哨站占据着一个小小的立足点，与其说是出于选择，不如说是迫不得已，他们为了与争夺海岸每一寸土地的怒尾纳迦作战而耗尽了力量。同样是这些纳迦袭击了塔尔伦，让这座前哨站陷入了多面受敌的境地。这是一段艰苦、潮湿、争夺不休的海岸，曾被一个已经沉没的帝国所占据，如今则被诞生于那片吞没了它的大海中的生物所占据。",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "佐拉姆加前哨站",
			short = "佐拉姆加前哨站是部落在灰谷佐拉姆海岸上的一座港口，它的码头一直伸向下方的水面。",
			full = "佐拉姆加前哨站是部落在灰谷佐拉姆海岸上的一座港口，它的码头一直伸向下方的水面。",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- 千针石林: 20 subzones
	[1441] = {
		["camp ethok"] = {
