		["darkcloud pinnacle"] = {
			name = "黑云峰",
			short = "黑云峰耸立在升降梯以东的三座小台地上，台地的顶端由悬在半空中的绳桥连接在一起。",
			full = "黑云峰耸立在升降梯以东的三座小台地上，台地的顶端由悬在半空中的绳桥连接在一起。只有两条路可以上去，每一条都有重兵把守：一条是横跨第四座台地的天然斜坡，另一条是从剃刀高地伸过来的一座桥。\n\n恐怖图腾牛头人占据着这些高地，由阿纳克·恐怖图腾和哈布·邪山率领。在戒备森严的桥梁后面，这两位首领与某个身份不明的黑暗势力秘密通信。他们之间往来的内容从不公开谈论，但为封锁这些台地所采取的谨慎措施，足以说明这个秘密被守护得有多么严密。",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "乱风岗",
			short = "乱风岗高高地坐落在千针石林的一座台地上，远离在下方游荡的半人马。",
			full = "乱风岗高高地坐落在千针石林的一座台地上，远离在下方游荡的半人马。木制的升降梯将这里的人们从峡谷底部送上来，绳桥在相邻的石峰之间架起，一座峰接着一座峰地向上攀升，直到抵达村庄。在下方，加拉克半人马不断派出他们的战斗部队，鹰身人在平地上空盘旋尖叫，但高度本身才是这座岗哨真正的防御。\n\n更深层的麻烦来自西北方的黑云峰，恐怖图腾部族在那里占据着他们自己的高地。早在公开的战争爆发之前，乱风岗就对他们心存戒备：牛头人接连失踪，有人看到来历不明的黑暗使者拜访那座山峰，谋杀的罪名也被归到了恐怖图腾部族的头上。酋长阿纳克·恐怖图腾承担了最大的罪责。当乱风岗的拉科塔·风歌拒绝了他的求爱时，他派人强行掳走了她，而当她的兄弟前来保护她时，恐怖图腾部族杀死了他。",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
