		["rustmaul dig site"] = {
			name = "锈锤挖掘场",
			short = "锈锤挖掘场位于闪光平原，它的壕沟被挖到一半就被搁置了。探险者协会来到这里是为了发掘古老的遗迹，他们在一个洞穴的阴影下挖掘土地，而那个洞穴里藏着一窝异种虫。",
			full = "锈锤挖掘场位于闪光平原，它的壕沟被挖到一半就被搁置了。探险者协会来到这里是为了发掘古老的遗迹，他们在一个洞穴的阴影下挖掘土地，而那个洞穴里藏着一窝异种虫。\n\n挖掘工作还没完成就停止了。壕沟空荡荡地敞开着，矮人们的工具被遗弃在原地，而挖掘场下方的洞穴至今仍是那些异种虫的栖身之所。",
