			name = "玛诺洛克集会所",
			short = "在凄凉之地上那些破碎的暗夜精灵废墟之中，有一个地方的名字是任何旅人都不敢轻易提起的。",
			full = "在凄凉之地上那些破碎的暗夜精灵废墟之中，有一个地方的名字是任何旅人都不敢轻易提起的。玛诺洛克集会所得名于可怕的深渊领主玛诺洛斯，而这里的土地也记得他。早在恶魔到来之前，这片土地就已经死去，但邪能魔法又进一步摧残了它，直到空气中弥漫着浓厚的腐化气息，一层致命的阴霾笼罩着任何踏入其中的人。\n\n火刃邪教徒打开了通道，他们在世间撕开了许多传送门，通过它们召唤燃烧军团的仆从：地狱火、魅魔、地狱犬和恶魔卫士，如今它们在废墟中四处游荡。阿兹雷索克领主指挥着这些恶魔，而兽人术士加克尔·恐棒则站在它们之中，作为火刃氏族在集会所中的代言人。他们共同在这里建立起了卡利姆多中部规模最大的恶魔集会，这证明邪教徒的阴谋所取得的成功远远不只是一个警告。",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "尼耶尔前哨站",
			short = "尼耶尔前哨站守望在凄凉之地北部的群山之中，是一座由联盟和塞纳里奥议会共同据守的前哨。",
			full = "尼耶尔前哨站守望在凄凉之地北部的群山之中，是一座由联盟和塞纳里奥议会共同据守的前哨。\n\n守护者玛兰迪斯和他的树妖姐妹们来到这里，把这座前哨当作他们追捕瑟莱德丝公主的基地。他们的目的，是从玛拉顿的深处取回扎尔塔的遗体，并把它带回石爪山脉的故乡。\n\n与此同时，暴风城军队在本迪加斯上尉的指挥下，将尼耶尔前哨站卫兵驻扎在这里，以对抗占据这一地区的半人马部族的威胁。本迪加斯以军人的警觉注视着吉尔吉斯部族和玛格拉姆部族之间的争斗，他确信无论哪个部族最终获胜，都会变得胆大妄为，转而攻击附近的联盟据点，因此他试图通过权衡两个部族之间的关系，来找出击败半人马的办法。",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "拉纳加尔岛",
			short = "拉纳加尔岛是凄凉之地西北海岸外的一座岩石嶙峋的小岛，是蛇形纳迦的家园。",
			full = "拉纳加尔岛是凄凉之地西北海岸外的一座岩石嶙峋的小岛，是蛇形纳迦的家园。在石头之间矗立着暗夜精灵的遗迹，它们与艾瑟雷索同属一座古老的城市，如今静静地矗立在居住于此的纳迦之上。",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "萨格隆",
			short = "矗立在这里的城市曾经有一个暗夜精灵的名字，但自从上古战争撕裂世界以来，那个名字便已失传。",
			full = "矗立在这里的城市曾经有一个暗夜精灵的名字，但自从上古战争撕裂世界以来，那个名字便已失传。留下来的只有废墟，如今住在那里的仇怒萨特为了纪念他们的恶魔主人萨格拉斯，称它为萨格隆。\n\n这片废墟中曾有三处艾露恩的圣地：她的大教堂、她的神殿和她的圣所。那个更古老信仰的遗物至今仍躺在石头之间：艾露恩的火盆、她的侍女、她的圣杯，以及远古漩涡符文石。",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "萨瑟里斯海岸",
			short = "凄凉之地与大海相接的海岸，与它身后的土地截然不同。内陆一片灰暗荒凉，而萨瑟里斯海岸却阳光明媚，青草翠绿。",
			full = "凄凉之地与大海相接的海岸，与它身后的土地截然不同。内陆一片灰暗荒凉，而萨瑟里斯海岸却阳光明媚，青草翠绿。海巨人在它的浅滩中涉水而行，纳迦在它的水中盘绕游动，螯虾人则在它的沙滩上横行。\n\n在艾瑟雷索的下方，一条小船撞碎在海滩上，船板碎裂，船上的船员也早已不知去向。",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "瑟卡布斯库的营地",
			short = "在凄凉之地的科多兽坟场附近，矗立着一座小小的地精营地。",
			full = "在凄凉之地的科多兽坟场附近，矗立着一座小小的地精营地。它属于斯米德·瑟卡布斯库，一个富有进取心的地精，他经营着一支科多兽商队，驱赶着这些巨兽穿越荒原，尽可能地从这片土地上获取利润。",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "破影峡谷",
			short = "破影峡谷隐藏在肖克索卡东南方的群山之中，是凄凉之地的一处褶皱，很少有人会偶然撞见。",
			full = "破影峡谷隐藏在肖克索卡东南方的群山之中，是凄凉之地的一处褶皱，很少有人会偶然撞见。巨大的蘑菇在它的岩石间耸立，在它的中心有一个被巨大的锁链束缚着的召唤法阵，那是把这道峡谷当作藏身之所的火刃邪教徒建造的。",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "葬影村",
			short = "葬影村坐落在萨瑟里斯海岸与凄凉之地南部海岸的交汇处，是巨魔的一座渔村。",
			full = "葬影村坐落在萨瑟里斯海岸与凄凉之地南部海岸的交汇处，是巨魔的一座渔村。村民们以海为生，正是他们捕获的鱼养活了更远的内陆的幽灵岗哨。",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "塔迪萨兰",
			short = "暗夜精灵的废墟零星散布在凄凉之地北部，位于雷斧堡垒以北，那是一个被认为在大分裂中毁灭的定居点的遗迹。",
			full = "暗夜精灵的废墟零星散布在凄凉之地北部，位于雷斧堡垒以北，那是一个被认为在大分裂中毁灭的定居点的遗迹。这里没有任何东西被重建。如今只有凄凉之地的野生生物在破碎的石头之间走动。",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "雷斧堡垒",
			short = "雷斧堡垒矗立在凄凉之地的西北部，已被火刃邪教所占据。",
			full = "雷斧堡垒矗立在凄凉之地的西北部，已被火刃邪教所占据。在由要塞、兵营、洞穴和瞭望塔构成的围墙之后，科霍尔手下的邪教徒正致力于召唤出拥有全部力量的恶魔纳萨尔根，他们小心翼翼，生怕召唤得太早，那时他会弱小到足以被消灭。\n\n这座堡垒曾经存放着圣光节杖，这是一件拥有可怕力量的神器，是火刃邪教从纳迦那里偷来的。为银色黎明效力的阿佐尔·奥达蒙特立志要夺回它，并在他人的帮助下成功地从邪教手中将它夺了回来。\n\n提拉尼斯·玛勒姆也曾住在这些围墙之内，他的族人提起这个名字时都充满了鄙夷，因为他背叛了他们，投身于恶魔魔法的研究，并把雷斧堡垒当作他进行这些黑暗研究的避难所。",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "白骨之谷",
			short = "白骨之谷是凄凉之地南缘的一处峭壁，骷髅、半人马死灵法师以及被屠杀的玛格拉姆部族的鬼魂在这里出没。",
			full = "白骨之谷是凄凉之地南缘的一处峭壁，骷髅、半人马死灵法师以及被屠杀的玛格拉姆部族的鬼魂在这里出没。在崖壁旁躺着一对巨大的骸骨，那是死去的巨人，它们的来历不明。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "长矛谷",
			short = "长矛谷位于凄凉之地的西部，是玛拉丁半人马部族的家园，只有通过南面和东面狭窄的山口才能步行抵达。",
			full = "长矛谷位于凄凉之地的西部，是玛拉丁半人马部族的家园，只有通过南面和东面狭窄的山口才能步行抵达。在它的西南端是玛拉顿的入口。在半人马之中，梅丽萨被囚禁着。",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- 菲拉斯: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "莫沙彻营地",
			short = "莫沙彻营地坐落在一条湍急的溪流注入狂风湖的地方。",
			full = "莫沙彻营地坐落在一条湍急的溪流注入狂风湖的地方。占据这片土地的牛头人以他们坚韧的皮肤和勇士们的勇气而闻名，这些勇士保护着旅人免遭菲拉斯的种种危险。",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "厄运之槌",
			short = "一万两千年前，一个隐秘的暗夜精灵巫师教派建造了埃尔德拉斯，以守护艾萨拉女王最珍贵的奥术秘密。",
			full = "一万两千年前，一个隐秘的暗夜精灵巫师教派建造了埃尔德拉斯，以守护艾萨拉女王最珍贵的奥术秘密。在城中的上层精灵之中，被称为辛德拉的奥术师们过着安静而辉煌的生活，其中一位名叫米莉森特·塞伦的奥术师培育出了丰饶之果，这是一种藤蔓，它那促进生长和提供庇护的光环让整座城市繁荣昌盛。\n\n大分裂之后，上层精灵与永恒之井失去了联系，于是他们束缚了一个名叫伊莫塔尔的恶魔，从对他的囚禁中汲取力量。这维持了他们数千年的生存，直到囚禁他的代价超过了他所提供的一切。他们的领袖托塞德林王子对此的回应，是转而对付他自己的人民，屠杀了其中的许多人，以释放出足够的力量让其余的人活下去。幸存者们退到了他们曾经统治的废墟的更深处，把城市的其余部分留给了任何将来到这里居住的东西。\n\n埃尔德拉斯的石头至今仍然屹立，奥术能量被一种如今已无人记得的技艺束缚在其中，维持着一座以吞噬自己的人民为代价而存活下来的城市的形状。",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "梦境之树",
			short = "一棵巨树从加德米尔湖中央的一座小岛上拔地而起，它的根和枝干承载着一座通往翡翠梦境的传送门。",
			full = "一棵巨树从加德米尔湖中央的一座小岛上拔地而起，它的根和枝干承载着一座通往翡翠梦境的传送门。绿龙军团守望着它，守护着这道门槛，阻止任何企图干扰下方梦境的人。",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "羽月要塞",
			short = "在菲拉斯西海岸外的萨尔多岛上，矗立着一座由珊蒂斯·羽月将军在海上建起的要塞，一万年来，她一直陪伴在泰兰德·语风的身边，是她在哨兵中的得力助手。",
			full = "在菲拉斯西海岸外的萨尔多岛上，矗立着一座由珊蒂斯·羽月将军在海上建起的要塞，一万年来，她一直陪伴在泰兰德·语风的身边，是她在哨兵中的得力助手。她以自己的名字为这座要塞命名，它至今仍为暗夜精灵守卫着卡利姆多的这段海岸。\n\n只有大海将它与大陆相连，那是一条从被遗忘的海岸驶往岛上码头的航线。",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "深痕谷",
			short = "在菲拉斯西部的高原荒野中，坐落着深痕谷，占据这里的深痕雪人为它赋予了名字。",
			full = "在菲拉斯西部的高原荒野中，坐落着深痕谷，占据这里的深痕雪人为它赋予了名字。",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "被遗忘的海岸",
			short = "被遗忘的海岸贯穿菲拉斯的整个西部边缘，那里是陆地与迷雾之海相接的地方。水元素从这里的浪花中升起，海巨人在海岸线上潜行。",
			full = "被遗忘的海岸贯穿菲拉斯的整个西部边缘，那里是陆地与迷雾之海相接的地方。水元素从这里的浪花中升起，海巨人在海岸线上潜行。\n\n一座鱼人渔村紧紧依附在这片海岸上。鸟儿常常俯冲下来叼走蝌蚪，这座村庄还先后遭到过人类和豺狼人的袭击。最可怕的是戈杜尼食人魔，他们多年来一直在掠夺这座村庄，把鱼人拖进厄运之槌的废墟中囚禁起来。已经有十几只鱼人以这种方式被掳走，其中有两只名叫莫尔和莫格里。",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "乱羽高地",
			short = "乱羽高地属于乱羽角鹰兽，它们在那里的高处筑巢，并为这片土地赋予了名字。",
			full = "乱羽高地属于乱羽角鹰兽，它们在那里的高处筑巢，并为这片土地赋予了名字。在峭壁之间，它们的蛋藏在零散的巢穴里，由那些以高地为家、在空中盘旋的鸟群守护着。",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "戈杜尼前哨站",
			short = "在拉瑞斯小亭以北的山中，大地上带着戈杜尼的印记。菲拉斯的其他地方都是一片青翠，而这座前哨站却在食人魔的盘踞下枯萎发黄。",
			full = "在拉瑞斯小亭以北的山中，大地上带着戈杜尼的印记。菲拉斯的其他地方都是一片青翠，而这座前哨站却在食人魔的盘踞下枯萎发黄。\n\n两个洞穴标志着这片山丘，一个小洞穴靠近入口，后面还有一座巨大的土丘，两者都被占据这片枯萎土地的戈杜尼食人魔所把守。",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "恐怖图腾营地",
			short = "恐怖图腾营地位于厄运之槌以东，是恐怖图腾牛头人为自己建立的家园。在它的南部矗立着一个大笼子，里面关着被俘的精灵龙。",
			full = "恐怖图腾营地位于厄运之槌以东，是恐怖图腾牛头人为自己建立的家园。在它的南部矗立着一个大笼子，里面关着被俘的精灵龙。在北部的东边，豺狼人建起了它们自己的营地。",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "高原荒野",
			short = "高原荒野横亘在菲拉斯的西部，从被遗忘的海岸一直延伸到沃丹提斯河。",
			full = "高原荒野横亘在菲拉斯的西部，从被遗忘的海岸一直延伸到沃丹提斯河。熊、狼和角鹰兽在它古老的树林间游荡，树人矗立在更深的林地之中，而雪人和食人魔则占据着更远处更加荒野的地带。",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "恐怖之岛",
			short = "恐怖之岛位于菲拉斯的海岸外，在萨尔多岛以南，它中央的山谷四面都被坚不可摧的悬崖环绕，只有东南方的一条路可以进入。",
			full = "恐怖之岛位于菲拉斯的海岸外，在萨尔多岛以南，它中央的山谷四面都被坚不可摧的悬崖环绕，只有东南方的一条路可以进入。在那个隐秘的盆地中，奇美拉安了家，其中有被奥术之力浸染的野兽，也有吞噬者，由拉克迈兰领主统治着。人们寻求他的血肉，所为的目的比求生还要奇怪：它被熬炼重塑，变成了一只重达五百磅的巨大禽类，被侏儒巫师纳瑞安整个吞了下去。\n\n在岛的北端，一个洞穴深陷于岩石之中，与那里已知的任何东西都不一样，幽深而构造奇特。一条水下的秘密通道通向一间内室，除了在深处庇护萨拉女士之外，没有人发现它还有什么别的用途。这个洞穴和其中的纳迦由沙尔扎鲁领主统率，他的存在引起了羽月要塞的注意，她们对离自己的海岸如此之近的纳迦保持着警惕。",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "加德米尔湖",
			short = "加德米尔湖位于菲拉斯北部，湖中央有一座名为梦境之树的小岛。那里矗立着一座通往翡翠梦境的传送门，由莱索斯和一些绿色龙人守卫着。",
			full = "加德米尔湖位于菲拉斯北部，湖中央有一座名为梦境之树的小岛。那里矗立着一座通往翡翠梦境的传送门，由莱索斯和一些绿色龙人守卫着。受感染的绿色雏龙在湖的西北岸徘徊。",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "拉瑞斯小亭",
			short = "拉瑞斯小亭的石雕是暗夜精灵风格的，它位于菲拉斯莫沙彻营地以北。这里的树妖曾经爱好和平，但翡翠梦魇腐化了她们，如今她们会攻击任何靠近的人。",
			full = "拉瑞斯小亭的石雕是暗夜精灵风格的，它位于菲拉斯莫沙彻营地以北。这里的树妖曾经爱好和平，但翡翠梦魇腐化了她们，如今她们会攻击任何靠近的人。\n\n在小亭下方有一条隐秘的通道，上层精灵埃斯托尔迪知道这条通道，他与托塞德林王子决裂，并经由这条通道逃离了厄运之槌。他逃走时几乎什么也没带出来，因为一个名叫普希林的小鬼在他消失到地下之前偷走了他的咒语书，从那以后，他就一直待在那条通道里。",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
