		["thalanaar"] = {
			name = "萨兰纳尔",
			short = "萨兰纳尔静静地矗立着，这是一座小小的前哨，除了它的职责之外，几乎没有什么能吸引旅人。",
			full = "萨兰纳尔静静地矗立着，这是一座小小的前哨，除了它的职责之外，几乎没有什么能吸引旅人。凯雷希亚·猎月在这里施展她的手艺，用古老的部族方法加工兽皮和皮革，这也是少数几个让人有理由在此逗留的原因之一。",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
