		["twin colossals"] = {
			name = "双塔山",
			short = "双塔山耸立在菲拉斯的西部边缘，这两座陡直的山峰高耸入云，是这一地区的最高点，通往凄凉之地的道路就从它们之间的缝隙中穿过。",
			full = "双塔山耸立在菲拉斯的西部边缘，这两座陡直的山峰高耸入云，是这一地区的最高点，通往凄凉之地的道路就从它们之间的缝隙中穿过。\n\n在东峰的顶上有一个又小又深的池塘，池水平静得足以垂钓，格雷甘·山酒就在那里。从山顶望去，整个地区都在脚下铺展开来。",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "沃丹提斯河",
			short = "沃丹提斯河蜿蜒流过菲拉斯的中部，位于厄运之槌废墟的东南方，在纠缠交错的森林中划出一道静谧的绿线。",
			full = "沃丹提斯河蜿蜒流过菲拉斯的中部，位于厄运之槌废墟的东南方，在纠缠交错的森林中划出一道静谧的绿线。它的水中生活着菲拉斯金枪鱼，这种鱼在世上别处都找不到。",
