		["woodpaw den"] = {
			name = "木爪巢穴",
			short = "在菲拉斯的中心坐落着木爪巢穴，那是木爪豺狼人的巢穴。木爪首领们在这里统治着它们的同族，它们密密麻麻地聚集在地面上，数量之多，很少有外人愿意去试探。",
			full = "在菲拉斯的中心坐落着木爪巢穴，那是木爪豺狼人的巢穴。木爪首领们在这里统治着它们的同族，它们密密麻麻地聚集在地面上，数量之多，很少有外人愿意去试探。巢穴的南面矗立着黑雾废墟，与豺狼人的喧闹为邻，却始终寂静无声。",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "木爪岭",
			short = "木爪岭林木茂密，是木爪部族豺狼人的家园。",
			full = "木爪岭林木茂密，是木爪部族豺狼人的家园。它们对这片土地的控制正在减弱，因为在最东南的地带，大地裂开，形成了如今被称为痛苦深渊的地方，从地下涌出来的成群结队的东西一直在把豺狼人赶出它们自己的领地。木爪首领们曾经在各处营地中领导着它们的部族，如今却只能固守在木爪巢穴之中。",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "痛苦深渊",
			short = "痛苦深渊位于菲拉斯的东南部，已被祖卡什虫巢所占据。那里的异种虫毒害了它们周围的土地，把附近的豺狼人逼得发狂，向北攻击莫沙彻营地。",
			full = "痛苦深渊位于菲拉斯的东南部，已被祖卡什虫巢所占据。那里的异种虫毒害了它们周围的土地，把附近的豺狼人逼得发狂，向北攻击莫沙彻营地。\n\n营地的战士们消灭了地面上的异种虫，但虫巢位于地下的核心、那个满是虫卵的地方，却从未被触及。雷克萨警告说，下一代孵化出来只是时间问题。",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
