	-- 尘泥沼泽: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "奥卡兹岛",
			short = "奥卡兹岛从尘泥沼泽外的海中升起，岛上满是热带的葱绿，本不该生长在离沼泽的灰色泥浆如此之近的地方，仿佛某种更古老、更温暖的力量曾经占据过这片土地，并且从未放手。",
			full = "奥卡兹岛从尘泥沼泽外的海中升起，岛上满是热带的葱绿，本不该生长在离沼泽的灰色泥浆如此之近的地方，仿佛某种更古老、更温暖的力量曾经占据过这片土地，并且从未放手。斯特拉沙兹纳迦占据着这座岛屿，岸边遍布着纳迦侍从和海妖。\n\n然而在对安其拉的战争期间，维维尔博士乘坐飞行器来到这座岛上，带着他的爪牙在山顶定居下来，把一段海岸变成了一座科技发明的工坊。",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "比吉尔的飞艇残骸",
			short = "一艘载着补给向南飞行的地精飞艇坠毁在尘泥沼泽的最深处，位于塔贝萨的农场以东。",
			full = "一艘载着补给向南飞行的地精飞艇坠毁在尘泥沼泽的最深处，位于塔贝萨的农场以东。它的船体破碎地躺在泥浆中，货物散落在残骸之间，爆破助推器至今仍躺在它们掉落的地方。",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "鲜血沼泽墓穴",
			short = "尘泥沼泽西南部的一个洞穴里栖息着数量异常多的鲜血沼泽迅猛龙。在入口外躺着某个定居点的遗迹，它被这些生物撕得粉碎，那里的人们如今已经消失在沼泽的泥浆之中。",
			full = "尘泥沼泽西南部的一个洞穴里栖息着数量异常多的鲜血沼泽迅猛龙。在入口外躺着某个定居点的遗迹，它被这些生物撕得粉碎，那里的人们如今已经消失在沼泽的泥浆之中。在洞穴里的某处，科泰罗的谜题的一部分正在残骸之间等待着。",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "蓝色沼泽",
			short = "蓝色沼泽位于尘泥沼泽的北部，低洼的地面上满是芦苇和积水。",
			full = "蓝色沼泽位于尘泥沼泽的北部，低洼的地面上满是芦苇和积水。蜘蛛、鳄鱼、迅猛龙和沼泽鸟类在沼泽中不受约束地穿行，而塞拉摩渗透者则在芦苇丛中悄无声息地从这里经过。",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "蕨墙村",
			short = "蕨墙村坐落在尘泥沼泽西北部的棚屋和食人魔土丘之间，是石槌食人魔的家园，他们宣誓效忠于部落。",
			full = "蕨墙村坐落在尘泥沼泽西北部的棚屋和食人魔土丘之间，是石槌食人魔的家园，他们宣誓效忠于部落。这里并不一直是他们的家。石槌部族曾经在南方拥有一座村庄，直到黑龙军团扑向那里，将它烧成了废墟。继雷克萨之后担任首领的莫克莫洛克督军带领幸存者向北迁移，在这里建起了蕨墙村，取代了旧的村庄。\n\n莫克莫洛克的统治建立在按兵不动的基础之上。当食人魔德拉兹·齐尔布得知那些袭击者是奥妮克希亚的子嗣，并把真相告诉他时，莫克莫洛克却不肯采取行动。蕨墙村是安全的，这里没有黑龙居住，这对他来说就足够了。德拉兹·齐尔布却不肯就此罢休，他暗中盘算着，要怎样才能让督军下台，带领石槌部族夺回他们失去的一切。",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "黑雾洞穴",
			short = "在尘泥沼泽的西北部有一座小矿洞，早已被在黑暗中长得大得吓人的蜘蛛所占据。",
			full = "在尘泥沼泽的西北部有一座小矿洞，早已被在黑暗中长得大得吓人的蜘蛛所占据。沼泽里的人们称它们为黑雾蜘蛛，并因此把这个洞穴称为黑雾洞穴，不过谁也说不清哪个名字在先，是这个地方，还是占据了它的这些生物。\n\n在矿洞口外矗立着一些小房子的废墟，它们半陷在潮湿的土地中，是某个早已被遗忘的定居点仅存的遗迹。",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "火焰洞穴",
			short = "火焰洞穴是石槌食人魔建造的土丘，它的石雕至今仍带着他们的手艺。它位于石槌废墟以西，在被奥妮克希亚占据的沼泽地之中。",
			full = "火焰洞穴是石槌食人魔建造的土丘，它的石雕至今仍带着他们的手艺。它位于石槌废墟以西，在被奥妮克希亚占据的沼泽地之中。\n\n食人魔如今已经离开了这里。黑色龙类占领了这个洞穴，把它当作黑龙军团的巢穴。只有古老的石雕和留在里面的石槌旗帜，还能让人想起它最初的建造者。",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "黑龙谷",
			short = "在尘泥沼泽的南部，有一片被称为黑龙谷的恶臭之地，到处都是黑龙军团的雏龙和龙人。",
			full = "在尘泥沼泽的南部，有一片被称为黑龙谷的恶臭之地，到处都是黑龙军团的雏龙和龙人。附近矗立着火焰洞穴和石槌废墟，两者同样被黑色龙人占据着。",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
