		["dreadmurk shore"] = {
			name = "恐惧海岸",
			short = "塞拉摩岛与北方城堡之间的海岸上挤满了泥鳍鱼人部族，它们将这段海岸线和零散的岛屿据为己有。",
			full = "塞拉摩岛与北方城堡之间的海岸上挤满了泥鳍鱼人部族，它们将这段海岸线和零散的岛屿据为己有。海龟和其他生物与它们共享着周围的水域。",
