		["foothold citadel"] = {
			name = "塞拉摩堡垒",
			short = "塞拉摩堡垒矗立在塞拉摩岛的中心，是塞拉摩卫兵的总部。",
			full = "塞拉摩堡垒矗立在塞拉摩岛的中心，是塞拉摩卫兵的总部。\n\n戴林·普罗德摩尔正是在这里走向了他的末路，当时萨尔的部队攻入了塞拉摩，由雷克萨和他的同伴们带领着冲进了城堡。这位违抗女儿吉安娜与兽人之间和平协定的海军上将，就倒在了这些城墙之内。",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
