		["lost point"] = {
			name = "废弃哨塔",
			short = "废弃哨塔是塞拉摩曾经在尘泥沼泽西部建造的一座破旧侦察塔，如今已经不再为它的建造者服务。",
			full = "废弃哨塔是塞拉摩曾经在尘泥沼泽西部建造的一座破旧侦察塔，如今已经不再为它的建造者服务。塞拉摩的逃兵们占据着这里，由巴鲁斯·加科因率领，他知道亨德尔下士参与了绑架一位非常重要的人物的事情。",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
