		["north point tower"] = {
			name = "北点哨塔",
			short = "北点哨塔守望着尘泥沼泽北部一条人来人往的道路，由一支人数可观的塞拉摩卫兵部队驻守。",
			full = "北点哨塔守望着尘泥沼泽北部一条人来人往的道路，由一支人数可观的塞拉摩卫兵部队驻守。自从逃兵占据了废弃哨塔之后，这座哨塔便成了塞拉摩最远的前哨。",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "奥妮克希亚的巢穴",
			short = "通往奥妮克希亚巢穴的通道，形状就像这位巢母自己张开的大嘴。通道之外，道路两旁满是岩浆，地面龟裂开来，从下方透出火光。",
			full = "通往奥妮克希亚巢穴的通道，形状就像这位巢母自己张开的大嘴。通道之外，道路两旁满是岩浆，地面龟裂开来，从下方透出火光。头顶的石质穹顶呻吟着、移动着，不断地落下碎石，而墙壁本身也在热量无法遏制的地方渗出熔岩。奥妮克希亚亲自开凿了这个地方，它深藏在黑龙谷之下，那是尘泥沼泽中一片阴郁的沼泽地。\n\n她与她的同类不同。她的父亲靠蛮力统治，她的兄弟则塑造扭曲的憎恶来执行他的命令，而奥妮克希亚却通过低语和魅惑行事，她热衷于凡人错综复杂的政治，悄悄地让他们屈从于她自己的目的。有一段时间，她冒用了一个名字，自称卡特拉娜·普瑞斯托，以这副伪装潜入了暴风城宫廷的核心，从内部瓦解它。是温德索尔元帅识破了她的伪装，揭穿了她的真面目。身份暴露之后，她逃离了那座城市，回到了她在沼泽下方的炽热大厅，至今仍待在那里，由她自己的同类黑龙军团守卫着。",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "泥潭沼泽",
			short = "泥潭沼泽是尘泥沼泽湿透的中心，在废弃哨塔和尘泥海湾之间延伸，北面是蕨墙村，南面是黑龙谷。",
			full = "泥潭沼泽是尘泥沼泽湿透的中心，在废弃哨塔和尘泥海湾之间延伸，北面是蕨墙村，南面是黑龙谷。\n\n鳄鱼潜伏在它漆黑的水中，软泥怪和蜘蛛在它的芦苇间爬行，而恐怖图腾牛头人则在这里占据着一片土地，远离任何会认领他们的亲族。这里最好是快速穿过，而不要逗留。",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "警戒哨岗",
			short = "警戒哨岗就矗立在从塞拉摩过桥的对面，这是一座由城堡建造的侦察塔，用来监视下方的道路。它完好无损地矗立着，默默地守望着所有前往那座城市的人。",
			full = "警戒哨岗就矗立在从塞拉摩过桥的对面，这是一座由城堡建造的侦察塔，用来监视下方的道路。它完好无损地矗立着，默默地守望着所有前往那座城市的人。",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "树荫旅店",
			short = "树荫旅店曾经坐落在尘泥沼泽与南贫瘠之地的交界附近，是一座由人类建造的路边驿站。",
			full = "树荫旅店曾经坐落在尘泥沼泽与南贫瘠之地的交界附近，是一座由人类建造的路边驿站。\n\n它毫无征兆地被烧成了平地。有两个人或许能说出罪魁祸首，帕瓦尔·雷瑟和考德威尔中尉，但他们还没来得及说出真相就都被杀死了，这场大火也就成了一桩悬案。",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "石槌废墟",
			short = "石槌村曾经坐落在尘泥沼泽中，是石槌部族食人魔的家园，直到督军科加尔夺得了古老的兽人战斧塞拉希尔，控制了这个部族，并以残暴统治着它。",
			full = "石槌村曾经坐落在尘泥沼泽中，是石槌部族食人魔的家园，直到督军科加尔夺得了古老的兽人战斧塞拉希尔，控制了这个部族，并以残暴统治着它。雷克萨正是来到了这里，却被拒之门外，他一路杀了进去。科加尔向他许诺，如果他能在鞭笞之路中活下来，就让他在部族中占有一席之地，那是一道挤满致命野兽的山谷。雷克萨挺了过来，回到了这里，并被接纳为石槌部族的一员。当科加尔拒绝让部族参加部落对抗库尔提拉斯的战争时，雷克萨向他发起挑战，争夺首领之位，并杀死了他，随后亲自率领石槌部族投入了战争。此后，他任命莫克莫洛克代替自己统治部族，然后便离开了。\n\n莫克莫洛克并没有像雷克萨那样统治。他从他的人民那里索取，而不是为他们服务，当奥妮克希亚的子嗣降临村庄并将它据为己有时，他带领幸存者逃到了安全的地方，并满足于待在那里，远离巨龙，而不愿为夺回昔日的家园而战。\n\n如今，这片废墟矗立在黑龙谷之中，被火鬃龙人所占据。",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "水光庄园",
			short = "水光庄园是尘泥沼泽女巫岭上的一座简朴的房子，是厨师“沼泽之眼”加尔的家。",
			full = "水光庄园是尘泥沼泽女巫岭上的一座简朴的房子，是厨师“沼泽之眼”加尔的家。\n\n在屋外的花园里，一堆翻动过的泥土下藏着一样加尔的烹饪无法解释的东西：一名兽人间谍埋下的一份报告，被留在泥土之下，以免它的秘密被窥探的目光发现。",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "塞拉摩岛",
			short = "第三次战争之后，吉安娜·普罗德摩尔带领洛丹伦的幸存者渡海来到卡利姆多。",
			full = "第三次战争之后，吉安娜·普罗德摩尔带领洛丹伦的幸存者渡海来到卡利姆多。在尘泥沼泽外的一座岩石岛上，他们建起了塞拉摩，这是一座有城墙环绕的城市，意在为联盟的残余力量在这片陌生的土地上提供庇护。\n\n这座城市被一道布满炮塔的长方形城墙环绕，只有在港口处才有缺口，那里改由两座侦察塔守卫。城市的中心耸立着吉安娜之塔，也就是城堡，它是塞拉摩最高的建筑，许多铺着木地板的楼层由蜿蜒的楼梯相连，并有防御攻击的结界，里面有吉安娜的私人住所、她的图书馆，以及城市的小王座厅。它的旁边矗立着塞拉摩堡垒，那是卫兵的营房，士兵们在那里对着训练假人操练，新兵们在牧师的注视下对练，牧师们随时准备在有人受伤的那一刻祈求圣光。\n\n沼泽的土壤贫瘠，木材也很差，塞拉摩的水手们抱怨说，兽人在奥格瑞玛上方砍伐的橡树比尘泥沼泽出产的任何东西都要好得多。即便如此，人类和兽人仍用鱼来交换杜隆塔尔多余的农作物，目前这座城市的犯罪率很低，它的人民大体上也安居乐业。",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "狂潮湾",
			short = "狂潮湾位于尘泥海湾的尽头，在塞拉摩岛以南，海面上点缀着小岛和隐秘的暗礁。在这片水域航行十分危险。",
			full = "狂潮湾位于尘泥海湾的尽头，在塞拉摩岛以南，海面上点缀着小岛和隐秘的暗礁。在这片水域航行十分危险。两艘船残破地躺在它的浅滩上，如今已被四处游荡的螯虾人所占据。\n\n在它的小岛之间坐落着纳特的码头，那是渔夫纳特·帕格的家。",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
