		["wyrmbog"] = {
			name = "巨龙沼泽",
			short = "在尘泥沼泽的黑龙谷以南，泥沼变得愈发浓稠，形成了巨龙沼泽。",
			full = "在尘泥沼泽的黑龙谷以南，泥沼变得愈发浓稠，形成了巨龙沼泽。黑龙在这里安家，大地上敞开着两个隐秘的地方：埃博斯塔夫的巢穴的入口，以及奥妮克希亚本人的巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
