			full = "在加基森以南、深沙平原附近，矗立着一小片被称为破碎石柱的巨魔废墟。地精科学家玛尔冯·瑞文斯克在那里扎营，在倒塌的石头间寻找着他自己的答案。",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "时光之穴",
			short = "时光之穴位于塔纳利斯东部的沙漠之下，这是一座与上方世界隔绝的蜿蜒迷宫。青铜龙军团在这里守望着时间本身的分岔之路。",
			full = "时光之穴位于塔纳利斯东部的沙漠之下，这是一座与上方世界隔绝的蜿蜒迷宫。青铜龙军团在这里守望着时间本身的分岔之路。自从世界诞生之初，这就是它们神圣的职责，是泰坦赋予它们的使命：守护这些洞穴，防止凡人的闯入，因为低等生灵的干涉可能会扰乱历史的洪流。洞穴的中心矗立着一座巨大的沙漏。\n\n时光守护者诺兹多姆与他的龙族一同住在这里，他有一个私人爱好，那就是收集稀有的神器。第二次战争之后，法师克拉苏斯借助一朵永恒玫瑰进入了诺兹多姆的巢穴，那是一件能让他瞬间跨越距离的装置。诺兹多姆对这次闯入十分不满，因为这打扰了他的收藏，他也毫不掩饰自己的不悦。",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "砂槌营地",
			short = "砂槌营地是砂槌食人魔的土丘，横卧在塔纳利斯的沙地上，这个部族在烈日下聚集在他们用泥土筑成的栖身之所中。",
			full = "砂槌营地是砂槌食人魔的土丘，横卧在塔纳利斯的沙地上，这个部族在烈日下聚集在他们用泥土筑成的栖身之所中。",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "东月废墟",
			short = "石砌的台地和开裂的石柱标志着东月废墟，它位于塔纳利斯的大裂口以西，是一座早已被遗弃的巨魔聚居地仅存的遗迹。",
			full = "石砌的台地和开裂的石柱标志着东月废墟，它位于塔纳利斯的大裂口以西，是一座早已被遗弃的巨魔聚居地仅存的遗迹。继巨魔之后，砂槌食人魔占据了这些摇摇欲坠的石头建筑，至今仍据守着它们。",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
