		["gadgetzan"] = {
			name = "加基森",
			short = "加基森从塔纳利斯北部的沙漠中崛起，终年笼罩在一层黑色的烟雾之下，它是热砂集团的首府，而热砂集团是地精集团中最强大的一个。",
			full = "加基森从塔纳利斯北部的沙漠中崛起，终年笼罩在一层黑色的烟雾之下，它是热砂集团的首府，而热砂集团是地精集团中最强大的一个。在这里，地精的信条支配着一切：利益高于忠诚。部落和联盟都正式承认这座城市是中立之地，地精打手在街道上巡逻，随时准备把任何胆敢将战争带入这个建立在贸易之上的地方的蠢货揍成肉泥。决定谁受欢迎的是钱包，而不是旗帜。\n\n那份中立从来都不是所有人都能安然接受的。废土强盗占领了东北方的热影废墟和清泉平原。地精们对那些古老的废墟毫不在意，但清泉平原却是另一回事：加基森水务公司在沙漠的烈日下在那里建造和维护的水塔，是维持这座城市生命的液体黄金。地精们绝不会交出他们辛辛苦苦建起来的水塔，于是来自世界各个角落的雇佣兵被卷了进来，保卫加基森的水源，抵御那些想要让它落入敌手的强盗。",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "大裂口",
			short = "大裂口里挤满了哈扎里异种虫，它们的虫巢群遍布塔纳利斯东南部的岩石之中。",
			full = "大裂口里挤满了哈扎里异种虫，它们的虫巢群遍布塔纳利斯东南部的岩石之中。\n\n高级勘探员菲兹杜瑟曾派他的下属谢申克下到裂口里进行勘测。谢申克再也没有出来。他死在了虫巢之间，后来只有他的装备被找回来，交给了菲兹杜瑟，而菲兹杜瑟一直都不知道，是自己把他送上了死路。",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "天涯海滩",
			short = "天涯海滩位于塔纳利斯的最南端，是卡利姆多东南角与大海相接的地方。海岸一片宁静，主要的标志就是在这里游荡的生物。",
			full = "天涯海滩位于塔纳利斯的最南端，是卡利姆多东南角与大海相接的地方。海岸一片宁静，主要的标志就是在这里游荡的生物。浪滑龟和沙岸螃蟹在东边的沙滩上择路而行，不受打扰。",
