		["noxious lair"] = {
			name = "腐化之巢",
			short = "塔纳利斯的西南部有一道沙地上的伤口，那里曾经有水。在异种虫到来之前，这片土地上曾有某种宽阔而浅的水域，也许是一条河，也许是一座湖，而森提帕尔虫群把它们在那里找到的东西吸干了。",
			full = "塔纳利斯的西南部有一道沙地上的伤口，那里曾经有水。在异种虫到来之前，这片土地上曾有某种宽阔而浅的水域，也许是一条河，也许是一座湖，而森提帕尔虫群把它们在那里找到的东西吸干了。塔纳利斯西部也因此变得干涸。\n\n地表依然显露着失去之物的形状。大地下陷，凹陷而空洞，俯瞰着安戈洛环形山，仿佛它还记得自己曾经是一片湖岸。巨大的爪子东一处西一处地直立在沙地上，抽搐着，仿佛被埋在地下的生物在攻击的途中被冻住了一般。每一只爪子周围的土壤都是黑色的，被异种虫的黏液浸得湿漉漉的，这是一个曾经拥有一座湖泊的地方仅存的水分。\n\n在地表之下，腐化之巢与森提帕尔在塔纳利斯开凿的其他任何虫巢一样：潮湿、温暖，寂静得令人毛骨悚然，隧道上覆盖着异种虫的酸液。",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "流沙岗哨",
			short = "流沙岗哨在加基森以西横跨塔纳利斯干涸的盆地，被法拉基巨魔和他们在自己的死者之中唤醒的僵尸所占据。",
			full = "流沙岗哨在加基森以西横跨塔纳利斯干涸的盆地，被法拉基巨魔和他们在自己的死者之中唤醒的僵尸所占据。",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
