		["south seas"] = {
			name = "南海",
			short = "已知大陆以南的水域，展开为无尽之海的一片广阔海域，洋流从一座座岛屿旁流过，这些岛屿的名字大多只有水手才知道。",
			full = "已知大陆以南的水域，展开为无尽之海的一片广阔海域，洋流从一座座岛屿旁流过，这些岛屿的名字大多只有水手才知道。赞达拉从这片海水中升起，那是巨魔帝国古老的故乡。科赞也位于其中，这是一座火山岛，岛上的人民与大陆上的各方势力保持着距离。\n\n在靠近荆棘谷的地方，大海因暗礁和隐秘的海湾而变得险恶，在这样的水域里，船长要么熟知每一块礁石的名字，要么就会失去他的船。这一带点缀着一些小岛，其中有些不过是一片沙洲，另一些则留有建造者早已消失在波涛之下的废墟。\n\n这片海之所以值得一提，与其说是因为在它上面打过的任何一场战役，不如说是因为它吞没了又半露出来的那些东西：沉没的神殿、被淹没的海岸，以及退潮时透过清澈的海水隐约可见的废墟。这是一片边缘与夹缝之海，沿着荆棘谷、塔纳利斯和奥丹姆的边界延伸，把潮水选择带来的任何东西送到它所分隔的海岸上。",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "塔纳利斯南海",
			short = "塔纳利斯南海静静地卧在塔纳利斯的南部边缘，是一片平坦的海滩，几乎没有什么生命。海龟和海巨人在浪花中游荡。",
			full = "塔纳利斯南海静静地卧在塔纳利斯的南部边缘，是一片平坦的海滩，几乎没有什么生命。海龟和海巨人在浪花中游荡。",
