		["steamwheedle port"] = {
			name = "热砂港",
			short = "热砂港坐落在塔纳利斯的东海岸，一条道路向西通往它的母城加基森，一座码头伸向科赞。",
			full = "热砂港坐落在塔纳利斯的东海岸，一条道路向西通往它的母城加基森，一座码头伸向科赞。它属于热砂集团，这些地精只要金子给得足，就跟任何人做生意。\n\n在港口的居民之中有叶基亚，他的所作所为促成了夺魂者哈卡的回归。",
