			short = "锯齿暗礁是艾萨拉的北部海岸，沙滩一次又一次地被突出的岩石和海水的小湾所截断。水面下隐藏着岩石和浅滩，使沿岸的通行十分危险。",
			full = "锯齿暗礁是艾萨拉的北部海岸，沙滩一次又一次地被突出的岩石和海水的小湾所截断。水面下隐藏着岩石和浅滩，使沿岸的通行十分危险。鱼人、九头蛇和螯虾人占据着这片海岸，在浅滩中游动，或在沙滩上缓慢地觅食。",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "门纳尔湖",
			short = "门纳尔湖的湖心一片平静，尽管四周的土地都属于龙人。",
			full = "门纳尔湖的湖心一片平静，尽管四周的土地都属于龙人。任何越过那道边界的人都会发现，湖泊本身并没有危险，在被严密守护的湖岸之间，这里是一处宁静而令人神清气爽的地方。\n\n这是除了诺森德之外，世界上少数几个蓝龙军团露面的地方之一。只有冬泉谷的麦索瑞尔可与之相比。在这片水域附近，常常可以看到年幼的蓝色雏龙。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "雷加什营地",
			short = "雷加什萨特在艾萨拉北部、乌索兰以东建起了他们的营地。",
			full = "雷加什萨特在艾萨拉北部、乌索兰以东建起了他们的营地。\n\n大法师克希雷姆曾在这里找到过一本魔典，这一发现让人们注意到了这座原本平淡无奇、充满邪能生物的营地。",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "拉文凯斯雕像",
			short = "艾萨拉南端的悬崖上矗立着一座巨像的残骸，不过如今剩下的部分已经配不上这个称呼了。",
			full = "艾萨拉南端的悬崖上矗立着一座巨像的残骸，不过如今剩下的部分已经配不上这个称呼了。只有断裂的双腿仍然立在海面之上，而这座巨大雕像的其余部分，要么散落在它们周围的岩石上，要么已经滑入了下方的波涛之中。\n\n如今萨斯纳迦占据着这片废墟。从水路无法到达这里；任何想要前往的人都必须从陆路过来，穿过那座通往埃达拉斯废墟之外的桥梁，才能站在那双倒塌的巨腿之下，而那无疑曾是一件蔚为壮观的东西。",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "雷瑟斯圣所",
			short = "雷瑟斯圣所残破地矗立在废墟海岸之中，位于拉文凯斯雕像的西南方。如今已经没有人守护它了。鱼人和螯虾人在它倒塌的石头间游荡，它们是唯一会来到这里的生物。",
			full = "雷瑟斯圣所残破地矗立在废墟海岸之中，位于拉文凯斯雕像的西南方。如今已经没有人守护它了。鱼人和螯虾人在它倒塌的石头间游荡，它们是唯一会来到这里的生物。",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "废墟海岸",
			short = "艾萨拉的南部海岸毫不掩饰地展露着它的残破。悬崖和海滩碎裂成一个个水湾，海水隐藏着浅滩，这些浅滩困住的船体比任何水手愿意去数的都要多。",
			full = "艾萨拉的南部海岸毫不掩饰地展露着它的残破。悬崖和海滩碎裂成一个个水湾，海水隐藏着浅滩，这些浅滩困住的船体比任何水手愿意去数的都要多。残破的船只半埋在沙中，旁边是更加古老、更加奇特的废墟，它们的建造者早已不在。鱼人、九头蛇和螯虾人在海岸线上出没，即使是熟悉这片海岸的人，走在上面也要小心翼翼。\n\n在西岸的海滩上方，一座侏儒建筑矗立在一座小山上，只有一条从内陆延伸过来的陡峭小路才能到达。布里莫和朱比·机械弹簧在这里安家做生意。楼上，在他们的私人卧室里，放着第三张床。没有人知道它属于谁，也不知道到底有没有人睡在上面。",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "埃达拉斯废墟",
			short = "在世界破碎之前，埃达拉斯是上层精灵的伟大要塞之一，是一座研习奥术的城市，最强大的法师们在石头上刻下符文和碑文，并将它们竖立在公共场所，好让任何路过的人都能思考他们对奥术的见解。",
			full = "在世界破碎之前，埃达拉斯是上层精灵的伟大要塞之一，是一座研习奥术的城市，最强大的法师们在石头上刻下符文和碑文，并将它们竖立在公共场所，好让任何路过的人都能思考他们对奥术的见解。\n\n这座城市的陷落并不平静。在上古战争期间，卡多雷的反抗军曾在这里对抗燃烧军团。当大分裂撕裂世界时，埃达拉斯无法承受：城市的大部分都崩塌了，沉入了下方风暴海湾的海水之中。\n\n残存下来的部分紧紧依附在东边的悬崖上，那是一群残破的塔楼，长久以来一直被曾以此为家的暗夜精灵所回避。如今纳迦占据了这片废墟，军阀克雷利安在辛玛洛神殿中统治着剩下的一切。在残骸之间，古代上层精灵的符文石碑依然矗立，它们所蕴含的奥术智慧，历经岁月却未被触动。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "鳞须海龟洞穴",
			short = "风暴海湾中一座小岛上的洞穴，以一只罕见的老海龟鳞须的名字命名。这里是他的家，却很少是他休息的地方，因为他更喜欢到遥远的无尽之海去猎食，让巢穴空着。",
			full = "风暴海湾中一座小岛上的洞穴，以一只罕见的老海龟鳞须的名字命名。这里是他的家，却很少是他休息的地方，因为他更喜欢到遥远的无尽之海去猎食，让巢穴空着。",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "影歌神殿",
			short = "影歌神殿是艾萨拉西部一座布满废墟的小山，没有任何明确的记载说明它为什么叫这个名字。",
			full = "影歌神殿是艾萨拉西部一座布满废墟的小山，没有任何明确的记载说明它为什么叫这个名字。它与贾罗德·影歌同名，他曾在上古战争中领导反抗军，也与他的妹妹玛维同名，这位守望者因在伊利丹·怒风于海加尔山背叛之后将他囚禁而为人所铭记。这两个人与这座小山有什么关系，没有人说得清。\n\n能说清的，是在那里行走的东西。上层精灵的鬼魂在石头之间徘徊，渴望着任何靠近的活物。",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "破碎海岸",
			short = "破碎海岸沿着艾萨拉风暴海湾的北侧延伸，到处都是九头蛇、海巨人、螯虾人和鱼人，它们各自占据着自己的一段沙滩。",
			full = "破碎海岸沿着艾萨拉风暴海湾的北侧延伸，到处都是九头蛇、海巨人、螯虾人和鱼人，它们各自占据着自己的一段沙滩。尽管到处都是利爪和触手，亚考兰神殿和埃达拉之塔依然从海岸上耸立起来。\n\n地精们也在这片海岸上圈占了土地，在一片利齿与潮水之间炒卖着海滨地产。",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
