		["southfury river"] = {
			name = "怒水河",
			short = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。",
			full = "怒水河发源于海加尔山的高处，从一座山间湖泊中倾泻而出，化作瀑布轰鸣着跌入低地。从那里开始，它奔流得又宽又急，将大地一分为二：它标志着灰谷与艾萨拉的分界，再往南，又是贫瘠之地的尽头和杜隆塔尔的起点。在入海口，河水从最后一道瀑布上奔腾而下，注入无尽之海，那里就在地精港口棘齿城的东北方。\n\n河上架着几座桥，一座连接艾萨拉与灰谷，另一座连接杜隆塔尔与贫瘠之地。\n\n这条河依然滋养着两岸的田地，依然让它流经之处的土壤一片青翠。",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "南山海滩",
			short = "南山海滩沿着风暴海湾的南缘延伸，沙滩上散布着曾经辉煌的城市埃达拉斯的废墟。",
			full = "南山海滩沿着风暴海湾的南缘延伸，沙滩上散布着曾经辉煌的城市埃达拉斯的废墟。如今纳迦占据着这片海岸，与螯虾人、九头蛇、鱼人以及偶尔从深水中浮上来的海巨人共享着它。",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "风暴悬崖",
			short = "风暴悬崖耸立在艾萨拉，被栖居在岩石间的萨斯纳迦所占据。在悬崖的最东端矗立着拉文凯斯雕像，那是一座孤零零的标志，俯瞰着这片被纳迦占据的岩石。",
			full = "风暴悬崖耸立在艾萨拉，被栖居在岩石间的萨斯纳迦所占据。在悬崖的最东端矗立着拉文凯斯雕像，那是一座孤零零的标志，俯瞰着这片被纳迦占据的岩石。",
