		["talrendis point"] = {
			name = "塔伦迪斯营地",
			short = "塔伦迪斯营地位于艾萨拉的西南部，它的两座警戒塔监视着与灰谷的边界，一口月亮井依然滋润着南边的土地。",
			full = "塔伦迪斯营地位于艾萨拉的西南部，它的两座警戒塔监视着与灰谷的边界，一口月亮井依然滋润着南边的土地。\n\n这座营地最初只不过是一座小小的暗夜精灵营地，是在森林边缘设立的一处哨所。",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "亚考兰神殿",
			short = "亚考兰神殿曾经用于崇拜艾露恩，它的石头矗立在艾萨拉的东北海岸上。那份神圣早已不复存在。",
			full = "亚考兰神殿曾经用于崇拜艾露恩，它的石头矗立在艾萨拉的东北海岸上。那份神圣早已不复存在。如今，海巨人亚考罗克住在它的顶端，由鱼人和螯虾人守卫着，它们会扑向任何靠近的人。周围的海岸线，也就是破碎海岸，也同样不安全，那里有和亚考罗克本人一样好斗的九头蛇和海巨人在把守。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "辛玛洛神殿",
			short = "辛玛洛神殿矗立在埃达拉斯废墟之中，它的石头仿照附近的亚考兰神殿的样子雕凿而成，也与后来在达纳苏斯建造的月神殿相似。",
			full = "辛玛洛神殿矗立在埃达拉斯废墟之中，它的石头仿照附近的亚考兰神殿的样子雕凿而成，也与后来在达纳苏斯建造的月神殿相似。它是在暗夜精灵转向奥术魔法之前的年代，为供奉艾露恩而建造的。\n\n神殿中曾经存放着辛玛洛水晶，这件礼物本意是要向上层精灵传达一个信息：他们根本就不需要奥术魔法。如今这块水晶已经不在了，很久以前就被人带走了。\n\n此后，神殿落入了萨斯纳迦部族之手。如今军阀克雷利安在那里统治，把曾经专为崇拜女神而保留的尊荣之位据为己有。",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "萨拉斯营地",
			short = "雷加什营地上方的小山属于血精灵，山坡被分割成一座座由魔导师里姆托丽掌管的小型设防据点。",
			full = "雷加什营地上方的小山属于血精灵，山坡被分割成一座座由魔导师里姆托丽掌管的小型设防据点。她与部落达成了一笔交易，承诺将她的探险队发掘出的任何东西分给部落一份，以换取保护探险队的金钱和兵力。这笔交易并没有得到遵守。里姆托丽拿了资助，却什么也没有回报，背叛的消息不胫而走，如今据说她和她的追随者都欠下了同样要以血偿还的债。\n\n里姆托丽本人很少待在营地里，她一心在自己挑选的护卫的保护下探索艾萨拉，而在她不在的时候，由魔导师鹰盔守住这座小山。他们两人真正追求的并不是金子。在营地的一道山脊上放着一本卡多雷召唤宝典，这件东西能够把恶魔召唤到世上，它的存在暴露了这支探险队的真面目：这不是一场寻宝，而是披着寻宝外衣的某种更加黑暗的勾当。",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "埃达拉之塔",
			short = "埃达拉之塔矗立在风暴海湾上方陆地的最东北端，它的沙滩上有鱼人、螯虾人和九头蛇在巡游。",
			full = "埃达拉之塔矗立在风暴海湾上方陆地的最东北端，它的沙滩上有鱼人、螯虾人和九头蛇在巡游。它曾经属于遍布这片海岸的暗夜精灵文明，但如今这座塔已经关闭，被人遗弃。",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "乌索兰",
			short = "乌索兰得名于熊怪一族所崇敬的熊之半神乌索尔。如今这里是木喉熊怪的一片广阔聚居地，一直向南延伸，穿过木喉要塞，直到熊头。",
			full = "乌索兰得名于熊怪一族所崇敬的熊之半神乌索尔。如今这里是木喉熊怪的一片广阔聚居地，一直向南延伸，穿过木喉要塞，直到熊头。",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "瓦罗莫克",
			short = "瓦罗莫克是部落在艾萨拉的一座前哨，位于西北部、哈达尔营地以北。驻扎在那里的战士们虽然处境艰难，却依然坚守着希望。",
			full = "瓦罗莫克是部落在艾萨拉的一座前哨，位于西北部、哈达尔营地以北。驻扎在那里的战士们虽然处境艰难，却依然坚守着希望。\n\n那份希望却从内部遭到了背叛。贝尔戈洛姆·石槌曾派血精灵魔导师里姆托丽带着一队兽人战士出发，去寻找这一地区的财宝和强大的神器。里姆托丽找到了她所寻找的东西，然而她不愿分享这一发现，反而对护送她的战士们下了毒手，杀死了他们，将战利品据为己有。领导营地的阿格图·血拳不会让这场屠杀得不到回应。他正在寻找战士，为他死去的同伴和石槌受伤的尊严报仇，要让魔导师里姆托丽死在她附近的营地里。",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
