			name = "血毒岗哨",
			short = "血毒岗哨矗立在黑海岸上方的高崖上，血毒河就在这里穿过费伍德森林。",
			full = "血毒岗哨矗立在黑海岸上方的高崖上，血毒河就在这里穿过费伍德森林。它的建筑风格和守卫它的牛头人都表明，这是由牛头人建立的，是部落监视下方海岸的一个小小立足点。\n\n要到达那里，需要沿着一条黑暗的小径走，这条小径从穿过费伍德森林的石路出发，沿着河的南岸向西延伸，绕过山坡，一直通到岗哨本身。",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "血毒河",
			short = "血毒河乌黑地流过费伍德森林，它的腐化蔓延到这一地区之外，直到作为黑海岸的急弯河再次出现。",
			full = "血毒河乌黑地流过费伍德森林，它的腐化蔓延到这一地区之外，直到作为黑海岸的急弯河再次出现。有毒的软泥怪在它的岸边爬行，附近的野生动物也变得有毒了。没有人喝它的水，也没有人在里面游泳。",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
