		["irontree cavern"] = {
			name = "铁木山洞",
			short = "在洞穴深处，扭木的扭曲木质已经扎下了根，孕育出了撕碎者和苔藓剥皮者，它们代替任何活着的守护者在黑暗中潜行。",
			full = "在洞穴深处，扭木的扭曲木质已经扎下了根，孕育出了撕碎者和苔藓剥皮者，它们代替任何活着的守护者在黑暗中潜行。",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "铁木森林",
			short = "铁木森林曾经是费伍德森林北部一片宁静的林间空地，直到燃烧军团的腐化将它扭曲成了别的东西。",
			full = "铁木森林曾经是费伍德森林北部一片宁静的林间空地，直到燃烧军团的腐化将它扭曲成了别的东西。暗夜精灵的三位伟大古树曾经住在这里，这些活着的树名叫哈斯塔特、斯托玛和瓦图斯。腐化也没有放过它们：三位古树都在原地石化，至今仍被封存在森林中，死在杀死它们的那片枯萎之中。\n\n然而，有某种东西拒绝死去。倒入森林中心的月亮井之水孕育出了一株幼苗。经过照料和培育，它开花了，然后又回到了它诞生的土地上，扎根在石化的死者之间，等待着成为一位古树，取代它们的位置。",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "碧火谷",
			short = "在费伍德森林南部被腐化的树林中，碧火谷庇护着一座萨特营地，这些恶魔生物将这片被污染的谷地据为己有，在它的腐朽之中繁衍生息，并将腐化进一步散布到周围的树林中。",
			full = "在费伍德森林南部被腐化的树林中，碧火谷庇护着一座萨特营地，这些恶魔生物将这片被污染的谷地据为己有，在它的腐朽之中繁衍生息，并将腐化进一步散布到周围的树林中。",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
