		["jadefire run"] = {
			name = "碧火小径",
			short = "在费伍德森林的北部坐落着碧火小径，这里是这一地区最强大的萨特的家园。任何靠近这里的人都务必小心谨慎。",
			full = "在费伍德森林的北部坐落着碧火小径，这里是这一地区最强大的萨特的家园。任何靠近这里的人都务必小心谨慎。这里的建筑遵循的是恶魔的设计，而不是凡人的设计。",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "加德纳尔",
			short = "加德纳尔从曾经属于暗夜精灵的土地上崛起，它的石头比如今侵占它们的腐化更加古老。",
			full = "加德纳尔从曾经属于暗夜精灵的土地上崛起，它的石头比如今侵占它们的腐化更加古老。在它的废墟之下有两座德鲁伊的地下墓穴，曾经神圣无比，而暗影议会正是在这片被亵渎的根基之上建立起了他们的统治，并以崇拜欺诈者基尔加丹的名义为这个地方命名。\n\n第三次战争之后，这片废墟落入了魔王贝恩霍勒和他所领导的暗影议会之手。兽人和被遗忘者的术士挤满了它的厅堂，而且他们并非孤身而来：魅魔、地狱猎犬、恶魔卫士和萨特在他们之间走动。它的中心矗立着暗影堡，那是暗影议会在艾泽拉斯的权力中枢，旁边则是以基尔加丹之名建造的欺诈者神祠。",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "摩罗萨兰",
			short = "摩罗萨兰曾经是一座宏伟的暗夜精灵聚居地，建于大分裂撕裂世界之前。",
			full = "摩罗萨兰曾经是一座宏伟的暗夜精灵聚居地，建于大分裂撕裂世界之前。如今它残破地躺在费伍德森林的南缘，是若干这类地方中的一处，就像亚米萨兰、巴莎兰、奥迪拉兰和塔迪萨兰一样，它们都曾是繁荣的城市，如今却只剩下石头，以及对一个早已逝去的黄金时代的回忆。",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "克斯特拉斯废墟",
			short = "这里残破的石柱曾经属于海加尔山附近的一座暗夜精灵聚居地。一口月亮井依然静卧在它的中心，但它已不再盛着纯净的光芒。",
			full = "这里残破的石柱曾经属于海加尔山附近的一座暗夜精灵聚居地。一口月亮井依然静卧在它的中心，但它已不再盛着纯净的光芒。邪能腐化已经渗入了井水，萨特萨瓦斯拉斯如今代表萨瓦里克照料着它，像培育一座用来投毒的花园一样培育着腐化。在废墟的更深处，一道火墙挡住了通往他的道路。\n\n德鲁伊的同胞们并没有对这些恶魔坐视不理，他们发动攻击，力图将这个地方从已在此扎根的邪能手中夺回来。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "暗影堡",
			short = "在费伍德森林西部的加德纳尔之下，有一座曾经是暗夜精灵地下墓穴的迷宫。暗影议会很久以前就占据了这里，如今术士和他们的恶魔仆从在它的坑道中游荡。",
			full = "在费伍德森林西部的加德纳尔之下，有一座曾经是暗夜精灵地下墓穴的迷宫。暗影议会很久以前就占据了这里，如今术士和他们的恶魔仆从在它的坑道中游荡。萨特萨瓦里斯王子和恐惧魔王贝恩霍勒都住在其中。\n\n圣骑士特雷·莱弗治和暗夜精灵亚科纳琳·星影深入费伍德森林，追查暗影议会活动的迹象。邪教徒抓住了他们两人，把他们关在了暗影堡里。特雷在那里被折磨致死，他的灵魂被俘虏他的人扭曲和腐化了。亚科纳琳至今仍被关在深处，被折磨她的人看守着，等待着一场尚未到来的救援。",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "碎痕谷",
			short = "碎痕谷是第三次战争期间燃烧军团横扫费伍德森林时地狱火坠落的地方。它们留下的陨坑至今仍在闷燃，在大地上留下道道伤痕，恶魔依然在其间游荡。",
			full = "碎痕谷是第三次战争期间燃烧军团横扫费伍德森林时地狱火坠落的地方。它们留下的陨坑至今仍在闷燃，在大地上留下道道伤痕，恶魔依然在其间游荡。",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
