		["shrine of the deceiver"] = {
			name = "欺诈者神祠",
			short = "欺诈者神祠是费伍德森林加德纳尔的一座被腐化的地下墓穴，得名于燃烧军团之王、欺诈者基尔加丹。",
			full = "欺诈者神祠是费伍德森林加德纳尔的一座被腐化的地下墓穴，得名于燃烧军团之王、欺诈者基尔加丹。暗影议会的术士挤满了它的深处，对毫无准备的人来说，这里是一个危险的地方。",
