		["talonbranch glade"] = {
			name = "刺枝林地",
			short = "刺枝林地位于费伍德森林的北部，在木喉要塞以南，就在通往月光林地和冬泉谷的小路旁。",
			full = "刺枝林地位于费伍德森林的北部，在木喉要塞以南，就在通往月光林地和冬泉谷的小路旁。",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
