		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位于费伍德森林的东北部，是木喉熊怪部族的首府。它的隧道开辟了一条通往月光林地和冬泉谷的通道。",
			full = "木喉要塞位于费伍德森林的东北部，是木喉熊怪部族的首府。它的隧道开辟了一条通往月光林地和冬泉谷的通道。\n\n当燃烧军团的腐化悄悄侵入卡利姆多神圣的森林时，熊怪们受到了它的影响，被扭曲得陷入疯狂。只有木喉部族逃过了那片黑暗，他们躲在自己的要塞里，眼看着他们所热爱的森林变成了溃烂腐败的扭曲模样。即使在恶魔的首领被击倒很久之后，森林中的污秽依然没有消散。\n\n木喉要塞的熊怪对所有陌生人都保持着警惕，他们担心自己会被误认为是被腐化的同族，一见面就遭到攻击。然而他们知道自己无法独自支撑下去，那些赢得他们信任的人会发现，木喉熊怪把友谊看得比什么都重要。最重要的是，他们只希望终结他们被腐化的同胞所受的苦难，并为费伍德森林所化成的这道伤口找到某种治愈的办法。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- 安戈洛环形山: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "火羽山",
			short = "火羽山耸立在安戈洛环形山的中心，这是一座焦黑的岩石山，熔岩沿着山坡缓缓流下，火元素在热浪中蠢蠢欲动。",
			full = "火羽山耸立在安戈洛环形山的中心，这是一座焦黑的岩石山，熔岩沿着山坡缓缓流下，火元素在热浪中蠢蠢欲动。浅浅的岩浆脉在环形山的地面之下流淌，为遍布安戈洛的嘶嘶作响的蒸汽池和间歇泉提供热量，因此整个盆地仿佛都在随着这座山的火焰呼吸。\n\n在山顶的一个洞穴里住着炽焰行者，它是在山岭上出没的火元素中最强大的一个，也是这座山燃烧之心的主宰。在这里闪烁舞动的火焰之灵诉说着它们数百年来的燃烧、熄灭成余烬、然后再次燃起，一遍又一遍，永无止境。\n\n并不是所有来到这座山岭的人都能征服它。一个名叫林格的流浪者来这里探索山坡，却迷了路，被炎热折磨得筋疲力尽。至今仍能在南边的洞穴里找到他，他再也没能走出来。",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "蘑菇石",
			short = "蘑菇石开在安戈洛环形山的东北壁上，这是一个洞穴，大猩猩生活在洞中黑暗里生长的幽灵蘑菇之间。",
			full = "蘑菇石开在安戈洛环形山的东北壁上，这是一个洞穴，大猩猩生活在洞中黑暗里生长的幽灵蘑菇之间。在洞外，一个小池塘汇聚在一道瀑布下方，卡尔纳·雷塔维的机械猿A-Me 01就站在那里。",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "葛拉卡温泉",
			short = "葛拉卡温泉上终年蒸汽升腾，安戈洛环形山火山的核心在环形山西部向池塘和间歇泉中释放着热量。",
			full = "葛拉卡温泉上终年蒸汽升腾，安戈洛环形山火山的核心在环形山西部向池塘和间歇泉中释放着热量。由那些蒸汽和火焰诞生的狂怒元素在岸边徘徊，它们被同样让温泉沸腾不止的力量从大地中召唤出来。\n\n克拉兰克曾经来到这里，追查温泉与附近火羽山的火焰之间的联系，后来他的探寻把他带到了别处。",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "铁石高原",
			short = "光秃秃的岩石沿着安戈洛的东北壁冲破了一片绿意。与环形山的其他地方相比，铁石高原十分安静，几乎没有什么掠食者。",
			full = "光秃秃的岩石沿着安戈洛的东北壁冲破了一片绿意。与环形山的其他地方相比，铁石高原十分安静，几乎没有什么掠食者。幼小的翼手龙在这里筑巢，高原的宁静使它有别于安戈洛那永不停歇的生长。",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "拉卡利油沼",
			short = "马绍尔营地以北的黑色湖泊在安戈洛的一片绿意之中显得浓稠而恶臭。数以百计的骸骨从表面伸出来，那是一些野兽的遗骸，它们踏进去时以为是坚实的地面，却发现并非如此。",
			full = "马绍尔营地以北的黑色湖泊在安戈洛的一片绿意之中显得浓稠而恶臭。数以百计的骸骨从表面伸出来，那是一些野兽的遗骸，它们踏进去时以为是坚实的地面，却发现并非如此。食腐动物在边缘徘徊，等待着焦油完成它已经开始的事情，而焦油怪物则从这些油沼中升了起来。",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "马绍尔营地",
			short = "马绍尔营地坐落在安戈洛环形山的北缘，是由威利德·马绍尔和霍莱伊·马绍尔领导的马绍尔探险队建立的。",
			full = "马绍尔营地坐落在安戈洛环形山的北缘，是由威利德·马绍尔和霍莱伊·马绍尔领导的马绍尔探险队建立的。他们深入环形山的冒险对所发现的一切毫无准备；安戈洛的野兽实在太过凶猛，探险队的营地一个接一个地被攻陷。这支队伍剩下的人逃到了高处，在环形山的边缘，也就是这里，得以逃生。\n\n这座营地就是那次撤退的结果，是一个勉强守住、而非夺取而来的立足点。",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "沼泽地",
			short = "沼泽地横亘在安戈洛环形山的东南部，是一片低洼的积水和繁茂杂草，大多数从塔纳利斯第一次下到环形山的人首先见到的就是它，因为其他任何一条路都十分凶险。",
			full = "沼泽地横亘在安戈洛环形山的东南部，是一片低洼的积水和繁茂杂草，大多数从塔纳利斯第一次下到环形山的人首先见到的就是它，因为其他任何一条路都十分凶险。迅猛龙成群结队地在芦苇丛中穿行，其中一些的咬伤还带有毒性。\n\n在这里可以找到蓝色的能量水晶，它们的存在已经渗入了沼泽本身，渗进了在湿地上狩猎的迅猛龙体内，在它们身上留下了印记。\n\n在一座从水中隆起的土丘上，托尔瓦·寻路者守望着，他是从环形山的其他地方划着独木舟来到这里的。",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "巨痕谷",
			short = "巨痕谷横跨安戈洛环形山的南部，是格里什教派的一座虫巢。",
			full = "巨痕谷横跨安戈洛环形山的南部，是格里什教派的一座虫巢。\n\n这座虫巢曾经有一位女王，只要惊动巢中的格里什异种虫水晶，便能将她召唤出来。",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "恐惧小道",
			short = "在巨痕谷以西的恐惧小道上，红色的水晶从地下长了出来，这在安戈洛环形山的其他任何地方都见不到。这条小道上的野兽吸收了它们的力量，这在它们身上表现得一清二楚。",
			full = "在巨痕谷以西的恐惧小道上，红色的水晶从地下长了出来，这在安戈洛环形山的其他任何地方都见不到。这条小道上的野兽吸收了它们的力量，这在它们身上表现得一清二楚。",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
