	-- 月光林地: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "月神湖",
			short = "晶莹的湖水填满了月光林地的中心，在树林下静得如同一面镜子。在它的水面之下躺着疯狂的半神奥曼，他在许多世纪之前被击败，却从未真正离开这片深水。",
			full = "晶莹的湖水填满了月光林地的中心，在树林下静得如同一面镜子。在它的水面之下躺着疯狂的半神奥曼，他在许多世纪之前被击败，却从未真正离开这片深水。湖水让他保持沉寂，那是平静的水面下一份无声的重负。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "永夜港",
			short = "在月神湖畔矗立着永夜港，这是一座由暗夜精灵的石雕建筑和月亮井组成的村庄，是塞纳里奥议会德鲁伊的家园。",
			full = "在月神湖畔矗立着永夜港，这是一座由暗夜精灵的石雕建筑和月亮井组成的村庄，是塞纳里奥议会德鲁伊的家园。这是一个宁静而与世隔绝的地方，对大多数外人关闭，这里的人们全心投入到德鲁伊之道和对荒野的照料之中。\n\n永夜港每年只打开一次大门，那就是在庆祝春节的时候，人们在湖面上空燃放烟花，以颂扬艾露恩的力量，欢迎那些平时永远不会在这里受到欢迎的陌生人。\n\n然而这座村庄见过比任何节日都更加黑暗的夜晚。正是在这里，守护者雷姆洛斯直面了梦魇之龙伊兰尼库斯，这条巨龙已被腐化，并转而与村庄为敌。梦魇生物扑向永夜港，眼看就要将它彻底毁灭，直到泰兰德·语风终于到来，召唤艾露恩的光芒，净化了侵占这条巨龙的腐化。月亮井至今仍燃烧着同样的光芒。",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "雷姆洛斯神殿",
			short = "在月光林地的西部矗立着雷姆洛斯神殿，它是为了纪念守望着那里的守护者而建造的。暗夜精灵塔加里住在里面，指导那些想要学习水栖形态的年轻德鲁伊。",
			full = "在月光林地的西部矗立着雷姆洛斯神殿，它是为了纪念守望着那里的守护者而建造的。暗夜精灵塔加里住在里面，指导那些想要学习水栖形态的年轻德鲁伊。",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "怒风兽穴",
			short = "在月光林地宁静的草地之下，躺着一座座地下墓穴，它们深陷在许多暗夜精灵德鲁伊从未真正离开的土地之中，他们的身体在这里安息，而灵魂则在翡翠梦境中漫游。",
			full = "在月光林地宁静的草地之下，躺着一座座地下墓穴，它们深陷在许多暗夜精灵德鲁伊从未真正离开的土地之中，他们的身体在这里安息，而灵魂则在翡翠梦境中漫游。\n\n玛法里奥·怒风曾在这里沉睡，这些墓穴也因此以他的名字命名。当提克迪奥斯和他的恐惧魔王们在第三次战争中到来时，他们袭击了沉睡中的玛法里奥，几乎将他的墓穴撕裂。是泰兰德·语风唤醒了他，将他召回世间，与阿克蒙德和燃烧军团对抗。\n\n后来，当塞纳里奥议会商议种植第二棵世界之树时，玛法里奥回到这些地下墓穴中冥想。泰兰德后来前来寻找他，却发现他的身体一动不动，仿佛睡着了一般，怎么也唤不醒。议会认为最好不要移动他：如果他的灵魂仍在梦境中漫游，寻找回家的路，那么它需要在离开身体的地方找到它。于是他一直留在那里，由塞纳里奥议会和艾露恩姐妹会守护着，他的身体静静地躺在以他的名字命名的墓穴之中。",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位于费伍德森林的东北部，那里有一条隧道一直通往月光林地和冬泉谷。它是木喉熊怪部族的首府。",
			full = "木喉要塞位于费伍德森林的东北部，那里有一条隧道一直通往月光林地和冬泉谷。它是木喉熊怪部族的首府。\n\n当燃烧军团的腐化悄悄侵入卡利姆多神圣的森林时，熊怪们受到了它的影响。只有木喉部族逃过了那片黑暗，他们躲在自己的要塞里，无助地看着他们所热爱的森林被扭曲成溃烂腐败的模样。即使在那场腐化的源头被摧毁之后，森林中的污秽依然没有消散。\n\n如今，木喉熊怪对所有陌生人都保持着警惕，他们担心自己可能会被误认为是被腐化的同族，一见面就遭到攻击。然而他们知道自己无法独自支撑下去，那些赢得他们信任的人会发现，木喉熊怪把友谊看得比什么都重要。他们的萨满传统延续至今，擅长用兽皮制作护甲，并拥有古老的治疗知识。最重要的是，这个部族渴望终结他们被腐化的同族所受的苦难，好让这片古老的森林有朝一日能再次回荡起它已失去的歌声与欢笑。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- 希利苏斯: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "格拉卡隆之骨",
			short = "在希利苏斯的中部，躺着巨龙格拉卡隆的巨大骸骨，他在流沙之战中倒在了那里。",
			full = "在希利苏斯的中部，躺着巨龙格拉卡隆的巨大骸骨，他在流沙之战中倒在了那里。",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "铜须营地",
			short = "铜须营地位于希利苏斯南部，在甲虫之墙以东。",
			full = "铜须营地位于希利苏斯南部，在甲虫之墙以东。",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "塞纳里奥要塞",
			short = "塞纳里奥要塞在流沙之战之后崛起于希利苏斯，由塞纳里奥议会建在一座古老的暗夜精灵聚居地之上。",
			full = "塞纳里奥要塞在流沙之战之后崛起于希利苏斯，由塞纳里奥议会建在一座古老的暗夜精灵聚居地之上。它是卡利姆多规模最大的德鲁伊要塞之一，只有月光林地本身能与之相比，而它的目的只有一个：守住防线，抵挡异种虫虫群，并守望着埋藏在黄沙之下的那个东西，那就是被囚禁的上古之神克苏恩，以免它的大军再次崛起。\n\n在这里生活艰苦而充满战斗。异种虫不断地冲击着它的城墙，周围的地区也变得越来越充满敌意。即便如此，要塞里的商人们依然开着他们的摊位，与任何从安戈洛环形山长途跋涉上来的人做买卖，因为离其他地方这么远，生意十分稀少，每一枚硬币都很重要。\n\n通往这里的小路从安戈洛向西北蜿蜒而出，经过苔藓堆，沿着一道陡峭的崖壁曲折攀升，然后通向希利苏斯燃烧的荒原。",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "水晶谷",
			short = "在希利苏斯最西北的角落里坐落着水晶谷，这座山谷已被土元素和空气元素所占据。",
			full = "在希利苏斯最西北的角落里坐落着水晶谷，这座山谷已被土元素和空气元素所占据。瑟银矿在它的岩石下储量丰富，但这片土地首先属于在那里躁动不安、古老的灵魂。德米提恩在山谷中设有一座营地。\n\n正是在这里，逐风者桑德兰可以被召唤出来，并重新被束缚在承载他怒火的那把剑刃之中，这是一项风暴与意志的仪式，很少有人敢于尝试，能够完成的就更少了。",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "亚什虫巢",
			short = "亚什虫巢位于希利苏斯的北部，它的异种虫后代向外扩散，侵占了它边界之外的虫群之柱。",
			full = "亚什虫巢位于希利苏斯的北部，它的异种虫后代向外扩散，侵占了它边界之外的虫群之柱。",
