			short = "在希利苏斯的南部，雷戈虫巢的土丘从沙地中升起，那里是异种虫的家园，隧道和甲壳在尘土中密密麻麻。",
			full = "在希利苏斯的南部，雷戈虫巢的土丘从沙地中升起，那里是异种虫的家园，隧道和甲壳在尘土中密密麻麻。",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
