			short = "佐拉虫巢是在希利苏斯西部沙地中挖掘出来的一座异种虫巢穴。",
			full = "佐拉虫巢是在希利苏斯西部沙地中挖掘出来的一座异种虫巢穴。",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "奥泰尔藏身处",
			short = "在希利苏斯的东南部，一个小洞穴向山坡敞开，那里住着一个名叫奥泰尔的隐士。",
			full = "在希利苏斯的东南部，一个小洞穴向山坡敞开，那里住着一个名叫奥泰尔的隐士。",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "暮光营地废墟",
			short = "在希利苏斯西北部的水晶谷中，矗立着一座暮光之锤的营地，被德米提恩据为己有。",
			full = "在希利苏斯西北部的水晶谷中，矗立着一座暮光之锤的营地，被德米提恩据为己有。\n\n德米提恩一直留在这里，为邪教据守着这片土地。",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "甲虫之台",
			short = "甲虫之锣矗立在甲虫之台上，位于希利苏斯南部安其拉城外甲虫之墙的西北方。",
			full = "甲虫之锣矗立在甲虫之台上，位于希利苏斯南部安其拉城外甲虫之墙的西北方。",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "甲虫之墙",
			short = "甲虫之墙沿着希利苏斯的南部边缘延伸，将沙漠与墙外那座残破的城市安其拉隔绝开来。",
			full = "甲虫之墙沿着希利苏斯的南部边缘延伸，将沙漠与墙外那座残破的城市安其拉隔绝开来。它是在流沙之战结束时从沙地中升起的，砂岩墙体至少向天空攀升了一百尺。在那个高度之上，岩石再也无法继续升高，青铜龙军团便将他们的魔法编织成一道屏障，比城墙还要高出许多倍。\n\n建造它的暗夜精灵和青铜龙一起将它命名为伊拉纳伊希尔，意为抵御暗影之盾。这个名字清楚地说明了它的用途：克苏恩和它的异种虫后代被封印在安其拉之中，而这道墙就矗立在那份恐怖与世界的其余部分之间。",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "南风村",
			short = "南风村曾经是希利苏斯的一座暗夜精灵前哨。它没能在流沙之战中幸存下来。",
			full = "南风村曾经是希利苏斯的一座暗夜精灵前哨。它没能在流沙之战中幸存下来。\n\n当其拉人成群结队地蜂拥而起时，范达尔·鹿盔的儿子瓦斯坦·鹿盔率领一支暗夜精灵军队的分队守卫这座村庄。他的部队在原地惨遭屠杀，而瓦斯坦本人则被拉贾克斯将军活捉，他奉命守卫的村庄就在他的身后被撕成了碎片。\n\n其拉人留下的废墟并没有一直空着。在那场屠杀中倒下的德鲁伊和哨兵的灵魂在残骸之间徘徊，漫无目的地游荡，被束缚在他们死去的地方，追随着琥珀月之魂。南风村至今仍矗立着，却不是一片宁静的废墟，而是一片闹鬼的土地，它的死者与它之间的事情仍未了结。",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "鹿盔岗哨",
			short = "一座暗夜精灵的塔楼曾经矗立在希利苏斯东北部的一座山峰顶上。永恒守望者拉罗沙尔在这里坚守着她的岗位，一头诺兹多姆族群的青铜幼龙在她头顶的天空中盘旋。",
			full = "一座暗夜精灵的塔楼曾经矗立在希利苏斯东北部的一座山峰顶上。永恒守望者拉罗沙尔在这里坚守着她的岗位，一头诺兹多姆族群的青铜幼龙在她头顶的天空中盘旋。从塔楼沿路而下便是暮光小径，那是一个庇护着暮光邪教徒的洞穴，洞口有一座小营地，这是这位守望者必须应对的威胁。",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "虫群之柱",
			short = "虫群之柱耸立在塞纳里奥要塞以南，这座山峰被异种虫的隧道钻得千疮百孔，山坡上从来都不平静。",
			full = "虫群之柱耸立在塞纳里奥要塞以南，这座山峰被异种虫的隧道钻得千疮百孔，山坡上从来都不平静。一团小型异种虫时时刻刻都在围着岩石盘旋，这团活的云雾为这座石柱赢得了名字，而在它脚下的沙地之下，有一座虫巢的巢室，那是遍布希利苏斯地下的众多此类巢穴中最大的一个。",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
