		["twilight outpost"] = {
			name = "暮光前哨站",
			short = "暮光前哨站位于希利苏斯最西南的角落，靠近甲虫之墙，在铜须营地以西。它由暮光之锤邪教把守。",
			full = "暮光前哨站位于希利苏斯最西南的角落，靠近甲虫之墙，在铜须营地以西。它由暮光之锤邪教把守。",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
