		["twilights run"] = {
			name = "暮光小径",
			short = "暮光小径隐藏在希利苏斯北部鹿盔岗哨山脚的岩石之中。",
			full = "暮光小径隐藏在希利苏斯北部鹿盔岗哨山脚的岩石之中。它的洞口丝毫看不出里面的黑暗中充斥着什么：一间接一间的洞室都被暮光之锤邪教占据，他们把山中的这个空洞据为己有，幽深而隐秘，而沙漠的狂风则在他们上方冲刷着岩石。",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "勇士之墓",
			short = "勇士之墓是希利苏斯边缘的一座小营地，从安戈洛环形山西北角攀升上来的小路可以抵达这里，这是旅人从下方进入沙漠时穿过的第一片土地。",
			full = "勇士之墓是希利苏斯边缘的一座小营地，从安戈洛环形山西北角攀升上来的小路可以抵达这里，这是旅人从下方进入沙漠时穿过的第一片土地。\n\n这座营地由塞纳里奥议会的成员照料，他们与一场令人不安地似曾相识的虫灾共享着这片土地。联盟和部落的人们都会在路过时在这里歇脚，营地的边缘静静地矗立着一座座坟墓。",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
