	-- 冬泉谷: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "班萨罗兽穴",
			short = "在冬泉谷的坠星村后面坐落着班萨罗兽穴，这是一座由隧道构成的迷宫，里面存放着村民们珍视的神圣遗物。",
			full = "在冬泉谷的坠星村后面坐落着班萨罗兽穴，这是一座由隧道构成的迷宫，里面存放着村民们珍视的神圣遗物。",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
