		["darkwhisper gorge"] = {
			name = "暗语峡谷",
			short = "暗语峡谷位于冬泉谷的南部。",
			full = "暗语峡谷位于冬泉谷的南部。\n\n当燃烧军团的大军在第三次战争中于海加尔山溃败、阿克蒙德倒下之后，幸存下来的恶魔并没有从世上消失。他们逃进了暗语峡谷，在那里躲藏起来，这支几乎毁灭了世界的大军的残余，就这样被留在黑暗中溃烂。",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "丹曼达尔",
			short = "丹曼达尔坐落在冬泉谷东南部的一个冰洞附近，它的名字暴露了它出自矮人之手。如今凶猛的枭兽占据了这座营地，至于建造它的人，几乎什么也没有留下。",
			full = "丹曼达尔坐落在冬泉谷东南部的一个冰洞附近，它的名字暴露了它出自矮人之手。如今凶猛的枭兽占据了这座营地，至于建造它的人，几乎什么也没有留下。",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
