		["everlook"] = {
			name = "永望镇",
			short = "永望镇坐落在冬泉谷各条商路的交汇处，是热砂集团的一座地精据点，它的实验室就隐藏在建筑群之间。",
			full = "永望镇坐落在冬泉谷各条商路的交汇处，是热砂集团的一座地精据点，它的实验室就隐藏在建筑群之间。\n\n银色黎明派格雷戈·格雷斯通来到这里，在热砂集团的地方管理机构面前代表他们的利益。",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "冰火温泉",
			short = "蒸汽从冬泉谷最西端的一连串水池中升起，这些水对于周围冰冻的土地来说太过温暖了。没有人能解释为什么这些温泉会在冰雪之下如此滚烫。",
			full = "蒸汽从冬泉谷最西端的一连串水池中升起，这些水对于周围冰冻的土地来说太过温暖了。没有人能解释为什么这些温泉会在冰雪之下如此滚烫。在附近扎营的多诺瓦·雪山怀疑，也许是某种从暗语峡谷向北渗透的恶魔污秽找到了路，来到这里温暖了岩石。\n\n最靠近木喉要塞的那个水池从未摆脱寒水部族的控制。他们至今仍占据着它，这些熊怪无意与别人分享他们所占有的温暖。",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
