		["frostwhisper gorge"] = {
			name = "霜语峡谷",
			short = "霜语峡谷穿过冬泉谷的南部，谷底和山脊上散布着暗夜精灵的废墟。霜槌巨人和他们高大的保护者就住在这些古老的石头之间。",
			full = "霜语峡谷穿过冬泉谷的南部，谷底和山脊上散布着暗夜精灵的废墟。霜槌巨人和他们高大的保护者就住在这些古老的石头之间。",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "隐秘小林",
			short = "隐秘小林深陷在冬泉谷的一个陨坑之中，四面都被陡峭的悬崖环绕。",
			full = "隐秘小林深陷在冬泉谷的一个陨坑之中，四面都被陡峭的悬崖环绕。只有一个开凿在东南山脊上的洞穴可以通行，而从上方的高处跳下去，是一条很少有人敢走的路。\n\n这片谷地曾经只有白色的野兔，它们在这处庇护所中不受打扰地繁衍生息，没有比它们更可怕的东西。此后情况变了。如今这片小林被枭兽占据，它们对任何进入的人都充满敌意，而它们的存在，就像这里的悬崖一样，将这个地方牢牢地封闭了起来。",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "冰蓟岭",
			short = "冰蓟岭耸立在永望镇的东南方，是冰蓟雪人的家园，它们栖息在一个向山坡上攀升的洞穴里，并在周围的山坡上游荡。",
			full = "冰蓟岭耸立在永望镇的东南方，是冰蓟雪人的家园，它们栖息在一个向山坡上攀升的洞穴里，并在周围的山坡上游荡。那些冒着严寒前来猎取它们的人，十分珍视它们厚厚的毛皮和苍白的角。\n\n冰盖草生长在开阔的山坡上，洞穴里的岩石中则贯穿着瑟银矿脉。最稀罕的是，据说在洞口的最边缘，有时会有一朵黑莲花绽放，在雪人的地盘上显得脆弱而奇异。",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "凯斯利尔湖",
			short = "凯斯利尔湖冰封的湖水静静地躺在冬泉谷的中心，周围环绕着与它同名的废墟。",
			full = "凯斯利尔湖冰封的湖水静静地躺在冬泉谷的中心，周围环绕着与它同名的废墟。这些废墟是古老的上层精灵建筑，那些曾经住在那里的人在他们的厅堂倒塌时并没有离开。他们的灵魂至今仍在徘徊，饱受折磨，在冰面和残破的石头间飘荡。",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "麦索瑞尔",
			short = "在冬泉谷的冰层深处，靠近凯斯利尔湖，麦索瑞尔洞穴在地下敞开，寒冷、广阔，充满了魔法。",
			full = "在冬泉谷的冰层深处，靠近凯斯利尔湖，麦索瑞尔洞穴在地下敞开，寒冷、广阔，充满了魔法。这里住着一窝效忠于玛里苟斯的蓝龙，它们的女族长也在这里独自守望。\n\n哈雷很少以世人所认为的真实形态示人，她只以一个高等精灵的样子出现在洞穴的最高处，要到达那里，必须通过设在下方远处地面上的一个传送符文。除了她自己的同类之外，很少有人见过她的真面目。\n\n她在自己身边设下了一支与她的隐居相称的卫队。四头强大的幼龙只听命于她一个人。法术之喉在冬泉谷三分之一的低地上缓慢而不间断地巡逻，而法力之爪和占卜者则守在洞穴后部的符文旁，就像守着一扇上了锁的门的哨兵。",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "惨月洞穴",
			short = "从永望镇的大门向东北走不远，地势便朝着一个被称为惨月洞穴的小洞穴升高，那里住着凶猛的暴怒枭兽。",
			full = "从永望镇的大门向东北走不远，地势便朝着一个被称为惨月洞穴的小洞穴升高，那里住着凶猛的暴怒枭兽。在洞穴与南边的寒水村之间隔着一座山，尽管这两个地方看起来近在咫尺，却没有直接相连的道路，只能绕过高地骑行很长一段路。",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "枭翼树丛",
			short = "枭翼树丛的洞穴穿过冬泉谷的南部，是那些发狂、被月光浸染、神志错乱的枭兽的家园。",
			full = "枭翼树丛的洞穴穿过冬泉谷的南部，是那些发狂、被月光浸染、神志错乱的枭兽的家园。据说古老的艾露恩守护者在这里讲述枭兽最初是如何来到世上的，而这个故事由兰莎尔拉保存着。",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "凯斯利尔废墟",
			short = "凯斯利尔废墟残破地躺在与它同名的湖泊边缘，是一座宏伟的暗夜精灵城市仅存的遗迹。",
			full = "凯斯利尔废墟残破地躺在与它同名的湖泊边缘，是一座宏伟的暗夜精灵城市仅存的遗迹。它在大分裂中陷落，那时世界本身被撕裂，它从此再也没有复兴。\n\n如今在那里徘徊的，是化作不安的哀伤。凯斯利尔陷落时死去的上层精灵并没有离去；他们的灵魂留在北部废墟倒塌的石柱之间，饱受折磨，无法放下他们失去的一切。高等精灵的鬼魂在东部地区出没，其中有遭到背叛的游侠和一位大法师。\n\n一块名为辛玛洛的水晶与这个地方的陷落紧密相关，它与一场在这里吞噬了一代又一代精灵的毁灭联系在一起。那个故事属于凯斯利尔本身，属于那些倒塌的石头，以及仍在其间行走的鬼魂。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "坠星村",
			short = "坠星村坐落在穿越冬泉谷的道路旁，是联盟在那片寒冷土地上唯一的立足点。",
			full = "坠星村坐落在穿越冬泉谷的道路旁，是联盟在那片寒冷土地上唯一的立足点。一座暗夜精灵的小屋和一座较小的房子组成了这个定居点，附近是班萨罗兽穴，它像给它命名的那些墓冢一样深陷在大地之中。",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "木喉要塞",
			short = "木喉要塞位于费伍德森林北部的隧道之中，这条通道通往月光林地和冬泉谷，它是木喉熊怪部族最后的据点。",
			full = "木喉要塞位于费伍德森林北部的隧道之中，这条通道通往月光林地和冬泉谷，它是木喉熊怪部族最后的据点。\n\n当燃烧军团的腐化悄悄侵入卡利姆多神圣的森林时，那片土地上的熊怪都屈服于它，被扭曲成野蛮而残忍的东西。只有木喉部族逃过了那样的命运，他们固守在自己的隧道里，而他们所热爱的森林就在他们周围变成了溃烂腐败的扭曲模样。即使在腐化的源头被摧毁之后，森林中的污秽依然没有消散。\n\n木喉熊怪依然对所有陌生人保持着警惕，他们担心自己会被误认为是被腐化的同族，还没来得及证明自己就被砍倒。然而他们知道自己无法独自支撑下去，对那些赢得他们信任的人，他们十分慷慨：他们恪守古老的萨满之道，毫无保留地分享他们所掌握的治疗知识。他们最想要的，是终结被腐化的同胞所受的苦难，并治愈费伍德森林所受的创伤。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "木喉岗哨",
			short = "木喉岗哨保留着一个已经名不副实的名字。",
			full = "木喉岗哨保留着一个已经名不副实的名字。这座营地曾经属于木喉部族，但如今它听命于被腐化的寒水熊怪，他们完全占据了这里，这座营地位于冰火温泉的东南方、凯斯利尔湖以西。",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "寒水村",
			short = "寒水村攀附在冬泉谷东部的山坡上，靠近永望镇，村里的熊怪早已被腐化。在它的顶端有一个小洞穴，那是冬泉酋长的居所，他从那里统治着这个定居点。",
			full = "寒水村攀附在冬泉谷东部的山坡上，靠近永望镇，村里的熊怪早已被腐化。在它的顶端有一个小洞穴，那是冬泉酋长的居所，他从那里统治着这个定居点。",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
