	-- 达纳苏斯: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "塞纳里奥区",
			short = "塞纳里奥区位于达纳苏斯的西北部，这是一片环形的林地，这里的橡树和白蜡树比城中其他地方的石头大厅还要高。",
			full = "塞纳里奥区位于达纳苏斯的西北部，这是一片环形的林地，这里的橡树和白蜡树比城中其他地方的石头大厅还要高。这里的每一棵树上都带有符文，它们不是雕刻出来的，而是从活的树皮中生长出来的，林中的聚会之所本身也是由木头和石头交织而成的，仿佛是生长出来的，而不是建造出来的。\n\n这里一直是城中德鲁伊的大本营，正如月神殿是城中牧师的大本营一样。大德鲁伊范达尔·鹿盔在塞纳里奥区的枝干间领导着他们，而矗立在林地中心、这里最大的一座活体建筑，便是他自己的居所。\n\n这片林地依然为聚集在它下方的教团服务：德鲁伊们来这里学习古老的道路，猎人们在最东边的那棵树中接受训练，而在塞纳里奥区那棵巨树的脚下，人们可以学习骑乘夜刃豹，这些猎豹载着达纳苏斯的骑手穿越荒野。在地下，隐藏在最西边的枝干中，一个神秘的盗贼公会设有它的据点，只有那些早已知道该去哪里找的人才知道它的存在。",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "工匠区",
			short = "工匠区位于达纳苏斯的北部，它专门用于贸易，而不是战争或崇拜。城中的工匠们在这里开设店铺，疲惫的旅人可以在达纳苏斯的一家旅店中歇脚。",
			full = "工匠区位于达纳苏斯的北部，它专门用于贸易，而不是战争或崇拜。城中的工匠们在这里开设店铺，疲惫的旅人可以在达纳苏斯的一家旅店中歇脚。银色黎明的一座使馆也坐落在这里，这是一个获准在这座精灵城市中占有一席之地的外来机构。\n\n工匠区南面与战士区相邻，西面与塞纳里奥区相邻。",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "神殿花园",
			short = "在达纳苏斯的中心坐落着神殿花园，这是一片由水面、步道和小岛组成的开阔区域，得名于就在它南面耸立的宏伟的月神殿。",
			full = "在达纳苏斯的中心坐落着神殿花园，这是一片由水面、步道和小岛组成的开阔区域，得名于就在它南面耸立的宏伟的月神殿。桥梁向四面八方伸展，北面连接塞纳里奥区，东面连接工匠区、战士区和贸易区，南面连接月神殿，因此穿过这座城市的所有道路似乎都在这里汇聚。\n\n最大的岛上坐落着城中的银行，花园西缘的一座传送门可以通往世界之树脚下的鲁瑟兰村，这使得这片由水与石构成的宁静中心，同时也成了达纳苏斯与外面世界之间的门槛。",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "贸易区",
			short = "贸易区坐落在达纳苏斯的南部，店主们在这里摆开摊位，商人们聚集在这里讨价还价，使这里成为整座城市的商业中心。",
			full = "贸易区坐落在达纳苏斯的南部，店主们在这里摆开摊位，商人们聚集在这里讨价还价，使这里成为整座城市的商业中心。它的北面通向战士区，西面的小路则通往月神殿和神殿花园。\n\n它的建筑以暗夜精灵的方式由木头生长而成，轻盈而优雅。",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "战士区",
			short = "战士区守着达纳苏斯的东门，城市在这里向泰达希尔的荒野敞开。",
			full = "战士区守着达纳苏斯的东门，城市在这里向泰达希尔的荒野敞开。哨兵们在这里驻守，任何想要拿起武器为这座城市效力的暗夜精灵都会来到这里，在靶场和决斗场上苦练，直到他们的技艺足以应付战争。\n\n骑着夜刃豹的骑手们沿着城门守望，这片区域是城市的盾牌，抵御着任何可能从森林沿路而来的暴力。\n\n它北面与工匠区相邻，南面与贸易区相邻，西面与神殿花园相邻，因此在这里训练的战士，与城中的工匠、商人和牧师都近在咫尺。",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- 幽暗城: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "洛丹伦废墟",
			short = "在这座地下城市的上方，洛丹伦的王宫依然矗立，大厅向天空敞开，花园已经荒芜。联盟的伟大王国就在这里消亡，而它的幽魂也从未真正离开过这里。",
			full = "在这座地下城市的上方，洛丹伦的王宫依然矗立，大厅向天空敞开，花园已经荒芜。联盟的伟大王国就在这里消亡，而它的幽魂也从未真正离开过这里。\n\n终结它的正是阿尔萨斯·米奈希尔。这位王子率领着一支为对付他自己的人民而组建的军队回到了家乡，在任何人明白他变成了什么之前，人们用钟声和欢呼声迎接他穿过了这些大门。他看到他的父亲泰瑞纳斯国王正在王座厅中等候，便在那里杀死了他。他站在尸体旁说出的话，至今仍在那间大厅里回荡，传入任何在那里逗留的人耳中：这个王国将会覆灭，而一个新的秩序将从它的灰烬中崛起，撼动整个世界。这并不是一句空洞的狂言。短短几天之内，这座城市和它的人民惨遭屠戮，洛丹伦从此归属于天灾军团。\n\n据说，如果如今在庭院中漫步，仍能听到石头所记得的声音：低沉的私语，迎接的钟声，还有王座厅中那从未真正消散的喃喃低语。那些能够看透帷幕的人说，洛丹伦的市民仍在那里行走，却浑然不知他们的王国早已不复存在。",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}

